[33419] = { ["id"] = 33419, ["name"] = "A Matter of Life and Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["storyline"] = { 33419 }, ["description"] = "Stranger, please help me! My companions and I ventured here to seek the bounty on a monstrous wasp queen. After we set up camp down the hill, we fell asleep. We were attacked in the middle of the night by these horrid, pale... things! I don't know where my friends have gone, but I heard screams from further down the cavern. Please, find my companions. I can't leave here without them!", ["objectivesText"] = "Find Arekk , Diaani , and Zuulo in Bloodthorn Cave. Progress: They told us not to come out here, but we didn't listen. Why didn't we listen!?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6719 } }, ["questType"] = "standard" },
