[33427] = { ["id"] = 33427, ["name"] = "Ours is the Fury", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 32979, 32980, 32983, 32984, 32985, 33427, 33444 }, ["series"] = { 32979, 32980, 32983, 32984, 32985, 33444 }, ["description"] = "Drek'Thar will be fine, once he adjusts. The vision the elemental has bestowed upon him is powerful, and he is on the path of becoming this world's greatest shaman. You may wish to inform Warmaster Zog in your garrison of what has transpired here. He should be able to deploy some of your troops to the area to further secure the area.", ["objectivesText"] = "Speak with Warmaster Zog at your Garrison in Frostfire Ridge.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 119145 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 76622, ["x"] = 0.7, ["y"] = 0.382 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.382 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 590, ["questLines"] = { { ["id"] = 117, ["name"] = "Garrison Campaign", ["orderIndex"] = 5, ["flags"] = 0 } } },
