[33513] = { ["id"] = 33513, ["name"] = "Blackthorn's Lieutenants", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 722, ["storyline"] = { 33513 }, ["description"] = "Amnennar's reincarnation is imminent. In order to protect the ceremony Death Speaker Blackthorn has placed his most trusted lieutenants between us and him. Aarux , a plagued spider nests near his young, tended to by the Death's Head Aranomancers. Mordresh rallies Amnennar's forces upon the Bone Pile. Finally, Mushlump stands guarding the entrance to the Spiral of Thorns. Once you defeat these guardians I will join you and together we will confront Blackthorn.", ["objectivesText"] = "Kill Aarux , Mordresh, and Mushlump . Progress: Have you cleared the way?", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 722 } }, ["questType"] = "dungeon" },
