[33944] = { ["id"] = 33944, ["name"] = "And the Elekk Too?!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33944 }, ["description"] = "The little stuffed elekk has seen better days. It's torn and the stuffing is poking out. The name Caleb is sewn onto the bottom of the left back foot. Sher'khaan must have snatched it from the cart. The little draenei might appreciate its return.", ["objectivesText"] = "Return Ricky to Caleb at the overturned cart. Progress: Where did you find Ricky ?!", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 37829, 108747, 116662 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 76826, ["x"] = 0.362, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
