[34192] = { ["id"] = 34192, ["name"] = "Things Are Not Goren Our Way", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 34192 }, ["description"] = "The abandoned mine shaft has been overrun with goren! They seem to be responding to commands from a big one farther down in the mine. If you can take him out, the rest will probably retreat. Once you have those goren cleared out, we can get that mine up and working!", ["objectivesText"] = "Kill Stonetooth in the Garrison Mine. Progress: Were you able to take out the leader?", ["rewardGold"] = 169800, ["rewardXP"] = 2090, ["rewardItems"] = { 109576, 111996, 116248, 116249, 248660 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[34193] = { ["id"] = 34193, ["name"] = "Clearing the Garden", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 34193 }, ["description"] = "This cave is the perfect climate to grow herbs for our Garrison, there is just one little problem. All these damn nibblers! I need you to clear them out and we can get this garden growing.", ["objectivesText"] = "Kill 8 Frostwall Nibblers . Progress: Did you get em?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 32572, 116053, 118595, 120945 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[34194] = { ["id"] = 34194, ["name"] = "Looking For Help", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 539, ["storyline"] = { 34194 }, ["series"] = { 36199, 36201, 36202 }, ["description"] = "We have an accessible fishing spot here, but no bait seems to work! We need to find a local fisherman with some knowledge of the area to help us out. Head northwest and see if you can find anyone on the shoreline.", ["objectivesText"] = "Find a local fisherman to help our cause. Progress: Find anyone?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 114873, 114874, 114876 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84372, ["x"] = 0.27, ["y"] = 0.065 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.065 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 7078 } }, ["questType"] = "standard" },
