[34209] = { ["id"] = 34209, ["name"] = "Vouchsafe Our Arrival", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 34209, 34216, 34227, 34230, 34280, 34291, 34294, 34295 }, ["series"] = { 34216, 34227 }, ["description"] = "A matter of great importance has arisen. While you were away, Archmage Khadgar contacted me. He is investigating demonic influences to the north. Being a human, the Frostwolves will not accept Khadgar without you there to vouch for him, nor will they accept a night elf such as myself. I will wait for you outside Throm'var in the Frostwind Crag.", ["objectivesText"] = "Meet Cordana Felsong outside of Thom'var in the Frostwind Crag.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 72814, ["x"] = 0.314, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 58, ["name"] = "On the Shadow's Trail", ["orderIndex"] = 0, ["flags"] = 0 } } },
