[34211] = { ["id"] = 34211, ["name"] = "Treasure: Gorgrond Treasure 20", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 34211 }, ["rewardGold"] = 171000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[34213] = { ["id"] = 34213, ["name"] = "They Have My Son", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 34213 }, ["description"] = "Please, $p! Can you help me. I received a ransom note from a very corrupt and uncouth orc within the ranks of the Iron Horde. He has my son! He made sure to include a number of graphic words to describe what would happen if the ransom is not paid. Clearly he thinks my people conjure gold from the nether. And if I try to rescue him myself, both of us will be killed in the process. Can you go to Gron'mar for me and rescue my son? His name is Corki .", ["objectivesText"] = "Find the Key to Corki's Cage and set him free.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 109592 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[34214] = { ["id"] = 34214, ["name"] = "Treasure: Gorgrond Treasure 21", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 34214 }, ["rewardGold"] = 171000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[34215] = { ["id"] = 34215, ["name"] = "Treasure: Gorgrond Treasure 22", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 34215 }, ["rewardGold"] = 171000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[34216] = { ["id"] = 34216, ["name"] = "Safe Passage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34209, 34216, 34227, 34230, 34280, 34291, 34294, 34295 }, ["series"] = { 34209, 34227 }, ["description"] = "Being a human and a night elf, the archmage and I aren't likely to be well-received by the orcs of the Frostwolf clan. We need you to make an introduction for us with the Throm'var farseer. There is much to discuss. Shall I bring you up to speed on the way to the village?", ["objectivesText"] = "Hear Cordana Felsong 's tale. Progress: You honor us with your presence.", ["rewardGold"] = 16980, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 72814, ["x"] = 0.314, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 72837, ["x"] = 0.318, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 58, ["name"] = "On the Shadow's Trail", ["orderIndex"] = 1, ["flags"] = 0 } } },
[34217] = { ["id"] = 34217, ["name"] = "Smash Blon'sky!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 34217 }, ["description"] = "Grulk not choose to be mutated. Grulk not monster like Blon'sky ! Blon'sky evil... chose mutation for power! You go to Grommar? Smash Blon'sky before he hurt innocents, make Grulk happy!", ["objectivesText"] = "Defeat Blon'sky .", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[34218] = { ["id"] = 34218, ["name"] = "Treasure: Gorgrond Treasure 23", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 34218 }, ["rewardGold"] = 171000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
