[34450] = { ["id"] = 34450, ["name"] = "Rylak Rescue", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34353, 34354, 34355, 34365, 34397, 34450, 35861 }, ["series"] = { 34352, 34353, 34355, 34365, 34397, 35861, 35876 }, ["description"] = "I managed to squeeze even more information out of our little friend here. The Darktide Matriarch is at the top of the hill. One of their lead engineers is attempting to tame the matriarch with his technology. We must stop him, <name>.", ["objectivesText"] = "Kill Razz Ricketroz at Darktide Roost.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 116978, 119130 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 78258, ["x"] = 0.58, ["y"] = 0.938 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 78937, ["x"] = 0.678, ["y"] = 0.9 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.938 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 100, ["name"] = "Garrison Campaign", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 110, ["name"] = "Garrison Campaign", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34455] = { ["id"] = 34455, ["name"] = "Free their Minds", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 34455 }, ["description"] = "This device is what the goblins are using to control the rylaks. There is a button on the controller labeled do not touch. Get within range of a Controlled Rylak and touch the button.", ["objectivesText"] = "Use the Rylak Mind Controller on Controlled Rylaks.", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["rewardItems"] = { 110447 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 89158, ["x"] = 0.598, ["y"] = 0.945 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
