[34463] = { ["id"] = 34463, ["name"] = "Mysterious Ring", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 535, ["storyline"] = { 34463 }, ["series"] = { 34464, 34465, 34466, 34472 }, ["description"] = "This elegantly crafted ring is covered in ornate decorations and symbols, the most prominent of which being the letter \"V\" in a glowing rune. The ring seems to fade in and out of view as if passing back and forth through time. Someone at Khadgar's Tower may have an interest in such an artifact.", ["objectivesText"] = "Bring the Mysterious Ring to Zooti Fizzlefury at Khadgar's Tower in Talador. Progress: Time magic is a young field of research.", ["rewardGold"] = 561800, ["rewardXP"] = 1365, ["rewardItems"] = { 110459 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 86949, ["x"] = 0.85, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.85, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[34464] = { ["id"] = 34464, ["name"] = "Mysterious Boots", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 535, ["storyline"] = { 34464 }, ["series"] = { 34463, 34465, 34466, 34472 }, ["description"] = "Phasing back and forward in time, these flickering ornate boots are adorned with a lavish \"V\" on them. Someone at Khadgar's Tower might have insights to the nature of these strange items.", ["objectivesText"] = "Bring the Mysterious Boots to Zooti Fizzlefury at Khadgar's Tower in Talador. Progress: I was wondering \"when\" I would see you again. Ah...? Ah...? Get it? Look, for as long as anyone was speaking the bronze dragons got to hog all of the good time jokes. Well now the guardians of time are taking a break and there is no one left to stop me!", ["rewardGold"] = 561800, ["rewardXP"] = 1365, ["rewardItems"] = { 110469 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 86949, ["x"] = 0.85, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.85, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[34465] = { ["id"] = 34465, ["name"] = "Mysterious Hat", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34465 }, ["series"] = { 34463, 34464, 34466, 34472 }, ["description"] = "Energy flows from this mystical hat with an unseen strength. It hums as it drifts back and forward in time where it rests on the ground. This is the sort of object that someone at Khadgar's Tower would find very interesting.", ["objectivesText"] = "Bring the Mysterious Hat to Zooti Fizzlefury at Khadgar's Tower in Talador. Progress: It is so nice to finally be able to research my passion without those interfering bronze dragons showing up.", ["rewardGold"] = 561800, ["rewardXP"] = 1365, ["rewardItems"] = { 110470 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 86949, ["x"] = 0.85, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.85, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34466] = { ["id"] = 34466, ["name"] = "Mysterious Staff", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 535, ["storyline"] = { 34466 }, ["series"] = { 34463, 34464, 34465, 34472 }, ["description"] = "Fluctuations in reality surround this staff so much that it is hard to identify any recognizable markings aside from a large, lavish \"V\" on its apex. This might require help to identify by someone from Khadgar's Tower.", ["objectivesText"] = "Bring the Mysterious Staff to Zooti Fizzlefury at Khadgar's Tower in Talador. Progress: I did my time with fire and the other arcane arts. They were good. Nothing compares to hurling a giant ball of fire. But temporal wizardry? So much fun! Really hard to master but you always have plenty of time.", ["rewardGold"] = 561800, ["rewardXP"] = 1365, ["rewardItems"] = { 110471 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 86949, ["x"] = 0.85, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.85, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34469] = { ["id"] = 34469, ["name"] = "Cleansing the Souls", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34309, 34314, 34315, 34316, 34318, 34319, 34381, 34469 }, ["series"] = { 34309, 34314, 34315, 34316, 34318, 34319, 34381 }, ["description"] = "Not all spirits are destroyed by the Soulgrinder. Some souls manage to survive more or less intact like myself. Others have become twisted and maddened. End their misery, take my soul shard and use it to purify them. Their rage will blind them to the effects of its energy so you must defeat them before you use it.", ["objectivesText"] = "Cleanse 10 Crazed Souls.", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["rewardItems"] = { 110378, 110394, 110606, 110607, 110608, 110664 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78428, ["x"] = 0.395333, ["y"] = 0.234667 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78428, ["x"] = 0.395333, ["y"] = 0.234667 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.395333, ["y"] = 0.234667 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525, ["questLines"] = { { ["id"] = 115, ["name"] = "Garrison Campaign", ["orderIndex"] = 7, ["flags"] = 0 } } },
[34472] = { ["id"] = 34472, ["name"] = "Temporal Juxtaposition", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34472 }, ["series"] = { 34463, 34464, 34465, 34466 }, ["description"] = "I think I figured out what those mysterious artifacts you collected were for. It would seem someone is attempting to affect a temporal shift by sending items back into this timeline from your own timeline. Technically that shouldn't be possible. But whoever this is found a way. I think I may try a ritual to bring the traveler through.", ["objectivesText"] = "Wait for Zooti Fizzlefury 's temporal ritual to complete.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 86949, ["x"] = 0.85, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 77853, ["x"] = 0.845333, ["y"] = 0.315333 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.85, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
