[34512] = { ["id"] = 34512, ["name"] = "Declawing The Competition", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34512 }, ["description"] = "These saberon freaks have cost me a lot of money, <class>. I'm not one to forgive a debt and it's time to collect! The saberon that have been causing us the most trouble are the ones living in Sabermaw. They keep ambushing our trade shipments along the road. <Pyxni grins.> It's time to declaw the competition. Bring me their claws; we'll sell the best ones as good luck charms here at the arena. If the claw sales don't cover their debt, we'll just have to charge them an arm and a leg too!", ["objectivesText"] = "Collect 10 Saberon Claws . Progress: Do you have the saberon claws I asked for?", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 110714 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79310, ["x"] = 0.786, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79310, ["x"] = 0.786, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.786, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34513] = { ["id"] = 34513, ["name"] = "WANTED: Razorpaw!", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34513 }, ["description"] = "Wanted for crimes against the innocent at the Ring of Trials! Razorpaw is responsible for leading several raids and ambushes against travelers on the road near Sabermaw. Last seen in the vicinity of the saberon den known as Sabermaw. Exercise extreme caution! Upon completion, this bounty will be fulfilled by Pyxni Pennypocket of the Steamwheedle Cartel.", ["objectivesText"] = "Defeat Razorpaw .", ["rewardGold"] = 561800, ["rewardXP"] = 5990, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79310, ["x"] = 0.786, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.786, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34514] = { ["id"] = 34514, ["name"] = "They've Got The Goods!", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34514 }, ["description"] = "The Saberon...they weren't just after prisoners... <Cough>...they took all the merchandise too. Kidnapping is one thing...but stealing a goblin's merchandise? That's making things personal! <Cough>...Pyxni ain't going to be happy unless you get all of the stolen goods back. Make your way into Sabermaw and steal back all our merch. When you're done, make your way back to Pyxni at the Ring of Trials. She'll make it worth your while...", ["objectivesText"] = "Recover 10 Stolen Goods . Progress: Greexlex told you that the saberon stole our merchandise? Well, what are you standing around for? Get your butt over to Sabermaw and get it back! Time is money!", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 110719 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79312, ["x"] = 0.79, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79310, ["x"] = 0.786, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34515] = { ["id"] = 34515, ["name"] = "Gobnapped", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34515 }, ["description"] = "We never even saw the ambush coming... The saberon hit us so hard and fast we barely had time to think. Those overgrown mongrels dragged the others away and left me here for dead...they probably thought I was too close to dying. I hear they like their meat fresh... <cough>....well I ain't going down that easy! Don't worry about me...<cough>...I've been through worse! You're gonna have to go to Sabermaw and get the other merchants out though. They've probably got 'em all caged up in there...", ["objectivesText"] = "Rescue 6 Goblin Traders.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 114880, 114881, 114882 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79312, ["x"] = 0.79, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79310, ["x"] = 0.786, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34516] = { ["id"] = 34516, ["name"] = "My Precious!", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34516 }, ["description"] = "You've got to help me! I was hiding on the trade wagon that got ambushed just down the road from here. I snuck away before the saberon spotted me...but...but... THEY STOLE MY MOST PRIZED POSSESSION! You've got to help me get it back! I watched them drag it into Sabermaw and up that giant hill! Who knows what those filthy saberon will do to it! Please, I'm just a kid! You've got to help me out, right?", ["objectivesText"] = "Find Bazwix 's stolen treasure.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 4907, 5395, 11189, 39781, 39803, 39805, 39842, 63770, 63771, 63773, 63774, 131705, 140241, 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187328, 187334, 187336, 187466, 211279, 223951, 237812, 258023 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79897, ["x"] = 0.748, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
