[34720] = { ["id"] = 34720, ["name"] = "Operation: Just Arrowhead", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34720 }, ["description"] = "It goes without saying that the Warsong in Telaar need to be dealt with. Rangari Ogir and his forces on the overlook will help you kill any of the orcs that are out in the open. You just start the fight, and they'll end it with extreme prejudice.", ["objectivesText"] = "Kill 15 Warsong forces at Telaar.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79576, ["x"] = 0.635, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79576, ["x"] = 0.635, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
