[34735] = { ["id"] = 34735, ["name"] = "Thunderlord Invasion!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 34735 }, ["description"] = "Sir! Scouts have spotted Thunderlords approaching from the east. The men are armed and ready. We'll mount defensive positions as soon as you take the field.", ["objectivesText"] = "Speak with Legionaire Grimjaw in your garrison.", ["rewardGold"] = 228000, ["rewardXP"] = 250, ["rewardItems"] = { 110560 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[34736] = { ["id"] = 34736, ["name"] = "We Be Needin' Supplies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 34736 }, ["description"] = "Commander, our forces are not prepared for frost fightin'. I took da liberty and sent some of our shadow hunters north to establish a supply base. Ya might want to be headin' up dere and see what they be up to. Look for a hollow between the Crackling Plains and the Savage Crag.", ["objectivesText"] = "Speak with Shadow Hunter Rala at Darkspear's Edge.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78208, ["x"] = 0.526, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[34751] = { ["id"] = 34751, ["name"] = "Clear!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34751 }, ["description"] = "You gotta help me fix this robot. I'm friggin' hungry! I built the Pleasure-Bot 8000 to locate Draenor truffles, and what does it do? It swims to this stupid island and shorts its power fluctuator. I got it hooked up to these batteries, but it ain't enough juice to jump it. Be a doll and get me the zapper sacs from the electric eels in the lake, would ya? They oughta be enough.", ["objectivesText"] = "Collect 6 Zapper Sacs from Lakebottom Zappers in Talador . Progress: You got the stuff, buddy?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 26009, 26023, 26035, 59620, 59621, 59622, 59623, 59624, 59625, 81834, 81835, 81836, 81837, 81838, 111637, 112595, 112596, 112597, 112598, 131273, 142279, 142282, 142283, 186601, 197126, 198048, 200454, 204075, 204733, 204735, 204739, 204745, 204746, 204747, 204748, 204749, 204752, 204754, 204755, 204768, 204769, 204776, 204782, 204789, 211279, 237812, 245417, 246815, 246936, 249400, 251821, 254267, 254579, 264675 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79870, ["x"] = 0.642, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79870, ["x"] = 0.642, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34758] = { ["id"] = 34758, ["name"] = "Looking For Help", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 34758 }, ["series"] = { 36131, 36132, 36141 }, ["description"] = "We have an accessible fishing spot here, but no bait seems to work! We need to find a local fisherman with some knowledge of the area to help us out. Head southeast and see if you can find anyone on the shoreline.", ["objectivesText"] = "Find a local fisherman that can help our cause. Progress: You think I am going to help you?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 79896, ["x"] = 0.556, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[34761] = { ["id"] = 34761, ["name"] = "Clear!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34761 }, ["description"] = "Oh, the gnomanity! The Pleasure-Bot 8000 broke before it could bring me a single Draenor truffle. It swam here and shorted its power fluctuator. AGAIN! I have power going to it, but it isn't enough to override the fluctuator. Could you get me the sacs from the electric eels in the lake? I think that would be just the ticket!", ["objectivesText"] = "Collect 6 Zapper Sacs from Lakebottom Zappers in Talador . Progress: Do you have the eel sacs?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 26009, 26023, 26035, 59620, 59621, 59622, 59623, 59624, 59625, 81834, 81835, 81836, 81837, 81838, 111637, 112595, 112596, 112597, 112598, 131273, 142279, 142282, 142283, 186601, 197126, 198048, 200454, 204075, 204733, 204735, 204739, 204745, 204746, 204747, 204748, 204749, 204752, 204754, 204755, 204768, 204769, 204776, 204782, 204789, 211279, 237812, 245417, 246815, 246936, 249400, 251821, 254267, 254579, 264675 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79901, ["x"] = 0.628, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79901, ["x"] = 0.628, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34766] = { ["id"] = 34766, ["name"] = "Logistical Nightmare", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34766 }, ["series"] = { 34803 }, ["description"] = "Commander, I am afraid I have... troubling... news. These saberon followed our encampment from Gorgrond, and have been stealing our supplies, ransacking our ledgers, and slaughtering our peons! I hate to ask of your time to deal with the matter, but all of our men are stationed guarding the camp from any further raids. We desperately need those supplies so we may enact your will!", ["objectivesText"] = "Retrieve 5 Sacks of Supplies and 5 Garrison Records . Progress: Commander! Have you had time to locate our supplies and ledgers?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 111735, 111736 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79921, ["x"] = 0.712, ["y"] = 0.295 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79921, ["x"] = 0.712, ["y"] = 0.295 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[34771] = { ["id"] = 34771, ["name"] = "Good Stuff", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 34771 }, ["rewardGold"] = 154900, ["rewardXP"] = 1045, ["rewardItems"] = { 63164, 63165, 63166, 63167, 63168 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[34773] = { ["id"] = 34773, ["name"] = "Why Is The Brew Gone?", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34773 }, ["series"] = { 34804 }, ["description"] = "Commander, we have a bit of a... uh... problem. This group o' saberon followed us from Gorgrond, and they've been stealin' our footmen's swords an' slaughtering our peasants! I hate to ask fer your time, but all of yer men are guardin' the camp from any further raids. Plus... < Quartermaster O'Riley lowers her voice to a whisper.> They took our beer!", ["objectivesText"] = "Retrieve 5 Footman Longswords and 5 Thunderbrew Kegs . Progress: Commander! Have ye had a moment to deal with the saberon?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 111808, 111809 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 79963, ["x"] = 0.696, ["y"] = 0.215 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79963, ["x"] = 0.696, ["y"] = 0.215 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.215 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
