[34947] = { ["id"] = 34947, ["name"] = "Shredder Manual", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 34087, 34088, 34089, 34090, 34091, 34094, 34095, 34096, 34097, 34098, 34099, 34947, 34959, 34963 }, ["series"] = { 34090, 34091, 34094, 34096, 34097, 34098, 34099, 34963 }, ["description"] = "Hey! I hear there's a curious object nearby. Scouts say it's some kind of shredder manual. Go check it out for me, will ya? I wonder if it has to do with this new prototype I've been hearin' about...", ["objectivesText"] = "Find the Iron Shredder Decommission Orders .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75874, ["x"] = 0.63, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 24, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 5, ["flags"] = 0 } } },
[34948] = { ["id"] = 34948, ["name"] = "Shredder Manual", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33720, 33721, 33722, 33724, 33728, 33729, 33730, 33731, 33735, 33736, 33754, 34948, 34950, 34962, 35226 }, ["series"] = { 33720, 33721, 33724, 33728, 33729, 33730, 33731, 34962 }, ["description"] = "I've been hearing rumors of this new prototype shredder the Iron Horde's engineers have been working on. I think we ought to investigate. A shadow hunter spotted some sort of shredder manual, and it might have something to do with that prototype.", ["objectivesText"] = "Find the Iron Shredder Decommission Orders .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75924, ["x"] = 0.59, ["y"] = 0.206 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.206 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 32, ["name"] = "The Battle for Shattrath", ["orderIndex"] = 6, ["flags"] = 0 } } },
[34953] = { ["id"] = 34953, ["name"] = "Blood of the Burning Blade", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 34953 }, ["description"] = "Hallvalor is the ancestral home of my clan, the Burning Blade. When the new warlord and his family came to power, I was exiled for being a half-breed. I want justice. I suspect you won't mind killing along the way. Not that you'll have any choice.", ["objectivesText"] = "Kill 15 Burning Blade forces at Hallvalor.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 80161, ["x"] = 0.854, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79954, ["x"] = 0.635, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.854, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[34960] = { ["id"] = 34960, ["name"] = "The Land Provides", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 34960 }, ["description"] = "The icevines of the Shivering Trench have developed a powerful resistance to cold temperatures. Integrating them into the construction materials of the garrison should prove useful.", ["objectivesText"] = "Collect 30 Frozen Plant Matter . Progress: Look at you, bein' all resourceful.", ["rewardGold"] = 208560, ["rewardXP"] = 1415, ["rewardItems"] = { 112266 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
