[35254] = { ["id"] = 35254, ["name"] = "Retribution for the Light", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 33530, 33917, 33920, 33958, 33967, 33969, 33976, 33988, 34013, 34092, 34154, 34157, 34163, 34164, 34234, 34240, 34326, 34351, 34407, 34452, 34458, 34508, 35254, 36512 }, ["description"] = "There are agents of darkness everywhere, fighting tooth and nail to envelop the world. The Light relies on us to balance the scale. You have the power needed to destroy Teron'gor's demonic minions once and for all. Send them to the Twisting Nether in pieces!", ["objectivesText"] = "Kill 15 demons in Gul'rok.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75392, ["x"] = 0.43, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75392, ["x"] = 0.43, ["y"] = 0.76 }, { ["mapID"] = 535, ["npcID"] = 77581, ["x"] = 0.456, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 26, ["name"] = "In the Shadows of Auchindoun", ["orderIndex"] = 19, ["flags"] = 0 } } },
