[35337] = { ["id"] = 35337, ["name"] = "That Pounding Sound", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35337 }, ["series"] = { 35350 }, ["description"] = "Commander. The rangari and I were just discussing the merits of various 'hunting' approaches. I assured her that the SI:7 are well-equipped to deal with any situation, even ones out in the wild. She seems to think that we don't know what we're doing when it comes to bringing down game in 'her land.' We're not going to let her get away with saying that, right? Let's take down some clefthoof.", ["objectivesText"] = "Collect 12 Pairs of Leatherhide Ears from Leatherhide clefthoof. Progress: It's unbelievable how arrogant these rangari can be.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 113100, 118135, 118136, 118137, 118187, 118188, 118189 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 82092, ["x"] = 0.635, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82092, ["x"] = 0.635, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35338] = { ["id"] = 35338, ["name"] = "Shooting the Breeze", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35338 }, ["description"] = "Kia and I are having a spirited debate over who kills more efficiently: SI:7 or rangari. Care to get in on the wager, commander? I've been focusing on talbuk because of their fierce majesty. They truly encapsulate the grandeur of Nagrand as any native of Draenor knows.", ["objectivesText"] = "Collect 24 Breezestrider Horns from Breezestrider talbuk. Progress: This outsider really thinks she can come here and best me in my own land? Oh... sorry, commander. Present company excluded, of course.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 113102 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 82094, ["x"] = 0.634667, ["y"] = 0.614667 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82094, ["x"] = 0.634667, ["y"] = 0.614667 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.634667, ["y"] = 0.614667 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35341] = { ["id"] = 35341, ["name"] = "Defection of Gronnstalker Rokash", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 35341 }, ["description"] = "You have done me a great service. This blade is as much yours as it is mine. I offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces. Will you accept it?", ["objectivesText"] = "Accept the Blood Oath of Blademaster Na'Shra.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 79229, ["x"] = 0.594, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.594, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[35342] = { ["id"] = 35342, ["name"] = "The Mysterious Flask", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 35342 }, ["series"] = { 35343, 35344, 35345 }, ["description"] = "The liquid swirling around inside the flask clearly has strong alchemical properties, but its nature is beyond your training. You have heard that one of the Eventide villagers at your garrison has some knowledge of the alchemy of Draenor. Perhaps he could tell you more?", ["objectivesText"] = "Speak to Aenir at your garrison. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 109152, 113103 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard", ["startItems"] = { 113103 } },
[35343] = { ["id"] = 35343, ["name"] = "The Young Alchemist", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 539, ["storyline"] = { 35343 }, ["series"] = { 35342, 35344, 35345 }, ["description"] = "I learned a little about alchemy from my aunt. If you want to know more, though, you should speak with my cousin Abatha . She was apprenticing under my aunt before she passed away. Abatha lives near the Verdant Mire with her father and sister.", ["objectivesText"] = "Find Abatha at the Verdant Mire.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 82497, ["x"] = 0.558, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[35344] = { ["id"] = 35344, ["name"] = "The Missing Father", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 35344 }, ["series"] = { 35342, 35343, 35345 }, ["description"] = "I would be happy to help with your alchemical inquiries, but right now I am worried about my father. It's been quite some time since he went hunting down by the river, but he still hasn't returned home. I need to watch Lumiel. Will you please find him?", ["objectivesText"] = "Find Telos in the Verdant Mire.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 82497, ["x"] = 0.558, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 82496, ["x"] = 0.54, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[35345] = { ["id"] = 35345, ["name"] = "Shocking Assistance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 35345 }, ["series"] = { 35342, 35343, 35344 }, ["description"] = "It's been a struggle to support the family since my wife died, and I got too ambitious when I got a contract for shockscales . Alas, there is no way I will hunt enough eels to fulfill it in time now.", ["objectivesText"] = "Collect 100 Shockscales from Shockscale eels. Progress: Thank you so much for finding my father.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 109558, 111812, 113248 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 82496, ["x"] = 0.54, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 82497, ["x"] = 0.558, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
