[35350] = { ["id"] = 35350, ["name"] = "Queen of the Clefthoof", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35350 }, ["series"] = { 35337 }, ["description"] = "Laara told me that they have Banthar here! Or rather, that she's still alive back now. Did what I just said make any sense? This is our chance, commander. We can defeat a younger, more powerful version of Banthar and really stick it to these rangari. We'll show Laara how a true professional works.", ["objectivesText"] = "Collect the Horn of Banthar from Banthar. Progress: Banthar's horn. Hemet would be green with envy to have another shot at such a powerful beast.", ["rewardGold"] = 561800, ["rewardXP"] = 5990, ["rewardItems"] = { 113105 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 82092, ["x"] = 0.635, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82092, ["x"] = 0.635, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
