[35357] = { ["id"] = 35357, ["name"] = "King of the Breezestriders", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35357 }, ["series"] = { 35356 }, ["description"] = "Let me guess, you found it in a talbuk's flank? <Laara seems lost in thought for a moment.> That arrow was intended for Tall Buck, king of the Breezestriders. Another talbuk - the one you killed - jumped in the way as I was taking my shot. I suggest you go after the king. When I was hunting him, he seemed fond of the pond at Lonely Falls to the south.", ["objectivesText"] = "Collect Tall Buck's Tail from Tall Buck. Progress: How goes the hunt for Tall Buck?", ["rewardGold"] = 561800, ["rewardXP"] = 5990, ["rewardItems"] = { 113104, 114695, 114696, 114697, 114698 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 82094, ["x"] = 0.634667, ["y"] = 0.614667 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 82094, ["x"] = 0.634667, ["y"] = 0.614667 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.634667, ["y"] = 0.614667 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
