[35619] = { ["id"] = 35619, ["name"] = "Pinchwhistle Gearworks", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35619 }, ["series"] = { 35077, 35080, 35082, 35620, 36861, 36862 }, ["description"] = "Commander, a goblin courier arrived this morning. He mentioned that he is from a settlement to the southeast called the Pinchwhistle Gearworks. They have requested our assistance with some sort of ecological disaster. If we can earn their trust it'll be worth the effort. Head down there and see what sort of assistance we can provide. I've already spoken to the flight master and he's set up a special flight to get you out there.", ["objectivesText"] = "Speak to Firn Swiftbreeze to secure a flight to the Pinchwhistle Gearworks.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 111957, 112634, 112683, 112698, 112906, 115475, 115533 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 85550, ["x"] = 0.396, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81109, ["x"] = 0.614, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[35620] = { ["id"] = 35620, ["name"] = "Pinchwhistle Gearworks", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35620 }, ["series"] = { 35077, 35080, 35082, 35619, 36861, 36862 }, ["description"] = "Commander, a courier arrived this morning. He said he's from a goblin settlement to the southeast called the Pinchwhistle Gearworks. They've asked for our assistance with some sort of ecological disaster. We're spread thin but if we can earn their trust then we might be able to gain a valuable ally. Head down there and see what sort of assistance we can provide. I've already spoken to the flight master and he's set up a special flight to get you out there.", ["objectivesText"] = "Speak to Hutou Featherwind to secure a flight to the Pinchwhistle Gearworks.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 85566, ["x"] = 0.4, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81109, ["x"] = 0.614, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
