[35640] = { ["id"] = 35640, ["name"] = "Vengeance for the Fallen", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35640 }, ["description"] = "I... almost made it out. Most of us... dead. The others... they are no longer themselves. These lurching spore beasts are the cause, dragging us further into the marsh... stop them.", ["objectivesText"] = "Kill 7 Fungal Lurchers .", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82499, ["x"] = 0.595, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82476, ["x"] = 0.582, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
