[35642] = { ["id"] = 35642, ["name"] = "Mysterious Pod", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35642 }, ["description"] = "This pod is similar to the ones growing on or near the bodies around here, except this one is pulsating weirdly. This is something Khaano would be interested in.", ["objectivesText"] = "Bring the Glowing Red Pod to Khaano at Crimson Fen in Gorgrond . Provided item:", ["rewardGold"] = 210675, ["rewardXP"] = 1045, ["rewardItems"] = { 113260 }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82476, ["x"] = 0.582, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard", ["startItems"] = { 113260 } },
[35644] = { ["id"] = 35644, ["name"] = "Mercy for the Living", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35644 }, ["description"] = "You can see that the dead were the lucky ones. Those that live wander about attacking anything not infected with these vile spores. I cannot bring myself to slay them, but if you could bring mercy to those poor people I would be very grateful.", ["objectivesText"] = "Kill 6 Fungus Covered Shamblers .", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 112595, 112596, 112597, 112598, 113260 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82476, ["x"] = 0.582, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82476, ["x"] = 0.582, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[35645] = { ["id"] = 35645, ["name"] = "The Secret of the Fungus", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35645 }, ["description"] = "I'm beginning to sense a strong... connection... between the fungus and the creatures that inhabit it. There are certain mushrooms that are stronger than others. I believe if I had some samples of these I could use them, track the source of this foul fungus and... deal with it.", ["objectivesText"] = "Collect 5 Glowing Mushrooms . Progress: Where are my mushrooms?!", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 112672, 113260 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82476, ["x"] = 0.582, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82476, ["x"] = 0.582, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[35647] = { ["id"] = 35647, ["name"] = "A Grim Harvest", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35647 }, ["description"] = "The spores grow thick further into the marsh, but those larger fungus beasts are the key. Yes, kill them and take their spore sacs. I will need them to refine my... search.", ["objectivesText"] = "Bring Khaano 3 Spore Pods from the Fungal Stompers. Progress: Those pods are critical <name>, I need them!", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["rewardItems"] = { 112394 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82476, ["x"] = 0.582, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82476, ["x"] = 0.582, ["y"] = 0.598 }, { ["mapID"] = 543, ["npcID"] = 82477, ["x"] = 0.59, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
