[35653] = { ["id"] = 35653, ["name"] = "Wood is Wood", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["storyline"] = { 35653 }, ["description"] = "Them ancients in Bracken Tangle be crazier than a dwarf who don't like gold. The burn their leaves right off their 'eads and make their bark hard to fire. Ya know, that bark might come in 'andy 'round here. Chop down a few ancients and I'll send a lackey to gather their wood.", ["objectivesText"] = "Kill 6 Emberbark Ancients .", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 37942, 37985, 38029, 38093, 60931, 60932, 60933, 112616, 112617, 112618, 112619, 131582, 198607, 211279, 232875, 237812, 242241, 264914 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[35656] = { ["id"] = 35656, ["name"] = "A Heartfelt Search", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35656 }, ["description"] = "I can feel a powerful presence in the marsh $p, it is not far from here. Go see what is there while I finish my grim feast. I will catch up...", ["objectivesText"] = "Investigate the strange presence in the Crimson Fen.", ["rewardGold"] = 421350, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82476, ["x"] = 0.582, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82477, ["x"] = 0.59, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[35659] = { ["id"] = 35659, ["name"] = "Heart of the Fen", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35659 }, ["description"] = "The pounding in my head is almost unbearable but I must see this through. With all the spore samples I've taken I know where to go and what to do. I will find the source and spread... no! Destroy it! I will do what needs to be done!", ["objectivesText"] = "Follow Khaano deeper into the Crimson Fen and deal with what comes.", ["rewardGold"] = 842700, ["rewardXP"] = 2615, ["rewardItems"] = { 112603, 112604, 112605, 112606 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82477, ["x"] = 0.59, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 75146, ["x"] = 0.583, ["y"] = 0.561 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[35663] = { ["id"] = 35663, ["name"] = "A Lesson in Teamwork", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 35663 }, ["description"] = "One of the most important skills an archaeology team needs is good teamwork. The key to teamwork is knowing when to give and when to take. The Highmaul ogres have been excavating mysterious artifacts from the gorge. I want you to team up with the Highmaul ogres in the name of good archaeology! Remember what I said about giving and taking? The ogres have given us their hard work to excavate the artifacts. Now I want you to take those artifacts from them and bring them here! It's teamwork!", ["objectivesText"] = "Retrieve 10 Mysterious Artifacts . Progress: Have you retrieved the mysterious artifacts ? It's all about teamwork!", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 113272, 114887, 114888, 114890, 122457 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 79201, ["x"] = 0.712, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79201, ["x"] = 0.712, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[35666] = { ["id"] = 35666, ["name"] = "Rangari in the Red", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35666 }, ["series"] = { 35633 }, ["description"] = "Gorgrond is a very dangerous place and I've sent scouting squads out to investigate various regions. I've sent one squad to the marsh called the Crimson Fen and they've not come back yet. I'd like you to find the missing squad and get a report if possible.", ["objectivesText"] = "Find Khaano near the Crimson Fen in Gorgrond .", ["rewardGold"] = 210675, ["rewardXP"] = 1045, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 75146, ["x"] = 0.583, ["y"] = 0.561 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 80762, ["x"] = 0.592, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.583, ["y"] = 0.561 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[35667] = { ["id"] = 35667, ["name"] = "Skulltakers in Crimson Fen", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 35667 }, ["description"] = "Grulkor and his group are often not seen for weeks, returning only when they can carry no more trophies and supplies. He has been gone too long this time. He mentioned hunting in the Crimson Fen for the first time, see if he still lives.", ["objectivesText"] = "Find Grulkor near the Crimson Fen in Gorgrond .", ["rewardGold"] = 210675, ["rewardXP"] = 1045, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82732, ["x"] = 0.462, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 81218, ["x"] = 0.544, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[35669] = { ["id"] = 35669, ["name"] = "WANTED: Keeho's Severed Paw", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35669 }, ["description"] = "Posted by: Taskmaster Gornek The saberon known as Keeho poses a serious threat to Axefall. He has taken to slaughtering peons on the night shift and dragging their corpses to his den in the pridelands. Anyone who can bring me his severed paw as proof of his demise will be rewarded greatly.", ["objectivesText"] = "Retrieve Keeho's Severed Paw from Keeho the Savage. Progress: Lok'tar, commander.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 113292 }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81920, ["x"] = 0.402, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "group" },
[35670] = { ["id"] = 35670, ["name"] = "WANTED: Spineslicer's Husk", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35670 }, ["description"] = "Posted by: Killga I will greatly reward anyone who brings me Spineslicer's husk . I wish to fashion fine ravager armor, but do not have the skills to take down such a beast. Don't tear too many holes in it.", ["objectivesText"] = "Retrieve Spineslicer's Husk from Spineslicer. Progress: It is an honor to have you in my shop, commander.", ["rewardGold"] = 339600, ["rewardXP"] = 5145, ["rewardItems"] = { 113293 }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82622, ["x"] = 0.41, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "group" },
[35672] = { ["id"] = 35672, ["name"] = "WANTED: Venombarb", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35672 }, ["description"] = "Posted by: Hutou Featherwind Venombarb is feared in the skies above Arak, even by the high arakkoa. She has made air travel difficult for our riders, preventing vital supplies from reaching Axefall. I require no proof of her demise, simply ensure her screech never again echoes among the spires. She nests above the howling crag to the northeast.", ["objectivesText"] = "Kill Venombarb .", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82612, ["x"] = 0.395, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "group" },
[35674] = { ["id"] = 35674, ["name"] = "WANTED: Keeho's Severed Paw", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35674 }, ["description"] = "Posted by: Lieutenant Willem Keeho, a monstrous saberon, has taken to raiding Southport at night. We're losing men left and right. I offer a hefty bounty to anyone able to track down Kreeho and bring his severed paw to me.", ["objectivesText"] = "Retrieve Keeho's Severed Paw from Keeho the Savage. Progress: Pleasure to see you, sir.", ["rewardGold"] = 663400, ["rewardXP"] = 5145, ["rewardItems"] = { 113292 }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 81929, ["x"] = 0.398, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "group" },
[35675] = { ["id"] = 35675, ["name"] = "WANTED: Spineslicer's Husk", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35675 }, ["description"] = "Posted by: Quartermaster Jolie We're running out of supplies to repair our troops' armor. I'll pay handsomely for the husk of the mighty ravager Spineslicer. It would provide us with repair materials for weeks.", ["objectivesText"] = "Retrieve Spineslicer's Husk from Spineslicer. Progress: Oh, commander! What an honor! How can I help you?", ["rewardGold"] = 573000, ["rewardXP"] = 5145, ["rewardItems"] = { 113293 }, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82664, ["x"] = 0.394, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "group" },
[35676] = { ["id"] = 35676, ["name"] = "WANTED: Venombarb", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 35676 }, ["description"] = "Posted by: Falrogh Venombarb taunts me every day. Screeching and killing me buzz. Somebody, anybody, kill the beast. I don't want proof, I want peace and quiet.", ["objectivesText"] = "Kill Venombarb .", ["rewardGold"] = 339600, ["rewardXP"] = 5145, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 82669, ["x"] = 0.392, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "group" },
[35679] = { ["id"] = 35679, ["name"] = "Garrison Campaign: The Fall of Shattrath", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 535, ["storyline"] = { 35679, 35683, 35685 }, ["description"] = "Greetings, <name>. I bring another message from Archmage Khadgar. We can no longer ignore Socrethar's presence at Shattrath. He spreads dangerous beliefs, converting more draenei to his \"new order\" with each passing day. The time has come for us to confront him. Exarch Maladaar should be expecting you at the Spire of Light in Talador. Good luck, <name>.", ["objectivesText"] = "Speak to Exarch Maladaar at the Spire of Light in Talador.", ["rewardGold"] = 140450, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75028, ["x"] = 0.498, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 101, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35680] = { ["id"] = 35680, ["name"] = "Garrison Campaign: The Fall of Shattrath", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 535, ["storyline"] = { 35680, 35684, 35687 }, ["description"] = "Greetings, <name>. I bring another message from Archmage Khadgar. We can no longer ignore Socrethar's presence at Shattrath. He spreads dangerous beliefs, converting more draenei to his \"new order\" with each passing day. The time has come for us to confront him. Lady Liadrin should be expecting you at the Spire of Light in Talador. Good luck, <name>.", ["objectivesText"] = "Speak to Lady Liadrin at the Spire of Light in Talador.", ["rewardGold"] = 140450, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 76804, ["x"] = 0.5, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 111, ["name"] = "Garrison Campaign", ["orderIndex"] = 0, ["flags"] = 0 } } },
[35683] = { ["id"] = 35683, ["name"] = "Reclaiming the City", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 35679, 35683, 35685 }, ["description"] = "The Shattrath offensive is going well, but Socrethar refuses to show himself. Despite our best efforts, we are unable to break into the inner city of Shattrath. The dome's defenses are simply too strong. However, we think we can lure Socrethar out of hiding. Defeat his lieutenants and warriors, and gather their medallions of service. When we show him proof of their demise, his pride will surely force him to face us.", ["objectivesText"] = "Collect 100 Sargerei Insignias . Progress: What I ask is no easy task, for his scions are formidable. How goes the offensive?", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 113294 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75028, ["x"] = 0.498, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75028, ["x"] = 0.498, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 101, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35684] = { ["id"] = 35684, ["name"] = "Reclaiming the City", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 35680, 35684, 35687 }, ["description"] = "The Shattrath offensive is going well, but Socrethar refuses to show himself. And despite our best efforts, we are unable to break into the inner city, where he resides. However, we think we can lure Socrethar out of hiding. Defeat his lieutenants and warriors, then gather their medallions of service. When we show him proof of their demise, his pride will surely force him to face us.", ["objectivesText"] = "Collect 100 Sargerei Insignias . Progress: What I ask is no easy task, for his followers are formidable. How goes the offensive?", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 113294 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 76804, ["x"] = 0.5, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 76804, ["x"] = 0.5, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 111, ["name"] = "Garrison Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[35685] = { ["id"] = 35685, ["name"] = "Socrethar's Demise", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 35679, 35683, 35685 }, ["description"] = "Meet me down by the entrance to the Shattrath dome. There, we will issue our challenge to the Sargerei leader. If he accepts our challenge, it is there that he shall meet his end. The creature that calls himself Socrethar was once my brethren. I can only hope that there is still some Light left within him.", ["objectivesText"] = "Kill Socrethar .", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 245425, 251330, 251477, 251548, 251549, 251640, 251653, 251654 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 75028, ["x"] = 0.498, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75028, ["x"] = 0.498, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 101, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 } } },
[35687] = { ["id"] = 35687, ["name"] = "Socrethar's Demise", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 35680, 35684, 35687 }, ["description"] = "Meet me down by the entrance to the Shattrath dome. There, we shall issue our challenge to the Sargerei leader. If he accepts, it is there that he shall meet his end. I must admit, <name>, I am looking forward to this.", ["objectivesText"] = "Kill Socrethar . Progress: What is it?", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 76804, ["x"] = 0.5, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 76804, ["x"] = 0.5, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535, ["questLines"] = { { ["id"] = 111, ["name"] = "Garrison Campaign", ["orderIndex"] = 2, ["flags"] = 0 } } },
