[35983] = { ["id"] = 35983, ["name"] = "FLAG: Hansel Event Complete", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 35983 }, ["series"] = { 34440, 34987, 35253, 35297 }, ["rewardGold"] = 114000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[35985] = { ["id"] = 35985, ["name"] = "Garrison Campaign: The Broken Precipice", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 550, ["storyline"] = { 35945, 35970, 35972, 35973, 35985, 36095 }, ["series"] = { 35945, 35970, 35972, 35973, 37511, 37517 }, ["description"] = "Hey there! You're the commander of this keep, right? I represent the Steamwheedle Preservation Society. We've been trying to get a very important excavation up and running in Nagrand. Unfortunately, we've had trouble with ogres in the area. In fact, one of our best preservationists recently went missing while surveying the area. He's the third society member we've lost up there this week! We aren't really equipped for a rescue mission... so whad'ya say? We could really use the help.", ["objectivesText"] = "Find Greblin Fastfizzle .", ["rewardGold"] = 140450, ["rewardXP"] = 1365, ["rewardItems"] = { 119128 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 83686, ["x"] = 0.395333, ["y"] = 0.244667 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.395333, ["y"] = 0.244667 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 105, ["name"] = "Garrison Campaign", ["orderIndex"] = 4, ["flags"] = 0 } } },
[35997] = { ["id"] = 35997, ["name"] = "Empire's Fall", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6996, ["mapID"] = 535, ["storyline"] = { 35997 }, ["series"] = { 35998, 36004, 36005, 36006, 39022 }, ["description"] = "The Ogre Sorcerer King, Imperator Mar'gok, has mastered magical techniques we would consider on the fringe of arcane science. His felbreakers, among others, can actively dampen or nullify magic. Even fel magic! If we're to locate Gul'dan, we need to figure out how it's done. Acquire a felbreaker's tome from his felbreaker captain and acquire the sigil of the sorcerer king himself - I must know what he knows. Yes, <name>, this means I expect you to storm Highmaul and defeat everyone inside. Get to it!", ["objectivesText"] = "Collect a Felbreaker's Tome and the Sigil of the Sorcerer King from Highmaul. Progress: What have you found in Highmaul?", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["rewardItems"] = { 115280, 115288, 115289, 245491 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6996 } }, ["questType"] = "standard" },
[35998] = { ["id"] = 35998, ["name"] = "Legacy of the Sorcerer Kings", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 35998 }, ["series"] = { 35997, 36004, 36005, 36006, 39022 }, ["description"] = "For over a thousand years, the ogre sorcerer kings maintained an iron grip over their empire using a variety of artifacts. Trusted lieutenants were given magical gems that allowed them to enforce the emperor's will out in the field. These \" Abrogator Stones \" still maintain their power even today, and can be found scattered throughout the Highmaul complex. Sometimes in clusters. Collect $1oa of these Abrogator Stones for me!", ["objectivesText"] = "Collect 125 Abrogator Stones from creatures in Highmaul. Your garrison followers may also be able to locate stones in certain missions. Progress: Do you have the stones? I never thought I'd turn to ogres for magical might, but those ancient Sorcerer Kings knew a thing or two about raw arcane energy that would keep Kirin-Tor scholars busy for ages.", ["rewardGold"] = 280900, ["rewardXP"] = 1365, ["rewardItems"] = { 115280, 115510, 115981, 127785 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[36004] = { ["id"] = 36004, ["name"] = "Power Unleashed", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 36004 }, ["series"] = { 35997, 35998, 36005, 36006, 39022 }, ["description"] = "You've more than earned a reward, commander. I'll wrap things up here and meet you back at my tower - you can use my portal as a shortcut. Speak to me when you arrive and I will use Kairoz's power with the crystals you gathered earlier to upgrade your ring!", ["objectivesText"] = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra, and allow him to upgrade your ring. Progress: Do you slay a lot of dragons? You handled that like a professional.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 118295, 118296, 118297, 118298, 118299 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 84702, ["x"] = 0.873333, ["y"] = 0.332667 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.873333, ["y"] = 0.332667 }, ["mapCandidates"] = { ["npc"] = { 535, 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[36005] = { ["id"] = 36005, ["name"] = "The Scrying Game", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 36005 }, ["series"] = { 35997, 35998, 36004, 36006, 39022 }, ["description"] = "We've learned everything we need from the ogres, <name>. Thanks to your efforts, I believe I can pierce the veil of secrecy that's cloaking Gul'dan. I WILL find him, <class>. Once my spell is finished we should be ready to leap into action. I won't begin until you let me know you're ready.", ["objectivesText"] = "Speak with Khadgar and locate Gul'dan with his scrying spell.", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83929, ["x"] = 0.848, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[36006] = { ["id"] = 36006, ["name"] = "Hunter: Hunted", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 36006 }, ["series"] = { 35997, 35998, 36004, 36005, 39022 }, ["description"] = "The weapon that stabbed the archmage was imbued with fel magic. He's slowly being poisoned! <name>, we don't have any time. Khadgar will be dead in minutes. I need you to track down Garona before she gets away - find that murder weapon and maybe we can find a cure! Follow the traces of fel energy she left behind. Track her down into the Zangarra lowlands and capture her with this Violet Hold Incarceration rune. Hurry!", ["objectivesText"] = "Follow Garona's trail into the Zangarra lowlands. Find, defeat, and capture her. Progress: Why are you wasting time? Find Garona!", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 115510, 115530, 118006 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 83929, ["x"] = 0.848, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83929, ["x"] = 0.848, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[36007] = { ["id"] = 36007, ["name"] = "Touch of the Kirin-Tor", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 36007 }, ["series"] = { 36009, 36010, 36012, 36013, 36014, 36016, 36017, 36018, 37834, 37836, 37837, 37841, 37964, 39023, 40501 }, ["description"] = "<Khadgar's breathing is labored and his face is drained of color, but his eyes still flash with energy.> You saved me, <name>. Once again I underestimated Gul'dan, and it nearly cost me everything. Come, help me up. While Jaina is here, the two of us can work together to upgrade your ring. You've earned it! Let me know when you're ready.", ["objectivesText"] = "Speak with Archmage Khadgar to upgrade your ring.", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["rewardItems"] = { 118300, 118301, 118302, 118303, 118304 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[36009] = { ["id"] = 36009, ["name"] = "Heart of the Fury", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 36009 }, ["series"] = { 36007, 36010, 36012, 36013, 36014, 36016, 36017, 36018, 37834, 37836, 37837, 37841, 37964, 39023, 40501 }, ["description"] = "It is foolish to pursue Gul'dan with magical means alone. But thanks to you we have a prisoner: Garona. If we can break Gul'dan's mind-control over her, we will learn all his secrets. I can do it, but I'll need some powerful spell components. First on the list is the heart of an elemental fury. There's one imprisoned in the center of the Blackrock Foundry. Fight your way in, destroy the furnace, and slay the elemental within.", ["objectivesText"] = "Collect a Heart of the Fury from the elemental Fury encased within the furnace of the Blackrock Foundry. Progress: Elemental \"furies\" appear to be unique to Draenor. It may be something about the primal nature of this world.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 115479, 115493, 115494, 115509, 115510 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[36010] = { ["id"] = 36010, ["name"] = "Flamebender's Tome", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 36010 }, ["series"] = { 36007, 36009, 36012, 36013, 36014, 36016, 36017, 36018, 37834, 37836, 37837, 37841, 37964, 39023, 40501 }, ["description"] = "The Iron Horde, and the Burning Blade clan in particular, have forged a unique relationship with Draenor's ancient elementals. They can work with iron and flame in ways that even I don't fully understand. Yet. <name>, slay the Burning Blade's highest-ranking artisan: Flamebender Ka'graz. She is down in the very heart of the Black Forge of the Blackrock Foundry, an area known as the Burning Font. If we're lucky, her secrets are codified in a Flamebender's Tome .", ["objectivesText"] = "Retrieve the Flamebender's Tome from Flamebender Ka'graz in the Blackrock Foundry. Progress: Do you have the Flamebender's Tome ? Many legendary Burning Blade weapons owe their existence to this volume!", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 115479, 115493, 115494, 115509, 115510 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[36012] = { ["id"] = 36012, ["name"] = "Reverse Piracy", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 36012 }, ["series"] = { 36007, 36009, 36010, 36013, 36014, 36016, 36017, 36018, 37834, 37836, 37837, 37841, 37964, 39023, 40501 }, ["description"] = "<name>, during the attack on Karabor Iron Horde dreadnaughts looted or sank most of the draenei eastern fleet. A priceless artifact was captured: A genuine Draenic Thaumaturgical Orb . I must have it! Those orcs don't know what they've got! My sources indicate that the orb was aboard a ship that's being retrofitted down in the Dread Grotto beneath the Blackrock Foundry. Search the ship and the area nearby for the Sha'tari Vault that contained the orb. We've got to get it back!", ["objectivesText"] = "Acquire the Draenic Thaumaturgical Orb from the Dread Grotto in the Blackrock Foundry. Progress: The orb! Tell me you've found the orb...?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 115479, 115493, 115494, 115509, 115510 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[36013] = { ["id"] = 36013, ["name"] = "Might of the Elemental Lords", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 36013 }, ["series"] = { 36007, 36009, 36010, 36012, 36014, 36016, 36017, 36018, 37834, 37836, 37837, 37841, 37964, 39023, 40501 }, ["description"] = "Somehow, the Blackrock Clan has forged an alliance with the creatures of fire and stone. I must know how! Search the entirety of the Blackrock Foundry. We are looking for stone tablets dating back to the prehistory of Draenor. They will likely be broken apart into fragments that you'll need to assemble by hand. Look for elemental runes carried by high-ranking members of the Iron Horde. Assemble them and bring me those tablets, <name>. I will use their power to augment the powers of your ring!", ["objectivesText"] = "Collect 3 Elemental Tablets . Assemble the tablets by collecting Elemental Runes from bosses in the Blackrock Foundry. Progress: I've been able to spend some time studying the prehistory of Draenor. Primal elemental forces competed with each other to shape the world in what is known as the Age of Colossals. Their descendants still fight to this day, especially in regions such as Gorgrond. Those tablets you're assembling will reveal the forces at work during the era... and more importantly, they will allow us to control and channel those forces, just as the Blackrock do today!", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 32572, 115280, 115479, 115493, 115494, 115509, 115510, 115981 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[36014] = { ["id"] = 36014, ["name"] = "Blackhand's Secret", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 36014 }, ["series"] = { 36007, 36009, 36010, 36012, 36013, 36016, 36017, 36018, 37834, 37836, 37837, 37841, 37964, 39023, 40501 }, ["description"] = "<name>, you've given me a lot to think about. There's a section of the Flamebender's Tome that speaks about a \"sacrifice,\" and a more recent notation referring to \"the chieftain.\" I think it's talking about Warlord Blackhand. Did Blackhand sacrifice someone? Himself? A piece of himself? Is that why his hand is deformed? Before I risk channeling these elements into a spell, I need to know. And there's only one way to find out. Kill Warlord Blackhand. And bring me his severed arm.", ["objectivesText"] = "Slay Warlord Blackhand and acquire his severed arm in the Blackrock Foundry. Progress: Well <name>? Are you armed?", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 115510, 115523 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[36016] = { ["id"] = 36016, ["name"] = "The Unbroken Circle", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 36016 }, ["series"] = { 36007, 36009, 36010, 36012, 36013, 36014, 36017, 36018, 37834, 37836, 37837, 37841, 37964, 39023, 40501 }, ["description"] = "Reading these tablets is like stepping back in time to the moment of Draenor's creation. There is a power here greater than any I have dealt with since I was Medivh's apprentice. I believe I can control it, but - can you handle it? If you think you are ready, prepare yourself. Hold your ring close to your heart. I will channel pure elemental energies into it. Speak with me to begin!", ["objectivesText"] = "Speak with Archmage Khadgar to upgrade your ring. Progress: Speak with me when you are ready!", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 118305, 118306, 118307, 118308, 118309 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[36017] = { ["id"] = 36017, ["name"] = "Prisoner of the Mind", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 36017 }, ["series"] = { 36007, 36009, 36010, 36012, 36013, 36014, 36016, 36018, 37834, 37836, 37837, 37841, 37964, 39023, 40501 }, ["description"] = "I'd had some time to compare the Flamebinder's tome with the elemental tablets you collected. Where it gets interesting is when I cross-reference the incantations you obtained from the ogre felbreakers... I can see I'm losing you. I will get to the point: I believe I can cast a spell that will nullify Gul'dan's mind control over his assassin Garona. Mind-controlled or not, she may be dangerous, so I won't begin the spell until you're with me. Let me know when you're ready!", ["objectivesText"] = "Speak with Khadgar and protect him while he casts his spell on Garona.", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[36018] = { ["id"] = 36018, ["name"] = "We're Not Finished...", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 36018 }, ["series"] = { 36007, 36009, 36010, 36012, 36013, 36014, 36016, 36017, 37834, 37836, 37837, 37841, 37964, 39023, 40501 }, ["description"] = "<name>, I'm going to have to hit the books and do more research to figure out how to locate Gul'dan or untangle his mind control of Garona. It's not glamorous, but the life of a mage is often spent in long hours of grueling study. As for you, there's much to do. Ensure that your garrison is fully upgraded, locate the best possible equipment, and continue fighting the Iron Horde. I will summon you when the next step of our journey is ready.", ["objectivesText"] = "Report to Archmage Khadgar at Khadgar's Tower in Zangarra.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 77497 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
