[36038] = { ["id"] = 36038, ["name"] = "Pandaren Hide", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 8485, ["mapID"] = 588, ["storyline"] = { 36038 }, ["objectivesText"] = "Progress: WAIT... YOU DIDN'T GET THIS HIDE FROM A HORDE PANDAREN, DID YOU?", ["rewardGold"] = 339600, ["rewardItems"] = { 112113, 170073, 170074 }, ["starts"] = { { ["mapID"] = 588, ["npcID"] = 83869, ["x"] = 0.458, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 588, ["npcID"] = 83869, ["x"] = 0.458, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 588, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 588 }, ["zone"] = { 8485 } }, ["questType"] = "standard" },
