[36117] = { ["id"] = 36117, ["name"] = "Garrison Campaign: The Broken Precipice", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 550, ["storyline"] = { 35945, 35970, 35972, 35973, 36117 }, ["series"] = { 35945, 35970, 35972, 35973, 37511, 37516 }, ["description"] = "Hey there! You're the commander of this keep, right? I represent the Steamwheedle Preservation Society. We've been trying to get a very important excavation up and running in Nagrand. Unfortunately, we've had trouble with ogres in the area. In fact, one of our best preservationists recently went missing while surveying the area. He's the third society member we've lost up there this week! We aren't really equipped for a rescue mission... so whad'ya say? We could really use the help.", ["objectivesText"] = "Find Greblin Fastfizzle .", ["rewardGold"] = 140450, ["rewardXP"] = 1365, ["rewardItems"] = { 119128 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 83686, ["x"] = 0.395333, ["y"] = 0.244667 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.395333, ["y"] = 0.244667 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 550, ["questLines"] = { { ["id"] = 116, ["name"] = "Garrison Campaign", ["orderIndex"] = 4, ["flags"] = 0 } } },
