[36352] = { ["id"] = 36352, ["name"] = "Locating the Lapidarist", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 36352 }, ["series"] = { 36314, 36378, 36380 }, ["description"] = "Are you sure I can't take this off your hands? I'll give you a fair price! Alright, alright... if you insist on finding the owner, you might want to try visiting Wor'gol. Rumor has it there is a master craftsman there who's skilled in manipulating precious metals and stones. Might be your guy.", ["objectivesText"] = "Search for the owner of the pendant in Wor'gol.", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["rewardItems"] = { 115489 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 85106, ["x"] = 0.2, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.2, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36376] = { ["id"] = 36376, ["name"] = "Goren Invasion!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36376 }, ["description"] = "Quakes have been shaking the garrison, and our scouts haven't reported in hours.", ["objectivesText"] = "Repel the goren invasion. (Speak with Sergeant Crowler again to begin) Progress: We must hold the line!", ["rewardGold"] = 169800, ["rewardXP"] = 8200, ["rewardItems"] = { 116980, 122403 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36379] = { ["id"] = 36379, ["name"] = "Peeking into the Portal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 4, ["mapID"] = 17, ["storyline"] = { 36379 }, ["description"] = "I sent Scout Pazerp to get a better look at the portal. She should have reported back by now; what could be taking her so long? She is one of my best scouts, I hope she is alright.", ["objectivesText"] = "Find Scout Pazerp and use her telescope .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 17, ["npcID"] = 85213, ["x"] = 0.668, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 17, ["npcID"] = 85213, ["x"] = 0.668, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 4 } }, ["questType"] = "standard" },
[36380] = { ["id"] = 36380, ["name"] = "Diamonds Are Forever", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36380 }, ["series"] = { 36314, 36352, 36378 }, ["description"] = "Please watch closely <name>. I shall craft this jewel into a fine pendant for you. Hopefully you will learn a bit of true jewelcrafting in the process.", ["objectivesText"] = "Wait for Orolak to finish crafting the pendant. Progress: It is finished, and even more beautiful than the last!", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["rewardItems"] = { 111814, 115287, 115359, 115503, 115507 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 85106, ["x"] = 0.2, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 85106, ["x"] = 0.2, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.2, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[36382] = { ["id"] = 36382, ["name"] = "Peeking into the Portal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 4, ["mapID"] = 17, ["storyline"] = { 36382 }, ["description"] = "I sent Scout Pazaztick to be gettin' a better look at da portal. He shoulda reported back by dis time; what be taking him so long? Dis is what happens when you hire da goblins as help.", ["objectivesText"] = "Find Scout Pazaztick and use her telescope .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 17, ["npcID"] = 85247, ["x"] = 0.718, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 17, ["npcID"] = 85247, ["x"] = 0.718, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 4 } }, ["questType"] = "standard" },
[36383] = { ["id"] = 36383, ["name"] = "Assault on the Pit", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6721, ["storyline"] = { 36383 }, ["description"] = "The Iron Horde are stockpiling their weapons and ammunition outside of the Foundry. Their campaign throughout Draenor has left their caches vulnerable. Get in there and cause as much chaos as you can, and while you're at it use some of that ammunition against them if they're just going to leave it lying around!", ["objectivesText"] = "Destroy Iron Horde weapons cache and take out as many of them as you can.", ["rewardGold"] = 1239200, ["rewardXP"] = 1365, ["rewardItems"] = { 118472, 119225, 119226, 119227, 119228, 119229, 119230, 120945, 133876 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Blackrock Foundry Assaulted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Kill Iron Horde", ["amount"] = 100, ["type"] = 0, ["objectID"] = 85228, ["orderIndex"] = 1 }, { ["text"] = "Kill Iron Horde", ["amount"] = 20, ["type"] = 0, ["objectID"] = 85229, ["orderIndex"] = 2 }, { ["text"] = "Kill Iron Horde", ["amount"] = 5, ["type"] = 0, ["objectID"] = 85230, ["orderIndex"] = 3 }, { ["text"] = "Kill Iron Horde", ["amount"] = 200, ["type"] = 0, ["objectID"] = 86298, ["orderIndex"] = 4 }, { ["text"] = "Destroy Training Manuals", ["amount"] = 100, ["type"] = 2, ["objectID"] = 236277, ["orderIndex"] = 5 }, { ["text"] = "Free Rangari Prisoners", ["amount"] = 50, ["type"] = 2, ["objectID"] = 236421, ["orderIndex"] = 6 } } },
[36385] = { ["id"] = 36385, ["name"] = "Legacy of the Ancients", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36385 }, ["description"] = "Opening the ancient tome you see that it's not actually a tome at all, but a container. Inside are four empty slots. Upon closer inspection each slot has next to it a carving of what appears to be a unique Draenor ancient, some glyphs and a receptacle used to hold a piece of the pictured ancient. There also appear to be directions to where these ancients may be found: medium timber -- Shadowmoon, Gorgrond, the Spires of Arak and Nagrand. These are assassination instructions. From trees to kill trees.", ["objectivesText"] = "Collect the Heart of Kuruk , the Trunk of Autuk , the Twig of Loruk , and the Roots of Hanuk . Progress: What have you got there, commander?", ["rewardGold"] = 679200, ["rewardXP"] = 2830, ["rewardItems"] = { 109255, 115467, 115476, 115477, 115478, 115480, 115506 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard", ["startItems"] = { 115467 } },
[36404] = { ["id"] = 36404, ["name"] = "Clearing the Garden", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36404 }, ["description"] = "This clearing is the perfect spot to grow herbs for our Garrison, there is just one little problem. All these dang raccoons! I need you to clear them out and we can get this garden growing.", ["objectivesText"] = "Kill 8 Lunarfall Raccoons . Progress: Did you get 'em?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 32572, 116053, 118595, 120945, 248334 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36408] = { ["id"] = 36408, ["name"] = "A Power Lost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36408 }, ["series"] = { 36409 }, ["description"] = "<The fragment gleams in the light as its aura's final pulse fades.> The power within the fragment appears to be drained. You recall hearing travelers speak of a local in Embaari Village who specializes in imbuing gems with magic.", ["objectivesText"] = "Find someone in Embaari Village well-versed in gemology and magic. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 115507, 210494 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84830, ["x"] = 0.47, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 115507 } },
[36412] = { ["id"] = 36412, ["name"] = "Shadowmoon Invasion!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36412 }, ["description"] = "Scouts report that the Shadowmoon clan is buzzing like a kicked hornets' nest. Time again to earn our pay, Commander?", ["objectivesText"] = "Repel the Shadowmoon clan invasion of your garrison. (Speak with Sergeant Crowler again to begin) Progress: We must hold the line!", ["rewardGold"] = 169800, ["rewardXP"] = 8200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36414] = { ["id"] = 36414, ["name"] = "Shadowmoon Invasion!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36414 }, ["description"] = "Scouts say the Shadowmoon clan looms close, ready with their necromancy. If I die and rise again, Commander, finish me quickly. I don't want to be a ghoul.", ["objectivesText"] = "Repel the Shadowmoon clan invasion of your garrison. (Speak with Sergeant Grimjaw again to begin) Progress: We must hold the line!", ["rewardGold"] = 169800, ["rewardXP"] = 8200, ["rewardItems"] = { 116980 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36419] = { ["id"] = 36419, ["name"] = "Dyed in the Fur", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36419 }, ["series"] = { 36301, 36417 }, ["description"] = "I can't believe they tried to physically rip the magic out of the material! It seems we were never in danger of my secrets falling into the wrong hands after all. Better safe than dead... In return for your help, I will share with you my methods of fusing magic to cloth. Flytrap Ichor is very rare in this region, but I do have a bit in reserve. Take this woven fur and dip it in the ichor here. You will see for yourself what all of the fuss is about.", ["objectivesText"] = "Use Trega 's Flytrap Ichor to create a Swatch of Hexweave. Progress: Has the cloth been enchanted?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 111816, 115357 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 84689, ["x"] = 0.204, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 84689, ["x"] = 0.204, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.204, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[36423] = { ["id"] = 36423, ["name"] = "Pets Versus Pests", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36423 }, ["description"] = "I've been trying to get this place ready for your pets, but we've uncovered some rude pests while building the garrison. I tried to take care of them myself, but they are too tough for my meager team. There's an angry carrot in the garden, an enormous rat eating our food rations, and an ornery water creature harassing the fishermen. If you can take care of them, I'll be free to finish up my work on your menagerie.", ["objectivesText"] = "Defeat the three pests in your garrison. Progress: Any luck?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 90173, 98715, 152555 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36432] = { ["id"] = 36432, ["name"] = "Seeking the Scout", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36432 }, ["description"] = "We are still trying to locate all of our scouts out in the field. One of these, Altauur , enjoys handling the more dangerous missions. He has not checked in and I feel we should check to make sure he has not taken on more than he can handle.", ["objectivesText"] = "Find Altauur at Dionor's Demise in Gorgrond .", ["rewardGold"] = 210675, ["rewardXP"] = 1045, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 75146, ["x"] = 0.583, ["y"] = 0.561 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 85426, ["x"] = 0.494, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.583, ["y"] = 0.561 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[36435] = { ["id"] = 36435, ["name"] = "Unintelligible Intelligence", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36435 }, ["series"] = { 36457, 36475 }, ["description"] = "The notes are unreadable, but based on previous experience, the text appears to be very similar to standard Orcish. It is possible that the notes could contain strategic information. Perhaps it would be of great value to the Frostwolf Orcs. Someone in Wor'gol might be able to help interpret the text.", ["objectivesText"] = "Look around Wor'gol for someone who can help translate the notes. Progress: <Raleigh looks up from the scrolls.> Commander <name>, what brings you to Wor'gol?!", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 115593 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 85439, ["x"] = 0.21, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.21, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["startItems"] = { 115593 } },
[36436] = { ["id"] = 36436, ["name"] = "Plant Pruning", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36436 }, ["description"] = "There may be more to this aberrant growth than it seems, but we will need to clear the way a bit before we can get to the bottom of this, yes? I suggest clearing out some of the angrier defenders to be on the safe side.", ["objectivesText"] = "Kill 12 defenders at Dionor's Demise. Progress: How goes the pruning <class>?", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 118034, 118035, 118036, 118037 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 85426, ["x"] = 0.494, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 85432, ["x"] = 0.512, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[36437] = { ["id"] = 36437, ["name"] = "Ambassador to the Ancient", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36437 }, ["description"] = "It appears that a genesaur was killed here not long ago and this growth has sprung up. It is stirring up the local monsters and I fear for our outpost. There is a strange ancient that wallows in grief here and is not hostile. Perhaps you could \"harvest\" its story?", ["objectivesText"] = "Talk to Birchus at Dionor's Demise in Gorgrond .", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 85426, ["x"] = 0.494, ["y"] = 0.496 }, { ["mapID"] = 543, ["npcID"] = 85432, ["x"] = 0.512, ["y"] = 0.48 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 85432, ["x"] = 0.512, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[36438] = { ["id"] = 36438, ["name"] = "Beatface vs. Boulder", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36438 }, ["description"] = "The saberon took their treasure up the rise and barricaded themselves in after Birchus attacked. It will be difficult to get in but I hear you have resources to handle this. One of their entrances is covered with a large boulder. Too large for you or I, but perhaps an ogre with a large enough hammer could break it. I think you know who I am talking about...", ["objectivesText"] = "Break the boulder barrier using Beatface the gladiator.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 85432, ["x"] = 0.512, ["y"] = 0.48 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 85431, ["x"] = 0.516, ["y"] = 0.501333 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[36439] = { ["id"] = 36439, ["name"] = "Shredder vs. Saberon", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36439 }, ["description"] = "The saberon took their treasure up the rise and barricaded themselves in after Birchus attacked. It will be difficult to get in but I hear you have resources to handle this. One of their entrances is covered with tough vegetation. I believe you have a mechanical solution to this problem in the form of a shredder. I think you know what to do...", ["objectivesText"] = "Break the vine barrier using your shredder.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 85432, ["x"] = 0.512, ["y"] = 0.48 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 85431, ["x"] = 0.516, ["y"] = 0.501333 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[36440] = { ["id"] = 36440, ["name"] = "Saberon Population Reduction", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36440 }, ["description"] = "We are closer to our goals but a host of sharp toothed saberon bar our way. If we are to get anywhere up here, some of the more aggressive ones will need to be put down I think.", ["objectivesText"] = "Slay 10 saberon at Steamscar Rise.", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 112875, 118004, 118005, 118012, 118013, 118014 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 85431, ["x"] = 0.516, ["y"] = 0.501333 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 85436, ["x"] = 0.528, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.501333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[36441] = { ["id"] = 36441, ["name"] = "Reclaiming Property", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36441 }, ["description"] = "You are attracted by a low green glow to the container. Inside there is a glowing bundle of herbs that was most likely stolen from the overgrowth below. It would be best to collect all of these so the saberon don't continue their dabbling in plant magic and irritating the nearby magnaron.", ["objectivesText"] = "Find 8 Herb Bundles in saberon stashes at Steamscar Rise. Progress: The saberon should definitely NOT have any of the herbs you have found!", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 115442 }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 85431, ["x"] = 0.516, ["y"] = 0.501333 }, { ["mapID"] = 543, ["npcID"] = 85436, ["x"] = 0.528, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.501333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[36442] = { ["id"] = 36442, ["name"] = "Taking the Death Bloom", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36442 }, ["description"] = "Your work has born fruit. Inside the nearby cave a powerful saberon shaman is learning to channel the genesaur magic using the Death Bloom we seek. The solution is before us: kill the shaman, take the Death Bloom, return it to Birchus . That should improve the safety of our outpost.", ["objectivesText"] = "Take the Death Bloom from Smokemaster Snarl in Steamscar Rise. Progress: Do you have something for me little beast?", ["rewardGold"] = 464700, ["rewardXP"] = 2090, ["rewardItems"] = { 113187 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 85436, ["x"] = 0.528, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82302, ["x"] = 0.503, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[36443] = { ["id"] = 36443, ["name"] = "Laying Dionor to Rest", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36443 }, ["description"] = "You have given me a tremendous gift with this bloom. I can finally send Dionor back to the Overgrowth for good and end this nightmare. All that remains is the ritual... stay and behold something you will never see again in your lifetime...", ["objectivesText"] = "Watch Birchus 's ritual.", ["rewardGold"] = 929400, ["rewardXP"] = 2615, ["rewardItems"] = { 112959, 112960, 112961, 119049, 119054 }, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 82302, ["x"] = 0.503, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 82302, ["x"] = 0.503, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[36448] = { ["id"] = 36448, ["name"] = "Reduction in Force", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36448 }, ["description"] = "I was a fool to trust him after the fiasco over the Barov family fortune! What I should have done is killed him the first chance I had. And now he thinks he's going to plumb this land for all that it's worth and cut me out?! No, dear brother, not this time! There can only be one CEO of Barov Industries and it will be me. My peasant friend, you must do me this service. Find my brother, Alexi, and serve him a notice of termination! You will likely find him out in the wilds, near small timber.", ["objectivesText"] = "Collect the Head of Alexi Barov . Progress: Did you deliver the... notice of termination?", ["rewardGold"] = 30900, ["rewardXP"] = 2830, ["rewardItems"] = { 114781, 116152, 116154 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36449] = { ["id"] = 36449, ["name"] = "Reduction in Force", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36449 }, ["description"] = "I was a fool to trust him after the fiasco over the Barov family fortune! What I should have done is killed him the first chance I had. And now he thinks he's going to plumb this land for all that it's worth and cut me out?! No, dear brother, not this time! There can only be one CEO of Barov Industries and it will be me. My peasant friend, you must do me this service. Find my brother, Weldon, and serve him a notice of termination! You will likely find him out in the wilds, near small timber.", ["objectivesText"] = "Collect the Head of Weldon Barov . Progress: Has my brother been served the notice of termination yet?", ["rewardGold"] = 30900, ["rewardXP"] = 2830, ["rewardItems"] = { 13470, 109255, 115467, 116153, 116154, 116452 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36452] = { ["id"] = 36452, ["name"] = "Spawn Tracking & Spell Visuals: Do They Work?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 36452 }, ["description"] = "Here's some text.", ["objectivesText"] = "Use the What's It to see a Spell Visual play through the magic of Spawn Tracking tech.", ["rewardGold"] = 154000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[36457] = { ["id"] = 36457, ["name"] = "Bypassing Security", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36457 }, ["series"] = { 36435, 36475 }, ["description"] = "Oh, my goodness! This is a list of captives, it appears they may be awaiting transfer... or possibly even execution. There is one name on this list that I do recognize: my master! I have been awaiting his return, but now it appears that he may have fallen into enemy hands. This is a disaster! Please, <name>, we must rescue him. According to the notes, he has been taken to Grom'gar, located far east of here. One moment... I think I may have just the thing to help you break in undetected...", ["objectivesText"] = "Infiltrate Grom'gar using Raleigh's Prestige Card.", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["rewardItems"] = { 116063 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 85439, ["x"] = 0.21, ["y"] = 0.56 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 85440, ["x"] = 0.612, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.21, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[36469] = { ["id"] = 36469, ["name"] = "Pets Versus Pests", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36469 }, ["description"] = "I been tryin' ta get dis place ready for your pets, but we uncovered some rude pests while buildin' da garrison. I tried takin' care o' dem myself, but they be too tough for my little friends. Beat da angry carrot in da garden, da rat eatin' our food, and da ornery water creature harassing da fishermen. If you can do it, I be free to finish up da work on your menagerie.", ["objectivesText"] = "Defeat the three pests in your garrison. Progress: How'd you fare, <name>?", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36471] = { ["id"] = 36471, ["name"] = "A New Darkmoon Challenger!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 5861, ["storyline"] = { 36471 }, ["description"] = "Look at me, now look at my horse, now look back at me, are I not the most impressive battler of pets that you have ever seen? Look now at my compatriot over there. Is he on a horse? Of course not! Is his hat made of fireworks? Not in a million years! Everything about me is more impressive, from my coat color to my last name, which I made myself. Dare you step up to the might of Christoph Willikens Dennis Ragnaros VonFeasel the First? I can see you trembling!", ["objectivesText"] = "Defeat Christoph VonFeasel in a pet battle. Progress: Ready, eh? Put up your cat's tiny dukes!", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 116062 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[36473] = { ["id"] = 36473, ["name"] = "Affliction Ridge", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36473 }, ["objectivesText"] = "Monsters slain Ancient Seedbearer burned", ["rewardGold"] = 849000, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6721 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Monsters slain", ["amount"] = 25, ["type"] = 0, ["objectID"] = 81786, ["orderIndex"] = 0 }, { ["text"] = "Ancient Seedbearer burned", ["amount"] = 5, ["type"] = 0, ["objectID"] = 85524, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 543 },
[36475] = { ["id"] = 36475, ["name"] = "Stealing the Declaration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36475 }, ["series"] = { 36435, 36457 }, ["description"] = "Commander, you and Raleigh did a great job finding me, but I'm exactly where I need to be. We've been working tirelessly since we got here, trying to crack these Draenic texts. I really thought I was gonna get the scrolls, but they nabbed me at the last possible second! Please, you've gotta help me out... up the hill to the east, you'll find the Master Siegesmith's tent. If you can grab the documents out of his chest, possibly this key too, I'll finally have enough to translate their languages.", ["objectivesText"] = "Loot the contents of Master Siegesmith Uratok's Strongbox. Progress: A book of poems? I'll let you hang onto that one for now....", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 111815, 111923, 116063, 116069, 116072, 116114 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 85440, ["x"] = 0.612, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 85440, ["x"] = 0.612, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
