[36606] = { ["id"] = 36606, ["name"] = "News from Nagrand", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 36606 }, ["description"] = "Welcome back, <sir/mam>. One of Bodrick's men delivered a message about a caravan being dispatched for Nagrand. He's awaiting your approval on a new outpost. I've been hearing whispers around camp about Nagrand. They say it's Warsong territory. They might need your help <sir/mam>.", ["objectivesText"] = "Speak to Bodrick Grey at your garrison in Shadowmoon Valley.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81929, ["x"] = 0.398, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[36607] = { ["id"] = 36607, ["name"] = "News from Nagrand", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 36607 }, ["description"] = "Welcome back, <sir/mam>. One of our shadow hunters delivered a message about a caravan being dispatched for Nagrand. Rokhan 's awaiting your approval on a new outpost. I've been hearing whispers around camp about Nagrand. They say it's Warsong territory. They might need your help <sir/mam>.", ["objectivesText"] = "Speak to Rokhan at your garrison in Frostfire Ridge.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 81920, ["x"] = 0.402, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[36608] = { ["id"] = 36608, ["name"] = "Finding Nat Pagle", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 418, ["storyline"] = { 36608 }, ["series"] = { 36609, 36612, 36870 }, ["description"] = "Now that you have proof, we might just have a shot at convincing Nat Pagle to join us out here. Last I heard, he was in fishing with the local Angler's faction out in Pandaria. Somewhere off the coast of Krasarang Wilds. Head out there, show him your catch and see if you can get him to come back with you!", ["objectivesText"] = "Travel to the Angler's Wharf in Krasarang Wilds and talk to Nat Pagle . Progress: You came all this way for me? Well, I am pretty important.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 87215, 103678, 116754, 118041 }, ["ends"] = { { ["mapID"] = 418, ["npcID"] = 63721, ["x"] = 0.684, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 418, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 418 }, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36609] = { ["id"] = 36609, ["name"] = "The Great Angler Returns", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 36609 }, ["series"] = { 36608, 36612, 36870 }, ["description"] = "What's this species, a molten catfish you say? I have never even heard of a fish like this, much less seen one in person! I have to find more fish like this, it's what I live for! And if the fishing is as good as you say it is, there is just no way I can pass this opportunity up. Take this page from my journal as proof that you found me and I will meet you back at your Garrison.", ["objectivesText"] = "Return to Rak'jin with Nat's journal page as proof that you found him. Progress: You found Nat? The real Nat Pagle ?!", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 116747 }, ["starts"] = { { ["mapID"] = 418, ["npcID"] = 63721, ["x"] = 0.684, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 418, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 418 }, ["zone"] = { 6134 } }, ["questType"] = "standard" },
[36611] = { ["id"] = 36611, ["name"] = "A True Draenor Angler", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36611 }, ["series"] = { 36616 }, ["description"] = "If you want me to help you permanently, you have to show me a few of these big Draenor catches first. Head out into the wild and bring me back the biggest fish you can find from all the surrounding areas. I made this custom lure for you to use, please take care of it, it's never let me down!", ["objectivesText"] = "Catch a Lunker in each of the Draenor zones and bring them back to Nat Pagle . Progress: What did you catch?", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 6256, 6533, 33820, 34861, 44050, 45991, 84661, 87791, 88710, 109137, 114919, 116158, 116268, 116748, 116749, 116750, 116751, 116752, 116753, 116755, 116820, 116825, 116826, 117397, 117401, 117404, 117405, 118380, 118381, 118391, 133755, 136377 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36612] = { ["id"] = 36612, ["name"] = "Luring Nat", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36612 }, ["series"] = { 36608, 36609, 36870 }, ["description"] = "Now that you are experienced enough with Draenor fishing, we might have a shot at convincing Nat Pagle to join us out here. If we want Nat to actually come all the way out here, we are going to have to show him real proof of the incredible catches on Draenor. Head out to the lava lakes here in Frostfire and see what you can do. All that time you spend honing your skill here in Draenor should pay off now.", ["objectivesText"] = "Catch a Molten Catfish in Frostfire Ridge and bring it back to Rak'jin . Progress: Any luck near those lava pools?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 34861, 45992, 116754, 118391, 124674 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36614] = { ["id"] = 36614, ["name"] = "My Very Own Fortress", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 36614 }, ["description"] = "Boss! Guess what?! I finally got that new larger draft paper in that I ordered when we first came here. And ya know what larger draft paper means? It means I can draw a bigger fortress! And if I can draw it, I can certainly make it! Making's the easy part, as long as you've got a few thousand stones and logs lying around. So whada'ya say, boss? Shall we get building?", ["objectivesText"] = "Gather 2000 Garrison Resources and then use the Architect Table to select your Town Hall and upgrade your garrison to Tier 3.", ["rewardItems"] = { 107645, 116118, 116131, 118695, 128313, 244315 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36615] = { ["id"] = 36615, ["name"] = "My Very Own Castle", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36615 }, ["description"] = "Commander! Some good news. I finally got that new larger draft paper in that I ordered when we first came here. And do you know what larger draft paper means? It means I can draw a bigger castle! And if I can draw it, we can certainly make it! Making it is the easy part, assuming you have a few thousand stones and logs lying around. So what do you say, sir? Shall we get building?", ["objectivesText"] = "Gather 2000 Garrison Resources and then use the Architect Table to select your Town Hall and upgrade your garrison to Tier 3.", ["rewardItems"] = { 101436, 107645, 110560, 111543, 113130, 113271, 113388, 116118, 116131, 118695, 118710, 119416, 128294, 128313, 248800 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36616] = { ["id"] = 36616, ["name"] = "An Angler on Our Team", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36616 }, ["series"] = { 36611 }, ["description"] = "You truly are a master fisherman! I would be delighted to join you here on Draenor and help you catch as many lunkers as you can. But first, let's grab a drink.", ["objectivesText"] = "Talk to Nat Pagle and ask him to join our cause.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
