[36623] = { ["id"] = 36623, ["name"] = "Ogre Invasion!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36623 }, ["description"] = "Commander, our scouts say that ogre bands march through the snow. If they want more battle after the beating we already delivered, then I'm eager to oblige them.", ["objectivesText"] = "Repel the ogre invasion of your garrison. (Speak with Sergeant Grimjaw again to begin) Progress: We must hold the line!", ["rewardGold"] = 169800, ["rewardXP"] = 8200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36626] = { ["id"] = 36626, ["name"] = "Host Howell", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7332, ["storyline"] = { 36626 }, ["series"] = { 36624, 36629, 36630 }, ["description"] = "Lieutenant Howell said you might be showing up. It's such an honor to meet you in person. The lieutenant is at the inn, I'll escort you over there.", ["objectivesText"] = "Speak with Lieutenant Howell .", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7332 } }, ["questType"] = "standard" },
[36627] = { ["id"] = 36627, ["name"] = "Big Frostfire Gun", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36627 }, ["series"] = { 36589, 36594 }, ["description"] = "One of my finest works, <name>! Momma would be so proud of me right now... if she was still in one piece. We gotta test this bad boy out though before I'm comfortable letting you run around with it all willy-nilly. I heard there were some clefthooves out back causing a ruckus.", ["objectivesText"] = "Subdue 6 Clefthooves. Progress: Did you manage to subdue those rowdy clefthooves?", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 109258, 111921, 116759 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36629] = { ["id"] = 36629, ["name"] = "Inspiring Ashran", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7332, ["storyline"] = { 36629 }, ["series"] = { 36624, 36626, 36630 }, ["description"] = "I hope you will find our facilities to be up to your high standards. This inn is run by Jaesia Rosecheer , in my opinion this is the best place to hearth in Draenor. We have new recruits coming through the portal daily. In fact our latest recruit, Knewbie McGreen just came through the portal today. If you are looking to trade for weapons or armor, Vindicator Nuurem will be happy to help.", ["objectivesText"] = "Speak with Jaesia Rosecheer , Vindicator Nuurem , and Knewbie McGreen . Progress: How did your walk go?", ["rewardGold"] = 127350, ["rewardXP"] = 1060, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7332 } }, ["questType"] = "standard" },
[36630] = { ["id"] = 36630, ["name"] = "A Surly Dwarf", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7332, ["storyline"] = { 36630 }, ["series"] = { 36624, 36626, 36629 }, ["description"] = "Before you go there is someone you might want to talk with. He's opinionated, a bit gruff, and very overbearing, but he's the best damn warrior I've met in ages. He belongs on the front lines with you, commander. And trust me, he knows it.", ["objectivesText"] = "Speak with Delvar Ironfist .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7332 } }, ["questType"] = "standard" },
[36632] = { ["id"] = 36632, ["name"] = "The Secrets of Gorgrond", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 36632 }, ["series"] = { 33255, 33256, 33533, 35033, 35050, 35065, 35556, 49564 }, ["description"] = "Commander, I was dispatched to intercept you. Yrel and Maraad have landed at Wildwood Wash, the rangari base of operations for the area. Your presence is requested immediately. We keep a small feywing presence just east of here. If you speak with the flight master they should be able to provide you safe passage to the Wash.", ["objectivesText"] = "Seek Yrel at the Wildwood Wash in Gorgrond . Speak with your Garrison Gryphon Master or the Flight Master at Bastion Rise to fly there.", ["rewardGold"] = 46350, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 543, ["npcID"] = 86088, ["x"] = 0.42, ["y"] = 0.94 } }, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 80978, ["x"] = 0.584, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.94 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
