[36648] = { ["id"] = 36648, ["name"] = "Assault on Stonefury Cliffs", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36648 }, ["description"] = "Bloodmaul ogres from Frostfire Ridge have been ambushing trade routes throughout the continent, and are putting captured soldiers to work in their slag mines. Bodrick Grey has requested the rescue of friendly troops that have been taken prisoner in the main Bloodmaul compound at Stonefury Cliffs.", ["objectivesText"] = "Assault the Bloodmaul ogres at Stonefury Cliffs in Frostfire Ridge.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 113489, 119131, 119163, 119356, 119362, 119379, 119390, 119399 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36649] = { ["id"] = 36649, ["name"] = "Assault on Shattrath Harbor", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36649 }, ["description"] = "Shattrath City is in the hands of Sargerei forces under the leadership of the traitor Exarch, Socrethar. Members of the Sha'tari Defense have been requesting aid against the Shadow Council forces in the eastern portions of the city.", ["objectivesText"] = "Assault the Sargerei forces at Shattrath City in Talador.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 119386, 119402, 119403, 119413, 241043 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
