[36667] = { ["id"] = 36667, ["name"] = "Assault on Shattrath Harbor", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36667 }, ["description"] = "Shattrath City is in the hands of Sargerei forces under the leadership of the once Exarch, Socrethar. The Shadow Council forces in the eastern portion of the city are gaining in power through the aid of demons from the Nether, and need to be culled before they become a threat to all of our operations.", ["objectivesText"] = "Assault the Sargerei forces at Shattrath City in Talador.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 119386, 119402, 119403, 119413, 122412, 241043 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
