[36670] = { ["id"] = 36670, ["name"] = "The Ring of Blood: Skull Chewer!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 36670 }, ["description"] = "Welcome to Nagrand 's one and only Ring of Blood, where hopefuls become gladiators and gladiators become discarded piles of meat on the arena floor! Talk to me to start a fight, hop down into the ring, and fight for your life. It's positively brutal - and the crowd loves it! You'll face off against an ogron that has a hankering for freshly severed heads. You'll be fine... and I'll be rich!", ["objectivesText"] = "Defeat Skull Chewer in the Ring of Blood.", ["starts"] = { { ["mapID"] = 550, ["npcID"] = 84783, ["x"] = 0.568, ["y"] = 0.13 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 84783, ["x"] = 0.568, ["y"] = 0.13 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.13 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "group" },
[36674] = { ["id"] = 36674, ["name"] = "Assault on the Iron Siegeworks", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36674 }, ["description"] = "Iron Horde war machines are being shipped onto battlefields by the dozens, and our forces are struggling to hold their ground. Most of these machines seem to be originating from the Iron Siegeworks in eastern Frostfire Ridge. A strategic attack to disrupt and dismantle the Iron Horde at the siegeworks could be just what we need to turn the tide of the war.", ["objectivesText"] = "Assault the Iron Horde forces at the Iron Siegeworks in Frostfire Ridge.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 119359, 119366 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36675] = { ["id"] = 36675, ["name"] = "Assault on Magnarok", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36675 }, ["description"] = "Colossal magnaron, gronn, and other stone monstrosities have been threatening our outposts in the west. Most seem to originate from Magnarok in Frostfire Ridge. If we strike at them at their home, we should be able to force them back. It's risky, but it may be our best move. While you're there, see if you can recover any of our supplies.", ["objectivesText"] = "Assault the stone monstrosities at Magnarok in Frostfire Ridge. Progress: How goes the assault, sir?", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 111534, 111545, 119349, 119376, 119415, 119416 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36676] = { ["id"] = 36676, ["name"] = "Assault on the Everbloom Wilds", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36676 }, ["description"] = "Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place. Bodrick Grey has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the wilds of Gorgrond, giving us more room to maneuver around them.", ["objectivesText"] = "Assault the botani forces in the Everbloom Wilds of Gorgrond.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 119357, 119361, 119367, 119381, 119391, 119395, 119406, 119412, 119414, 119432 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36677] = { ["id"] = 36677, ["name"] = "Assault on the Broken Precipice", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36677 }, ["description"] = "Massive ogron have been battering our frontlines, and no matter how many we down, there seem to be more to replace them. Most of these ogron appear to be coming from the Broken Precipice , deep in western Nagrand. If we're to stand a chance in the coming battles, we need to find a way to remove these ogron from the battlefield.", ["objectivesText"] = "Assault the ogron forces at the Broken Precipice in Nagrand.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 119370, 119389, 119405 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36678] = { ["id"] = 36678, ["name"] = "Assault on Mok'gol Watchpost", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36678 }, ["description"] = "Warsong raiders out of Mok'gol Watchpost have been terrorizing anything and everything not behind a tall wall. We've warned travelers not to stray out alone, but many don't listen. If we were to launch an assault on Mok'gol Watchpost, we would almost certainly put the Warsong back on the defensive, restricting most of their riders to Nagrand.", ["objectivesText"] = "Assault the Warsong forces at Mok'gol Watchpost in Nagrand.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 119355, 119380 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36679] = { ["id"] = 36679, ["name"] = "Assault on Darktide Roost", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36679 }, ["description"] = "There's been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don't stop them at the source, we'll quickly lose control of the roads and be pushed back into our outposts. The most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should still have time to get ahead of the problem.", ["objectivesText"] = "Assault the Iron Horde forces at Darktide Roost in Shadowmoon Valley.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 115020, 116978, 119093, 119364, 119400, 119411 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36680] = { ["id"] = 36680, ["name"] = "Assault on Socrethar's Rise", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36680 }, ["description"] = "Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar's Rise in southern Shadowmoon Valley. Socrathar's disciples pose a threat to draenei and our garrison alike. We need to quell them at our soonest convenience.", ["objectivesText"] = "Assault the Sargerei forces at Socrethar's Rise in Shadowmoon Valley.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 119360, 119368, 119377, 119382, 119387, 119396, 119431, 251329 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36681] = { ["id"] = 36681, ["name"] = "Assault on Lost Veil Anzu", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36681 }, ["description"] = "Some of our best scouts have gone missing in the vicinity of the lost ruins of Veil Anzu. Bodrick Grey has requested any available resources be dispatched to identify the threat and see if any of our men yet remain alive within the ruins.", ["objectivesText"] = "Assault the hostile creatures at Lost Veil Anzu in Spires of Arak.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 118373, 122414 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36683] = { ["id"] = 36683, ["name"] = "Assault on Skettis", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36683 }, ["description"] = "We've been receiving regular reports of birdmen from the south ambushing and burning caravans along the main roads. Guards from our outposts are requesting that we launch a counter attack against the main presence of Adherents of Rukhmar at Skettis in Spires of Arak.", ["objectivesText"] = "Assault the Adherents of Rukhmar at Skettis in Spires of Arak.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 118701, 119093, 119407 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36684] = { ["id"] = 36684, ["name"] = "Battle in Ashran", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36684 }, ["description"] = "As we do battle all across Draenor, the cowardly Horde try to seize our territory within Ashran. Our men would be inspired to see you join the battlefield, striking terror into the hearts of the Horde.", ["objectivesText"] = "Join the battle in Ashran.", ["rewardGold"] = 1239200, ["rewardXP"] = 1365, ["rewardItems"] = { 114125 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "pvp" },
[36685] = { ["id"] = 36685, ["name"] = "Assault on the Heart of Shattrath", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36685 }, ["description"] = "Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose. Bring allies if you wish to face the Sargerei so deep within the city.", ["objectivesText"] = "Assault the Sargerei forces deep within Shattrath City in Talador.", ["rewardGold"] = 1239200, ["rewardXP"] = 1365, ["rewardItems"] = { 119170, 119352, 119353, 119375, 119383, 119388, 119393, 119394, 133883, 251547 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "group" },
[36686] = { ["id"] = 36686, ["name"] = "Assault on the Pit", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36686 }, ["description"] = "The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us. If you choose the battle, bring friends. The Blackrock won't be defeated easily.", ["objectivesText"] = "Assault the Blackrock orcs at the Pit in Gorgrond.", ["rewardGold"] = 1239200, ["rewardXP"] = 1365, ["rewardItems"] = { 118472, 119225, 119226, 119227, 119228, 119229, 119230, 120945 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "group" },
