[36697] = { ["id"] = 36697, ["name"] = "Assault on Magnarok", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36697 }, ["description"] = "Colossal magnaron, gronn, and other stone monstrosities have been threatening our garrison. Most seem to originate from Magnarok, just to the north. If we strike at them at their home, we should be able to force them back. It's risky, but it may be our best move. While you're there, see if you can recover any of our supplies.", ["objectivesText"] = "Assault the stone monstrosities at Magnarok in Frostfire Ridge.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 111534, 111545, 119349, 119376, 119415, 119416, 122403 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36698] = { ["id"] = 36698, ["name"] = "Battle in Ashran", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36698 }, ["description"] = "As we do battle all across Draenor, the cowardly Alliance try to seize our territory within Ashran. Our men would be inspired to see you join the battlefield, striking terror into the hearts of the Alliance.", ["objectivesText"] = "Join the battle in Ashran.", ["rewardGold"] = 1239200, ["rewardXP"] = 1365, ["rewardItems"] = { 114125, 114843 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "pvp" },
[36699] = { ["id"] = 36699, ["name"] = "Assault on the Heart of Shattrath", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36699 }, ["description"] = "Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose. Bring allies if you wish to face the Sargerei so deep within the city.", ["objectivesText"] = "Assault the Sargerei force in Shattrath City in Talador. Progress: Da assault be goin' well I hope?", ["rewardGold"] = 1239200, ["rewardXP"] = 1365, ["rewardItems"] = { 119170, 119352, 119353, 119375, 119383, 119388, 119393, 119394, 251547 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group" },
[36700] = { ["id"] = 36700, ["name"] = "Challenge at the Ring of Blood", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36700 }, ["description"] = "A challenge has been issued at the Ring of Blood. Bring friends and do battle to prove your right as champion.", ["objectivesText"] = "Do battle at the Ring of Blood.", ["rewardGold"] = 1239200, ["rewardXP"] = 1365, ["rewardItems"] = { 25759, 25760, 25761, 25762, 25763, 25764 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group" },
[36701] = { ["id"] = 36701, ["name"] = "Assault on the Pit", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36701 }, ["description"] = "The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us. If you choose the battle, bring friends. The Blackrock won't be defeated easily.", ["objectivesText"] = "Assault the Blackrock forces at the Pit in Gorgrond. Progress: Da assault be goin' well I hope?", ["rewardGold"] = 1239200, ["rewardXP"] = 1365, ["rewardItems"] = { 119225, 119226, 119227, 119228, 119229, 119230 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group" },
