[36813] = { ["id"] = 36813, ["name"] = "Subversive Infestation", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36813 }, ["description"] = "As lord of the Everbloom my charge was the weaponization of nature. You have likely seen the fruits of my labor in your journeys across my world. My discoveries have allowed my kind to control the invasive species of Draenor through subversive infestation. I speak of total systemic control of the invading organism - the mind and the body. Now that you are my master I offer these gifts to you, but first you must retrieve my research and tools from the Everbloom . Do this and great power is yours.", ["objectivesText"] = "Recover Phylarch's Research , Xeri'tac's Venom Gland , and 3 Depleted Everbloom Seeds from the Everbloom and return to Phylarch the Evergreen . Progress: Retrieve what I have asked for, master. I will show you the true strength of nature.", ["rewardGold"] = 1239200, ["rewardXP"] = 1200, ["rewardItems"] = { 117398, 117434, 117435, 117436 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
