[36830] = { ["id"] = 36830, ["name"] = "Shadow Council Invasion!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36830 }, ["description"] = "The demons are at our heels, Commander. Cow's milk is sour. A crone gave me an evil look this morning. The sky just doesn't seem... right.", ["objectivesText"] = "Repel the Shadow Council invasion of your garrison. (Speak with Sergeant Crowler again to begin) Progress: We must hold the line!", ["rewardGold"] = 169800, ["rewardXP"] = 8200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36831] = { ["id"] = 36831, ["name"] = "Shadow Council Invasion!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36831 }, ["description"] = "There's a cold fire in my blood, Commander. Like a warlock has my heart in his claw. Let the Shadow Council show themselves!", ["objectivesText"] = "Repel the Shadow Council invasion of your garrison. (Speak with Sergeant Grimjaw again to begin) Progress: We must hold the line!", ["rewardGold"] = 169800, ["rewardXP"] = 8200, ["rewardItems"] = { 116980, 122410, 133884 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
