[36843] = { ["id"] = 36843, ["name"] = "They Came From Above", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 36843 }, ["series"] = { 33740, 34685 }, ["description"] = "Please, traveler, I need your help. Aruuna, my home, has been destroyed by the arakkoa. They swooped down from their spires and killed anyone who tried to escape. My family... did not make it out. My brother Barum stayed behind to find his daughter amidst the chaos. I beseech you, please, go to Aruuna and find Barum. He is the only family I have left.", ["objectivesText"] = "Find Crystal-Shaper Barum near Aruuna in Talador .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 86522, ["x"] = 0.675, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 75896, ["x"] = 0.73, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
