[36897] = { ["id"] = 36897, ["name"] = "Nemesis: Becoming Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36897 }, ["description"] = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a human in mortal combat. Return here with your prize. Through the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", ["objectivesText"] = "Kill a Human Player in Player versus Player combat while in Draenor and retrieve their Human Heart . Progress: Have you recovered the heart of a worthy foe?", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 118116 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "pvp" },
[36911] = { ["id"] = 36911, ["name"] = "Taming a Talbuk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36911 }, ["description"] = "If we're going to start sending out patrols in this wilderness, we'll need swift mounts for our troops. We can capture young beasts and bring them back here for training, eventually turning them into formidable beasts of war. The talbuk is one of Draenor's fastest creatures, and that makes them just that much more difficult to capture. Take this talbuk lasso and head out to Shadowmoon Valley . Mount up and rope one of the young talbuk, and follow it until it's tamed. Don't let it get too far from you!", ["objectivesText"] = "Use the Talbuk Lasso on a Young Silverpelt and follow it until it is tamed.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 118179 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36912] = { ["id"] = 36912, ["name"] = "Capturing a Clefthoof", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36912 }, ["description"] = "Greetings, friend. I have been told that you are in need of a master of beasts. I come from the icy slopes of Northrend to finally shake this snow from my fur. This savage land holds many creatures that we may tame so that our forces may ride on formidable war mounts. The mighty clefthoof reminds me of the mammoths from my home. Take this lasso and head out to the northern reaches of Frostfire Ridge . Mount up and use it to capture one of the young beasts.", ["objectivesText"] = "Use the Clefthoof Lasso on a Young Icehoof and follow it until it is tamed.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 118287 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36913] = { ["id"] = 36913, ["name"] = "Besting a Boar", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36913 }, ["description"] = "Have you seen the boars they have here? Bigger than I am! Let's get one of them, why not? You're going to have to head to Gorgrond for that task. Way out in the desolate regions, you'll find the ones we're lookin' for.", ["objectivesText"] = "Use the Boar Lasso on a Young Rocktusk and follow it until it is tamed.", ["rewardGold"] = 619600, ["rewardXP"] = 2615, ["rewardItems"] = { 118185 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36914] = { ["id"] = 36914, ["name"] = "Wrangling a Wolf", ["level"] = 38, ["requiredLevel"] = 38, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36914 }, ["description"] = "This next one will test you to your very limits, commander. The wolf is the most savage beast in all of Draenor. The wolves of Nagrand , mounts of the fabled Warsong clan, can rend a man to bits in seconds. They're also faster and more agile than anything you've seen yet. Here's your lasso. Good luck, and don't get yourself killed!", ["objectivesText"] = "Use the Wolf Lasso on a Young Snarler and follow it until it is tamed.", ["rewardGold"] = 619600, ["rewardXP"] = 6495, ["rewardItems"] = { 118182 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36915] = { ["id"] = 36915, ["name"] = "Entangling an Elekk", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36915 }, ["description"] = "Well, you're pretty good at this whole taming thing. What's next? We've done big, and we've done pointy. Let's do big AND pointy. I'm talking Elekks. Way out on the fertile plains of Nagrand , you'll find the finest specimens of beast this world has to offer. Grab one of the younger elekks, and we'll see if we can't get it trained like the Draenei used to.", ["objectivesText"] = "Use the Elekk Lasso on a Young Meadowstomper and follow it until it is tamed.", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 118184, 118286 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36916] = { ["id"] = 36916, ["name"] = "Capturing a Clefthoof", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36916 }, ["description"] = "Way up north in the frozen peaks of Frostfire Ridge , you'll find the wooly clefthoof. They're sturdy, for sure, and fierce when you corner them. Don't expect them to be tamed without a fight. Here's a lasso, see if you can't manage to tame one before it tugs the rope out of your hands.", ["objectivesText"] = "Use the Clefthoof Lasso on a Young Icehoof and follow it until it is tamed.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 118181 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36917] = { ["id"] = 36917, ["name"] = "Taming a Talbuk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36917 }, ["description"] = "The next beast is one of the fastest in Draenor, but will test your skills at infiltrating into enemy territory. The young talbuk can be found on the flowery hills of Shadowmoon Valley . Take this talbuk lasso and head out. When you encounter one, mount up and throw this rope, then follow it until it is tamed. Good hunting!", ["objectivesText"] = "Use the Talbuk Lasso on a Young Silverpelt and follow it until it is tamed.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 110560, 118284 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36918] = { ["id"] = 36918, ["name"] = "Requisition a Riverbeast", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36918 }, ["description"] = "I wasn't sure about this next beast, but it turns out that they've got a key strategic purpose. The riverbeast is quite at home in the water! You'll find the best ones around in Talador , around about Duskfall Island. Look for the huge, floating lumps out in the water. Try not to get wet!", ["objectivesText"] = "Use the Riverbeast Lasso on a Young Riverwallow and follow it until it is tamed.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 8827, 81354, 118183, 118711 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36921] = { ["id"] = 36921, ["name"] = "Nemesis: Manslayer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36921 }, ["description"] = "< Raza'kul hands you the bloody heart.> The ritual is complete. Your nemesis is marked for death. Now your work to rid this world of the enemy truly begins. Kill all humans that stand defiantly against the Horde. Let their deaths serve as a warning to the rest of the Alliance: they will leave Draenor or they will die. Return when you have quenched your rage with the blood of man. Conquer our enemy and be known as manslayer. Fail and be nothing.", ["objectivesText"] = "Kill 500 Human Players in Player versus Player combat across Draenor.", ["rewardGold"] = 679200, ["rewardXP"] = 2830, ["rewardItems"] = { 118265 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "pvp" },
[36923] = { ["id"] = 36923, ["name"] = "Nemesis: Becoming Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36923 }, ["description"] = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a dwarf in mortal combat. Return here with your prize. Through the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", ["objectivesText"] = "Kill a Dwarf Player in Player versus Player combat while in Draenor and retrieve their Dwarf Heart . Progress: Have you recovered the heart of a worthy foe?", ["rewardGold"] = 584200, ["rewardXP"] = 1770, ["rewardItems"] = { 118119 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "pvp" },
[36924] = { ["id"] = 36924, ["name"] = "Nemesis: Dwarfstalker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36924 }, ["description"] = "< Raza'kul hands you the bloody heart.> The ritual is complete. Your nemesis is marked for death. Now your work to rid this world of the enemy truly begins. Kill all dwarves that stand defiantly against the Horde. Let their deaths serve as a warning to the rest of the Alliance: they will leave Draenor or they will die. Return when you have quenched your rage with the blood of dwarf. Conquer our enemy and be known as dwarfstalker. Fail and be nothing.", ["objectivesText"] = "Kill 500 Dwarf Players in Player versus Player combat across Draenor.", ["rewardGold"] = 679200, ["rewardXP"] = 2830, ["rewardItems"] = { 118265 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "pvp" },
[36925] = { ["id"] = 36925, ["name"] = "Nemesis: Becoming Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36925 }, ["description"] = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a gnome in mortal combat. Return here with your prize. Through the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", ["objectivesText"] = "Kill a Gnome Player in Player versus Player combat while in Draenor and retrieve their Gnome Heart . Progress: Have you recovered the heart of a worthy foe?", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 118117 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "pvp" },
