[36935] = { ["id"] = 36935, ["name"] = "Phantom Potion", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6941, ["mapID"] = 588, ["storyline"] = { 36935 }, ["description"] = "Every turn you take in Ashran you run into danger. But don't fret <name>, I've developed the perfect solution. It's my very own riff on the popular Invisibility Potion. I'm just missing one of the ingredients: cave mushrooms. Luckily, a variety grows right here in Ashran .", ["objectivesText"] = "Bring Tyra Silverblood 10 Ghost Truffles . Progress: Are those the truffles?", ["rewardGold"] = 339600, ["rewardItems"] = { 114124, 117017 }, ["ends"] = { { ["mapID"] = 588, ["npcID"] = 86366, ["x"] = 0.455333, ["y"] = 0.284667 } }, ["coords"] = { ["mapID"] = 588, ["source"] = "quest_giver", ["x"] = 0.455333, ["y"] = 0.284667 }, ["mapCandidates"] = { ["npc"] = { 588 }, ["zone"] = { 6941 } }, ["questType"] = "standard" },
[36940] = { ["id"] = 36940, ["name"] = "Warning Orgrimmar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 1637, ["mapID"] = 17, ["storyline"] = { 36940 }, ["description"] = "We have slowed the Iron Horde down, but this war is far from over... I'll stay here and continue our efforts to hold back the Iron Horde. The Warchief needs to know about what we have accomplished here today, and the threat we face in the future. It is probably best if you report to High Overlord Saurfang yourself, <class>.", ["objectivesText"] = "Speak with High Overlord Saurfang .", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 111660, 118776, 118777, 118778, 118779, 118780 }, ["starts"] = { { ["mapID"] = 17, ["npcID"] = 84928, ["x"] = 0.486, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 14720, ["x"] = 0.485, ["y"] = 0.71 }, { ["mapID"] = 85, ["npcID"] = 86832, ["x"] = 0.482, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 17, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[36941] = { ["id"] = 36941, ["name"] = "Report to the King", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 1519, ["mapID"] = 17, ["storyline"] = { 36941 }, ["description"] = "We have slowed the Iron Horde down, but this war is far from over... I'll stay here and continue our efforts to hold back the Iron Horde. The King needs to know about what we have accomplished here today, and the threat we face in the future. It is probably best if you report to King Wrynn yourself, <name>.", ["objectivesText"] = "Speak with King Anduin Wrynn .", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 111660, 118776, 118777, 118778, 118779, 118780 }, ["starts"] = { { ["mapID"] = 17, ["npcID"] = 84929, ["x"] = 0.52, ["y"] = 0.285 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 29611, ["x"] = 0.855, ["y"] = 0.32 }, { ["mapID"] = 84, ["npcID"] = 107574, ["x"] = 0.856, ["y"] = 0.316667 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 17, 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[36944] = { ["id"] = 36944, ["name"] = "Besting a Boar", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36944 }, ["description"] = "The great boars of Gorgrond appear to serve as both a mount and an excellent source of food. Having a few of them in the garrison would not be an unwise idea. I have created for you another rope, should you wish to ride one down. Be wary of the Iron Horde presence nearby.", ["objectivesText"] = "Use the Boar Lasso on a Young Rocktusk and follow it until it is tamed.", ["rewardGold"] = 619600, ["rewardXP"] = 2615, ["rewardItems"] = { 118288 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36945] = { ["id"] = 36945, ["name"] = "Requisition a Riverbeast", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36945 }, ["description"] = "I have seen great beasts floating slowly along the rivers of Talador . The 'riverbeasts,' I believe they are called. Their hides are solid, like rock, and yet they float along the waters easily. I would quite like to see one of these up close, if you should head that way. Tormak has created for you another rope, if you are interested.", ["objectivesText"] = "Use the Riverbeast Lasso on a Young Riverwallow and follow it until it is tamed.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 7969, 8827, 42457, 81354, 87791, 118285, 168417 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36946] = { ["id"] = 36946, ["name"] = "Entangling an Elekk", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36946 }, ["description"] = "The plains of Nagrand are the most lush and fertile that I have ever seen. Should you ever see them, you will come upon the mightiest beasts that this place has to offer. Among them, the great elekk. A magnificent beast with horns that can grow larger than you or I. Here is another rope, should you wish to tangle with such a beast.", ["objectivesText"] = "Use the Elekk Lasso on a Young Meadowstomper and follow it until it is tamed.", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 44234, 69775, 78883, 86568, 118184, 118286 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36948] = { ["id"] = 36948, ["name"] = "Auctioning for Parts", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36948 }, ["objectivesText"] = "Progress: <The power crystal for this unit has been disconnected. Whatever did this also managed to rip out the other support modules. If you found all of these items, you're confident you could restore it>", ["rewardItems"] = { 65274, 65360, 111986, 118197, 118331, 118332, 118333, 118334, 118335, 118336, 118337, 118338, 118339, 118340, 118341, 118342, 118343, 118344, 118345, 118346, 118347, 118375, 118376, 118377, 118378, 118379, 120945 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36950] = { ["id"] = 36950, ["name"] = "Wrangling a Wolf", ["level"] = 38, ["requiredLevel"] = 38, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 36950 }, ["description"] = "The wolves of this land have jaws of steel. It is no wonder that the orcs have taken them as their own. Yet, deep in Nagrand , there are young wolves, ripe for taming. They will present a great challenge to you, as they are more fast and agile than any beast in this land. Here is your final rope, may luck be with you.", ["objectivesText"] = "Use the Wolf Lasso on a Young Snarler and follow it until it is tamed.", ["rewardGold"] = 339600, ["rewardXP"] = 6495, ["rewardItems"] = { 118283 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36952] = { ["id"] = 36952, ["name"] = "Taking the Fight to Nagrand", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 550, ["storyline"] = { 36952 }, ["series"] = { 34794, 34795, 34808, 34818, 49549 }, ["description"] = "**Eyes Only -- Commander <name>** Durotan recommended dat we be gettin' a foothold in Nagrand , so I taken the liberty of dispatchin' some of da boys. Thrall's already reportin' the new outpost be nearly complete. He been askin' me to let ya know they be ready for ya. A windrider be waitin' to catch ya up with the latest caravan shipment whenever you be ready, <sir/ma'am>. -- Rokhan", ["objectivesText"] = "Speak with Stone Guard Brox at the caravan in Nagrand .", ["rewardXP"] = 600, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 80001, ["x"] = 0.864, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.864, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36953] = { ["id"] = 36953, ["name"] = "It's a Matter of Strategy", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 535, ["storyline"] = { 36953 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 49547 }, ["description"] = "**Eyes Only -- Commander <name>** The Iron Horde have proved themselves worthy foes. They managed to get their fleet moving to Talador from Gorgrond without my spies seeing a thing. Talador be a crossroads for the whole continent. We can't let them have it. Don't worry boss, we got a plan. Foreman Grobash be setting up an outpost for our forces as we speak. They be ready for you when you arrive, commander. --Rokhan", ["objectivesText"] = "Speak to Bron Skyhorn to secure a flight to Talador .", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79176, ["x"] = 0.71, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36955] = { ["id"] = 36955, ["name"] = "Nemesis: Hunter - Hunted", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36955 }, ["description"] = "Our enemies surround us, and with each passing day their numbers grow. It is time to make a decisive strike against their armies, champion. Around me stand effigies of our most hated adversaries. You will be their downfall, <name>. You will become nemesis and they will run in fear at the sight of you. Now select the target of your rage and burn in effigy that race which you mean to eradicate. Speak to me when you have made your selection.", ["objectivesText"] = "Burn a Nemesis Effigy at the Gladiator's Sanctum then speak to Kuros .", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "pvp" },
[36956] = { ["id"] = 36956, ["name"] = "Nemesis Flag, Human", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 36956 }, ["rewardGold"] = 11400, ["rewardXP"] = 25, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp" },
