[36959] = { ["id"] = 36959, ["name"] = "Nemesis: Becoming Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36959 }, ["description"] = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the mostly-dead heart of a Forsaken in mortal combat. Return here with your prize. Through the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", ["objectivesText"] = "Kill a Forsaken Player in Player versus Player combat while in Draenor and retrieve their Forsaken Heart . Progress: Have you recovered the heart of a worthy foe?", ["rewardGold"] = 339600, ["rewardXP"] = 1770, ["rewardItems"] = { 118359 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "pvp" },
[36960] = { ["id"] = 36960, ["name"] = "Nemesis: Death Stalker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36960 }, ["description"] = "< Kuros hands you the bloody heart.> The ritual is complete. Your nemesis is marked for death. Now your work to rid this world of the enemy truly begins. Kill all Forsaken that stand defiantly against the Alliance. Let their deaths serve as a warning to the rest of the Horde: they will leave Draenor or they will die. Return when you have quenched your rage with the black blood of Forsaken. Conquer our enemy and be known as death stalker. Fail and be nothing.", ["objectivesText"] = "Kill 500 Forsaken Players in Player versus Player combat across Draenor.", ["rewardGold"] = 679200, ["rewardXP"] = 2830, ["rewardItems"] = { 118265 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "pvp" },
