[36969] = { ["id"] = 36969, ["name"] = "Nemesis: Becoming Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36969 }, ["description"] = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a goblin in mortal combat. Return here with your prize. Through the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", ["objectivesText"] = "Kill a Goblin Player in Player versus Player combat while in Draenor and retrieve their Goblin Heart . Progress: Have you recovered the heart of a worthy foe?", ["rewardGold"] = 339600, ["rewardXP"] = 1770, ["rewardItems"] = { 118357 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "pvp" },
[36970] = { ["id"] = 36970, ["name"] = "Nemesis: Killer of Kezan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36970 }, ["description"] = "< Kuros hands you the bloody heart.> The ritual is complete. Your nemesis is marked for death. Now your work to rid this world of the enemy truly begins. Kill all goblins that stand defiantly against the Alliance. Let their deaths serve as a warning to the rest of the Horde: they will leave Draenor or they will die. Return when you have quenched your rage with the blood of goblin. Conquer our enemy and be known as the killer of Kezan. Fail and be nothing.", ["objectivesText"] = "Kill 500 Goblin Players in Player versus Player combat across Draenor.", ["rewardGold"] = 885120, ["rewardXP"] = 2830, ["rewardItems"] = { 118265 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "pvp" },
[36971] = { ["id"] = 36971, ["name"] = "Talbuk Training: Great-Tusk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36971 }, ["description"] = "The first step in training your mount for war will be getting it used to the sights and sounds of combat. If it's not trained properly, it might get spooked and run. Take this little talbuk out to the plains of Shadowmoon Valley and take on the biggest beast you can find, together. That should raise its confidence!", ["objectivesText"] = "Defeat Great-Tusk while riding your Talbuk-In-Training. Progress: Did you manage to bring down Great-Tusk ?", ["rewardGold"] = 339600, ["rewardXP"] = 1770, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36972] = { ["id"] = 36972, ["name"] = "Talbuk Training: Rakkiri", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36972 }, ["description"] = "Now that your talbuk has got a taste for combat, let's take it out into an environment it may not be familiar with. The icy bluffs of Frostfire Ridge should be a good test. Find yourself a big, mean beast out there and take it down with your talbuk.", ["objectivesText"] = "Defeat Rakkiri while riding your Talbuk-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 1770, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36973] = { ["id"] = 36973, ["name"] = "Talbuk Training: Riplash", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36973 }, ["description"] = "Now plenty of mounts have been known to run away at the sight of a fierce predator. Way out in the desolate cliffs of Gorgrond , they've got some of the fiercest. Let's put your talbuk to the test. See if the two of you can't take down the mighty raptor known as Riplash .", ["objectivesText"] = "Defeat Riplash while riding your Talbuk-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 2615, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36974] = { ["id"] = 36974, ["name"] = "Talbuk Training: Gezz'ran", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36974 }, ["description"] = "There's plenty more beasts out in the wild that can make a snack of your favorite mount. One of the most cunning on Draenor is the stalker. Stalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your talbuk can't overcome this natural defense mechanism. You'll find some mean stalkers out in Talador .", ["objectivesText"] = "Defeat Gezz'ran while riding your Talbuk-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 3455, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36975] = { ["id"] = 36975, ["name"] = "Talbuk Training: Bulbapore", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36975 }, ["description"] = "Way down south in the Spires of Arak , the land's being overtaken by the mushrooms that grow underwater. The result? Strange fungal creatures sprouting up all over the place. Taking on a strange creature, like the fungal giant Bulbapore , gives us a great chance to expose your talbuk to predators it's unfamiliar with.", ["objectivesText"] = "Defeat Bulbapore while riding your Talbuk-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 5145, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36976] = { ["id"] = 36976, ["name"] = "Talbuk Training: Cruel Ogres", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36976 }, ["description"] = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques. There is one ogre in particular, the Gorian Beast-Lasher , that smells of blood and fear. Go on and see how your talbuk reacts to that.", ["objectivesText"] = "Defeat the Gorian Beast-Lasher while riding your Talbuk-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 5990, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36977] = { ["id"] = 36977, ["name"] = "Talbuk Training: Darkwing Roc", ["level"] = 38, ["requiredLevel"] = 38, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36977 }, ["description"] = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both of 'em. Head on out to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc . That'll be a good test for the both of ye.", ["objectivesText"] = "Defeat the Darkwing Roc while riding your Talbuk-In-Training.", ["rewardGold"] = 561800, ["rewardXP"] = 6495, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36978] = { ["id"] = 36978, ["name"] = "Talbuk Training: Moth of Wrath", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36978 }, ["description"] = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath , is coated with a foul-smelling dust. If the moth dust is enough to keep wolves at bay, it'll probably be a pretty good test for your talbuk. See if you can't keep it focused and take down that moth.", ["objectivesText"] = "Defeat the Moth of Wrath while riding your Talbuk-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36979] = { ["id"] = 36979, ["name"] = "Talbuk Training: Thundercall", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36979 }, ["description"] = "The elements can sometimes pose a problem for some beasts. Ever seen a ram in a thunderstorm? They'll hide behind anything larger than themselves. I'm not sure if they think the world is ending or what, but it's not great if you're atop one at the time. In Nagrand , off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your talbuk and face off against Thundercall , and we'll see if it gets spooked.", ["objectivesText"] = "Defeat Thundercall while riding your Talbuk-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118286, 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36980] = { ["id"] = 36980, ["name"] = "Talbuk Training: Ironbore", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36980 }, ["description"] = "Alright, we've taken on foes in the sky and on land, and even in the rain. What happens when the beasts are below your feet, though? We're about to find out! The rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your talbuk on out to the sandy shores and see if you can't take down one of the elder rockworms: Ironbore .", ["objectivesText"] = "Defeat Ironbore while riding your Talbuk-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36981] = { ["id"] = 36981, ["name"] = "Talbuk Training: Orc Hunters", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36981 }, ["description"] = "The Warsong Clan of Nagrand are some of the best hunters I've ever had the misfortune of meeting. If anyone can pose a real test for your future mount, it's one of their chief beast-killers. Out in Nagrand , you'll find an orc by the name of Karak. They call him the Great Hunter, and he's taken down more fierce beasts than any other in the clan. Get astride your talbuk and bring him down. In the name of the poor wee beasts!", ["objectivesText"] = "Defeat Karak the Great Hunter while riding your Talbuk-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36982] = { ["id"] = 36982, ["name"] = "Talbuk Training: The Garn", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36982 }, ["description"] = "I've got one last challenge for ye, commander, but if it isn't a doozy. They call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator. There's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand . Take your talbuk, mount up, and bring it down. If the two of you survive, your talbuk will truly be ready for war.", ["objectivesText"] = "Defeat Maimclaw while riding your Talbuk-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 116774, 118352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36983] = { ["id"] = 36983, ["name"] = "Clefthoof Training: Great-Tusk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36983 }, ["description"] = "The first step in training your mount for war will be getting it used to the sights and sounds of combat. If it's not trained properly, it might get spooked and run. Take this little clefthoof out to the plains of Shadowmoon Valley and take on the biggest beast you can find, together. That should raise its confidence!", ["objectivesText"] = "Defeat Great-Tusk while riding your Clefthoof -In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 1770, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36984] = { ["id"] = 36984, ["name"] = "Clefthoof Training: Rakkiri", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36984 }, ["description"] = "Now that the clefthoof has a taste for combat, let's take it out into a harsher environment. Take your clefthoof out to the icy hills of Frostfire Ridge , and take on the great predator Rakkiri . We'll really put 'er toughness to the test.", ["objectivesText"] = "Defeat Rakkiri while riding your Clefthoof-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 1770, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36985] = { ["id"] = 36985, ["name"] = "Clefthoof Training: Riplash", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36985 }, ["description"] = "Now plenty of mounts have been known to run away at the sight of a fierce predator. Way out in the desolate cliffs of Gorgrond , they've got some of the fiercest. Let's put your talbuk to the test. See if the two of you can't take down the mighty raptor known as Riplash .", ["objectivesText"] = "Defeat Riplash while riding your Clefthoof-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 2615, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
