[36987] = { ["id"] = 36987, ["name"] = "Clefthoof Training: Bulbapore", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36987 }, ["description"] = "Way down south in the Spires of Arak , the land's being overtaken by the mushrooms that grow underwater. The result? Strange fungal creatures sprouting up all over the place. Taking on a strange creature, like the fungal giant Bulbapore , gives us a great chance to expose your clefthoof to predators it's unfamiliar with.", ["objectivesText"] = "Defeat Bulbapore while riding your Clefthoof-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 5145, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36988] = { ["id"] = 36988, ["name"] = "Clefthoof Training: Cruel Ogres", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36988 }, ["description"] = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques. There is one ogre in particular, the Gorian Beast-Lasher , that smells of blood and fear. Go on and see how your clefthoof reacts to that.", ["objectivesText"] = "Defeat the Gorian Beast-Lasher while riding your Clefthoof-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 5990, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36989] = { ["id"] = 36989, ["name"] = "Clefthoof Training: Darkwing Roc", ["level"] = 38, ["requiredLevel"] = 38, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36989 }, ["description"] = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both of em.' Head on out to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc . That'll be a good test for the both of ye.", ["objectivesText"] = "Defeat the Darkwing Roc while riding your Clefthoof-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 6495, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36990] = { ["id"] = 36990, ["name"] = "Clefthoof Training: Moth of Wrath", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36990 }, ["description"] = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath , is coated with a foul-smelling dust. If the moth dust is enough to keep wolves at bay, it'll probably be a pretty good test for your clefthoof. See if you can't keep it focused and take down that moth.", ["objectivesText"] = "Defeat the Moth of Wrath while riding your Clefthoof-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36991] = { ["id"] = 36991, ["name"] = "Clefthoof Training: Thundercall", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36991 }, ["description"] = "The elements can sometimes pose a problem for some beasts. Ever seen a ram in a thunderstorm? They'll hide behind anything larger than themselves. I'm not sure if they think the world is ending or what, but it's not great if you're atop one at the time. In Nagrand , off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your clefthoof and face off against Thundercall , and we'll see if it gets spooked.", ["objectivesText"] = "Defeat Thundercall while riding your Clefthoof-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 118286, 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36992] = { ["id"] = 36992, ["name"] = "Clefthoof Training: Ironbore", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36992 }, ["description"] = "Alright, we've taken on foes in the sky and on land, and even in the rain. What happens when the beasts are below your feet, though? We're about to find out! The rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your clefthoof on out to the sandy shores and see if you can't take down one of the elder rockworms: Ironbore .", ["objectivesText"] = "Defeat Ironbore while riding your Clefthoof-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36993] = { ["id"] = 36993, ["name"] = "Clefthoof Training: Orc Hunters", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36993 }, ["description"] = "The Warsong Clan of Nagrand are some of the best hunters I've ever had the misfortune of meeting. If anyone can pose a real test for your future mount, it's one of their chief beast-killers. Out in Nagrand , you'll find an orc by the name of Karak. They call him the Great Hunter, and he's taken down more fierce beasts than any other in the clan. Get astride your clefthoof and bring him down. In the name of the poor wee beasts!", ["objectivesText"] = "Defeat Karak the Great Hunter while riding your Clefthoof-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36994] = { ["id"] = 36994, ["name"] = "Clefthoof Training: The Garn", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36994 }, ["description"] = "I've got one last challenge for ye, commander, but if it isn't a doozy. They call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator. There's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand . Take your clefthoof, mount up, and bring it down. If the two of you survive, your clefthoof will truly be ready.", ["objectivesText"] = "Defeat Maimclaw while riding your Clefthoof-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 112003, 116656, 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36995] = { ["id"] = 36995, ["name"] = "Boar Training: Riplash", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36995 }, ["description"] = "That boar's seen it's share of combat out in Gorgrond , so it'll be a bit easier to train. We'll start off in it's home, as you've done with yer other beasties. See if the two of you can't take down the mighty raptor known as Riplash .", ["objectivesText"] = "Defeat Riplash while riding your Boar-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 2615, ["rewardItems"] = { 118351 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36996] = { ["id"] = 36996, ["name"] = "Boar Training: Gezz'ran", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36996 }, ["description"] = "There's plenty more beasts out in the wild that can make a snack of your favorite mount. One of the most cunning on Draenor is the stalker. Stalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your boar can't overcome this natural defense mechanism. You'll find some mean stalkers out in Talador .", ["objectivesText"] = "Defeat Gezz'ran while riding your Boar-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 3455, ["rewardItems"] = { 118351 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36997] = { ["id"] = 36997, ["name"] = "Boar Training: Bulbapore", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 36997 }, ["description"] = "Way down south in the Spires of Arak , the land's being overtaken by the mushrooms that grow underwater. The result? Strange fungal creatures sprouting up all over the place. Taking on a strange creature, like the fungal giant Bulbapore , gives us a great chance to expose your boar to predators it's unfamiliar with.", ["objectivesText"] = "Defeat Bulbapore while riding your Boar-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 5145, ["rewardItems"] = { 118351 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
