[37014] = { ["id"] = 37014, ["name"] = "Auctioning for Parts", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37014 }, ["objectivesText"] = "Progress: <The power crystal for this unit has been disconnected. Whatever did this also managed to rip out the other support modules. If you found all of these items, you're confident you could restore it>", ["rewardItems"] = { 116980, 118197, 118331, 118332, 118333, 118334, 118335, 118336, 118337, 118338, 118339, 118340, 118341, 118342, 118343, 118344, 118345, 118346, 118347, 118375, 118376, 118377, 118378, 118379, 122163 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37015] = { ["id"] = 37015, ["name"] = "Elekk Training: Cruel Ogres", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37015 }, ["description"] = "This beast is surely at home in Nagrand , and I bet ye after all of the years of domestication by Draenei, it's going to be a snap to train. Let's set it loose against the ogres of the region that yer familiar with. That Gorian Beast-Lasher , the one that smells of blood and fear, go on and see how your elekk reacts to that.", ["objectivesText"] = "Defeat the Gorian Beast-Lasher while riding your Meadowstomper-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 5990, ["rewardItems"] = { 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37016] = { ["id"] = 37016, ["name"] = "Elekk Training: Darkwing Roc", ["level"] = 38, ["requiredLevel"] = 38, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37016 }, ["description"] = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both of em.' Head on out to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc . That'll be a good test for the both of ye.", ["objectivesText"] = "Defeat the Darkwing Roc while riding your Meadowstomper-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 6495, ["rewardItems"] = { 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37017] = { ["id"] = 37017, ["name"] = "Elekk Training: Moth of Wrath", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37017 }, ["description"] = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath , is coated with a foul-smelling dust. If the moth dust is enough to keep wolves at bay, it'll probably be a pretty good test for your elekk. See if you can't keep it focused and take down that moth.", ["objectivesText"] = "Defeat the Moth of Wrath while riding your Meadowstomper-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37018] = { ["id"] = 37018, ["name"] = "Elekk Training: Thundercall", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37018 }, ["description"] = "The elements can sometimes pose a problem for some beasts. Ever seen a ram in a thunderstorm? They'll hide behind anything larger than themselves. I'm not sure if they think the world is ending or what, but it's not great if you're atop one at the time. In Nagrand , off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your elekk and face off against Thundercall , and we'll see if it gets spooked.", ["objectivesText"] = "Defeat Thundercall while riding your Meadowstomper-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 118286, 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37019] = { ["id"] = 37019, ["name"] = "Elekk Training: Ironbore", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37019 }, ["description"] = "Alright, we've taken on foes in the sky and on land, and even in the rain. What happens when the beasts are below your feet, though? We're about to find out! The rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your elekk on out to the sandy shores and see if you can't take down one of the elder rockworms: Ironbore .", ["objectivesText"] = "Defeat Ironbore while riding your Meadowstomper-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37020] = { ["id"] = 37020, ["name"] = "Elekk Training: Orc Hunters", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37020 }, ["description"] = "The Warsong Clan of Nagrand are some of the best hunters I've ever had the misfortune of meeting. If anyone can pose a real test for your future mount, it's one of their chief beast-killers. Out in Nagrand , you'll find an orc by the name of Karak. They call him the Great Hunter, and he's taken down more fierce beasts than any other in the clan. Get astride your elekk and bring him down. In the name of the poor wee beasts!", ["objectivesText"] = "Defeat Karak the Great Hunter while riding your Meadowstomper-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37021] = { ["id"] = 37021, ["name"] = "Elekk Training: The Garn", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37021 }, ["description"] = "I've got one last challenge for ye, commander, but if it isn't a doozy. They call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator. There's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand . Take your elekk, mount up, and bring it down. If the two of you survive, your elekk will truly be ready.", ["objectivesText"] = "Defeat Maimclaw while riding your Meadowstomper-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 112003, 116662, 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37022] = { ["id"] = 37022, ["name"] = "Wolf Training: Cruel Ogres", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37022 }, ["description"] = "The wolves of Draenor are some of the most savage beasts around, but they've also gotten used to the sights and smells of the orcs and ogres that live here. It shouldn't take us much time at all to train this little ball of fur and death. Let's set it loose against the ogres of the region that yer familiar with. That Gorian Beast-Lasher , the one that smells of blood and fear, go on and see how your wolf reacts to that.", ["objectivesText"] = "Defeat the Gorian Beast-Lasher while riding your Snarler-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 118353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37023] = { ["id"] = 37023, ["name"] = "Wolf Training: Darkwing Roc", ["level"] = 38, ["requiredLevel"] = 38, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37023 }, ["description"] = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both of em.' Head on out to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc . That'll be a good test for the both of ye.", ["objectivesText"] = "Defeat the Darkwing Roc while riding your Snarler-In-Training.", ["rewardGold"] = 339600, ["rewardXP"] = 6495, ["rewardItems"] = { 118353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
