[37028] = { ["id"] = 37028, ["name"] = "Wolf Training: The Garn", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37028 }, ["description"] = "I've got one last challenge for ye, commander, but if it isn't a doozy. They call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator. There's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand . Take your wolf, mount up, and bring it down. If the two of you survive, your wolf will truly be ready.", ["objectivesText"] = "Defeat Maimclaw while riding your Snarler-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 116784, 118353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37029] = { ["id"] = 37029, ["name"] = "Sigil of the Black Hand", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6967, ["storyline"] = { 37029 }, ["description"] = "<Goraluk sighs with... relief? ...or perhaps regret?> Once I walked these halls with pride, holding my head high as an orc of the Blackrock clan. But this is a wrong path. Our hammers were meant to craft axes, swords... not these machines from the stranger's whispers. The Warlord will not be swayed, but by force. If you can retrieve essences from the Foundry's most powerful guardians, I can craft for you a sigil that will permit direct access to Blackhand's Crucible.", ["objectivesText"] = "Collect 4 Embers of the Mountain , 4 Hearts of Stone , and 4 Shards of Iron from the final bosses of each wing of the Blackrock Foundry on Normal difficulty. Progress: I will require essences from each of the Foundry's guardians if this is to work.", ["rewardGold"] = 679200, ["rewardXP"] = 1365, ["rewardItems"] = { 118382, 118383, 118384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6967 } }, ["questType"] = "raid" },
[37030] = { ["id"] = 37030, ["name"] = "Sigil of the Black Hand (Heroic)", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6967, ["storyline"] = { 37030 }, ["description"] = "<Goraluk sighs with... relief? ...or perhaps regret?> Once I walked these halls with pride, holding my head high as an orc of the Blackrock clan. But this is a wrong path. Our hammers were meant to craft axes, swords... not these machines from the stranger's whispers. The Warlord will not be swayed, but by force. If you can retrieve essences from the Foundry's most powerful guardians, I can craft for you a sigil that will permit direct access to Blackhand's Crucible.", ["objectivesText"] = "Collect 4 Embers of the Mountain , 4 Hearts of Stone , and 4 Shards of Iron from the final bosses of each wing of the Blackrock Foundry on Heroic difficulty. Progress: I will require essences from each of the Foundry's guardians if this is to work.", ["rewardGold"] = 679200, ["rewardXP"] = 1365, ["rewardItems"] = { 118385, 118386, 118387 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6967 } }, ["questType"] = "raid" },
[37031] = { ["id"] = 37031, ["name"] = "Sigil of the Black Hand (Mythic)", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6967, ["storyline"] = { 37031 }, ["description"] = "<Goraluk sighs with... relief? ...or perhaps regret?> Once I walked these halls with pride, holding my head high as an orc of the Blackrock clan. But this is a wrong path. Our hammers were meant to craft axes, swords... not these machines from the stranger's whispers. The Warlord will not be swayed, but by force. If you can retrieve essences from the Foundry's most powerful guardians, I can craft for you a sigil that will permit direct access to Blackhand's Crucible.", ["objectivesText"] = "Collect 4 Embers of the Mountain , 4 Hearts of Stone , and 4 Shards of Iron from the final bosses of each wing of the Blackrock Foundry on Mythic difficulty. Progress: I will require essences from each of the Foundry's guardians if this is to work.", ["rewardGold"] = 679200, ["rewardXP"] = 1365, ["rewardItems"] = { 118388, 118389, 118390 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6967 } }, ["questType"] = "raid" },
[37032] = { ["id"] = 37032, ["name"] = "Boar Training: Riplash", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37032 }, ["description"] = "This boar is at home in the rocky plains of Gorgrond , so it will be easier to train. As with other beasts, we will begin the training in the place it calls home. Test your boar against the great predator Riplash , a raptor known to hunt boars.", ["objectivesText"] = "Defeat Riplash while riding your Boar-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 2615, ["rewardItems"] = { 118351 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37033] = { ["id"] = 37033, ["name"] = "Boar Training: Gezz'ran", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37033 }, ["description"] = "Many of the creatures of Draenor have grown and thrived in a most hostile environment. One of the most cunning on is the stalker. Stalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your beast can overcome this natural defense mechanism. You will find a proper predator in Talador .", ["objectivesText"] = "Defeat Gezz'ran while riding your Boar-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 118351 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37034] = { ["id"] = 37034, ["name"] = "Boar Training: Bulbapore", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37034 }, ["description"] = "In the far south, in the Spires of Arak , the land is being swallowed by the mushrooms that grow underwater, and strange fungal creatures grow uninhibited. Taking on a strange creature, like the fungal giant Bulbapore , will grant you a chance to expose your mount to unfamiliar predators.", ["objectivesText"] = "Defeat Bulbapore while riding your Boar-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 118351 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37035] = { ["id"] = 37035, ["name"] = "Boar Training: Cruel Ogres", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37035 }, ["description"] = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques. There is one ogre in particular, the Gorian Beast-Lasher , that smells of blood and fear. Go on and see how your beast reacts to that.", ["objectivesText"] = "Defeat the Gorian Beast-Lasher while riding your Boar-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 118351 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37036] = { ["id"] = 37036, ["name"] = "Boar Training: Darkwing Roc", ["level"] = 38, ["requiredLevel"] = 38, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37036 }, ["description"] = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both. Travel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc . It will be a good test for your mount.", ["objectivesText"] = "Defeat the Darkwing Roc while riding your Boar-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 6495, ["rewardItems"] = { 118351 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37037] = { ["id"] = 37037, ["name"] = "Boar Training: Moth of Wrath", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37037 }, ["description"] = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath , is coated with a foul-smelling dust. If the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your boar. See if you can keep it focused and defeat the moth.", ["objectivesText"] = "Defeat the Moth of Wrath while riding your Boar-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118351 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37038] = { ["id"] = 37038, ["name"] = "Boar Training: Thundercall", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37038 }, ["description"] = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance. In Nagrand , off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall , and we will see how your mount fares.", ["objectivesText"] = "Defeat Thundercall while riding your Boar-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118286, 118351 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37039] = { ["id"] = 37039, ["name"] = "Boar Training: Ironbore", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37039 }, ["description"] = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet. The rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore .", ["objectivesText"] = "Defeat Ironbore while riding your Boar-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118351 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37040] = { ["id"] = 37040, ["name"] = "Boar Training: Orc Hunters", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37040 }, ["description"] = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test. Out in Nagrand , you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", ["objectivesText"] = "Defeat Karak the Great Hunter while riding your Boar-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118351 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37041] = { ["id"] = 37041, ["name"] = "Boar Training: The Garn", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37041 }, ["description"] = "The last test for your mount will pit it against one of the great terrors of this land. The garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them. There is a lone garn that calls Nagrand its home. Take your boar, mount up, and bring it down. If the two of you survive, your boar will truly be ready.", ["objectivesText"] = "Defeat Maimclaw while riding your Boar-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 112003, 116675, 118351 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37043] = { ["id"] = 37043, ["name"] = "Scraps of Iron", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37043 }, ["description"] = "At the armory, we can take scraps of Iron Horde armor that you collect and turn them into new gear. It's not the strongest stuff in the world, but it looks good. Get some Iron Horde scraps and come back my way. I'll set you up with a nice tabard for your troubles.", ["objectivesText"] = "Collect 5 Iron Horde Scraps from Iron Horde on Draenor. Progress: Got those scraps?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 113681, 118365, 118372, 245437 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37044] = { ["id"] = 37044, ["name"] = "Unconventional Inventions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37044 }, ["description"] = "We've got a lot goin' on here at the workshop. We're buildin' new inventions all the time, and you can find 'em behind me on the workbench. Go ahead and grab today's glorious invention. Use it at your own risk.", ["objectivesText"] = "Acquire an invention from the workbench at your Goblin Workshop. Progress: A goblin workshop can get dangerous. Watch out for exploding explosives!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37045] = { ["id"] = 37045, ["name"] = "Salvaging the Situation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37045 }, ["description"] = "Here at the Salvage Yard we inspect any extra material your followers bring back from the field, preserving anything that may be useful. I have an extra pack of material our people brought in that I've yet to go through. Why don't you take it over to the incinerator and see if it contains anything useful?", ["objectivesText"] = "Use the Small Sack of Salavaged Goods near the incinerator at your Salvage Yard. Progress: Have you burned through that bag of salvage yet?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 118471, 118473, 139593 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37046] = { ["id"] = 37046, ["name"] = "The Headhunter's Harvest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37046 }, ["description"] = "Hey der mon, I be ya new headhunter. The tavern be a perfect place for adventurers to rest after a long journey. It also be a great place to talk them into joining our cause. I be havin' a few recruits for ya to look at, if ya find one we can hire then I'll give ya a little somethin' as a finder fee for ya time.", ["objectivesText"] = "Recruit a follower from Akanja in the Frostwall Tavern. Progress: Ya find a recruit ya like?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37048] = { ["id"] = 37048, ["name"] = "Clefthoof Training: Great-Tusk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37048 }, ["description"] = "The next step in training your mount for war will be getting it used to the sights and sounds of combat. If it is not trained properly, it might become afraid at a very inopportune time. Though small, take your clefthoof to the plains of Shadowmoon Valley and find the greatest beast you can. It will grow quickly against such a foe.", ["objectivesText"] = "Defeat Great-Tusk while riding your Clefthoof -In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37049] = { ["id"] = 37049, ["name"] = "Clefthoof Training: Rakkiri", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37049 }, ["description"] = "Your clefthoof is most at home here in Frostfire Ridge , and that is where we will begin the training. Out on the icy plains, you will find a hunter of blood and death. The winged terror Rakkiri is feared by beasts across this region, and will prove a good first test for your future mount.", ["objectivesText"] = "Defeat Rakkiri while riding your Clefthoof-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37050] = { ["id"] = 37050, ["name"] = "Clefthoof Training: Riplash", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37050 }, ["description"] = "Many beasts will cower in fear at the sight of a mighty predator. In the desolate cliffs of Gorgrond lives one of the most fierce. It will prove your next challenge. Take your beast to the nest of the great Riplash , and see if you cannot emerge victorious.", ["objectivesText"] = "Defeat Riplash while riding your Clefthoof-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 2615, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37051] = { ["id"] = 37051, ["name"] = "Clefthoof Training: Gezz'ran", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37051 }, ["description"] = "Many of the creatures of Draenor have grown and thrived in a most hostile environment. One of the most cunning on is the stalker. Stalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your beast can overcome this natural defense mechanism. You will find a proper predator in Talador .", ["objectivesText"] = "Defeat Gezz'ran while riding your Clefthoof-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37052] = { ["id"] = 37052, ["name"] = "Clefthoof Training: Bulbapore", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37052 }, ["description"] = "In the far south, in the Spires of Arak , the land is being swallowed by the mushrooms that grow underwater, and strange fungal creatures grow uninhibited. Taking on a strange creature, like the fungal giant Bulbapore , will grant you a chance to expose your mount to unfamiliar predators.", ["objectivesText"] = "Defeat Bulbapore while riding your Clefthoof-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37053] = { ["id"] = 37053, ["name"] = "Clefthoof Training: Cruel Ogres", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37053 }, ["description"] = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques. There is one ogre in particular, the Gorian Beast-Lasher , that smells of blood and fear. Go on and see how your beast reacts to that.", ["objectivesText"] = "Defeat the Gorian Beast-Lasher while riding your Clefthoof-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37054] = { ["id"] = 37054, ["name"] = "Clefthoof Training: Darkwing Roc", ["level"] = 38, ["requiredLevel"] = 38, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37054 }, ["description"] = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both. Travel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc . It will be a good test for your mount.", ["objectivesText"] = "Defeat the Darkwing Roc while riding your Clefthoof-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 6495, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37055] = { ["id"] = 37055, ["name"] = "Clefthoof Training: Moth of Wrath", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37055 }, ["description"] = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath , is coated with a foul-smelling dust. If the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your clefthoof. See if you can keep it focused and defeat the moth.", ["objectivesText"] = "Defeat the Moth of Wrath while riding your Clefthoof-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37056] = { ["id"] = 37056, ["name"] = "Clefthoof Training: Thundercall", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37056 }, ["description"] = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance. In Nagrand , off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall , and we will see how your mount fares.", ["objectivesText"] = "Defeat Thundercall while riding your Clefthoof-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 116668, 118286, 118348, 118469 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37057] = { ["id"] = 37057, ["name"] = "Clefthoof Training: Ironbore", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37057 }, ["description"] = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet. The rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores and test it against the elder worm Ironbore .", ["objectivesText"] = "Defeat Ironbore while riding your Clefthoof-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37058] = { ["id"] = 37058, ["name"] = "Clefthoof Training: Orc Hunters", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37058 }, ["description"] = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test. Out in Nagrand , you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", ["objectivesText"] = "Defeat Karak the Great Hunter while riding your Clefthoof-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37059] = { ["id"] = 37059, ["name"] = "Clefthoof Training: The Garn", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37059 }, ["description"] = "The last test for your mount will pit it against one of the great terrors of this land. The garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them. There is a lone garn that calls Nagrand its home. Take your clefthoof, mount up, and bring it down. If the two of you survive, your clefthoof will truly be ready.", ["objectivesText"] = "Defeat Maimclaw while riding your Clefthoof-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 116656, 118348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37060] = { ["id"] = 37060, ["name"] = "Lost in Transition", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37060 }, ["description"] = "<Sir/Ma'am>, the storehouse is fully operational and I've seen to it that your supplies are safely stored away and accounted for. Unfortunately, during the rest of my audit I found that we are missing a few crates of surplus material - probably misplaced by one of the porters. If you happen to come across any of the surplus crates while making your rounds, please bring them to me and I'll update our ledger.", ["objectivesText"] = "Gather 5 Crate of Surplus Materials . Progress: Hello commander, what can I do for you?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 118417 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37062] = { ["id"] = 37062, ["name"] = "Tricks of the Trade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37062 }, ["description"] = "To pass the time, traders have been known to consume beverages of an inspired nature, if you know what I mean. Sometimes, they drink a bit too much. Your trader might have stumbled beyond the gates and passed out under a tree. It's been known to happen from time to time. Luckily, I have a brew that I use to rouse groggy traders. One splash and I find they're more willing to work.", ["objectivesText"] = "Find and rouse the missing Trader. Progress: Trading isn't always the most exciting enterprise. But I do enjoy it.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 118418 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37063] = { ["id"] = 37063, ["name"] = "Elekk Training: Cruel Ogres", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37063 }, ["description"] = "This beast is surely at home in Nagrand , and after the years of domestication by Draenei it will be quite easy to train. We shall face it against the ogres of the region that you are familiar with. The Gorian Beast-Lasher , the one that smells of blood and fear, see how this elekk reacts to him.", ["objectivesText"] = "Defeat the Gorian Beast-Lasher while riding your Meadowstomper-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37064] = { ["id"] = 37064, ["name"] = "Elekk Training: Darkwing Roc", ["level"] = 38, ["requiredLevel"] = 38, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37064 }, ["description"] = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both. Travel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc . It will be a good test for your mount.", ["objectivesText"] = "Defeat the Darkwing Roc while riding your Meadowstomper-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 6495, ["rewardItems"] = { 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
