[37069] = { ["id"] = 37069, ["name"] = "Elekk Training: The Garn", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37069 }, ["description"] = "The last test for your mount will pit it against one of the great terrors of this land. The garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them. There is a lone garn that calls Nagrand its home. Take your elekk, mount up, and bring it down. If the two of you survive, your elekk will truly be ready.", ["objectivesText"] = "Defeat Maimclaw while riding your Meadowstomper-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 116662, 118349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37071] = { ["id"] = 37071, ["name"] = "Riverbeast Training: Gezz'ran", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37071 }, ["description"] = "This bulbous beast has spent a number of years in the wilds of Talador . We will begin the training there. It is already docile, as well, so I do not think it will take as long to train as the others. As you know, stalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your riverbeast can't overcome this natural defense mechanism.", ["objectivesText"] = "Defeat Gezz'ran while riding your Riverbeast-In-Training.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 118350 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
