[37305] = { ["id"] = 37305, ["name"] = "Bronze Victory", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37305 }, ["objectivesText"] = "Progress: Surrounded as we are, we cannot be weak. We must win every battle, and win them decisively.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 119153 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
