[37416] = { ["id"] = 37416, ["name"] = "Feast of the Spires", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 37416 }, ["description"] = "Boss-mon, I prepared a great feast for you right over dere. You should be havin' a bite or two before you be goin' out for da day. Trust me, you will feel much betta if you do!", ["objectivesText"] = "Eat a Feast of the Spires at Axefall.", ["rewardGold"] = 30900, ["rewardXP"] = 515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[37417] = { ["id"] = 37417, ["name"] = "Feast of the Spires", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["storyline"] = { 37417 }, ["description"] = "Commander, I prepared a great feast for ye right over there. You should be have a bite o' two before you be go out fer the day. Trust me, it's good fer ya!", ["objectivesText"] = "Eat a Feast of the Spires at Southport.", ["rewardGold"] = 30900, ["rewardXP"] = 515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
