[37433] = { ["id"] = 37433, ["name"] = "Proving Grounds", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37433 }, ["description"] = "Greetings commander. Word of your exploits has made its way back to Trial Master Rotun, and he has humbly requested to see your prowess in person. Fighting in his proving grounds would be an excellent way to spread your reputation to the farthest reaches of the Alliance, and beyond. If you're interested in proving yourself, talk to me to enter Trial Master Rotun's Proving Grounds.", ["objectivesText"] = "Speak with Lieutenant Thorn to enter the Proving Grounds, and then complete a Bronze trial. Progress: Have you completed your challenge?", ["rewardGold"] = 341600, ["rewardXP"] = 2040, ["rewardItems"] = { 17690, 17691, 19483, 19484, 119457, 119458, 119459, 119460, 119461, 119462, 119463, 119464 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37434] = { ["id"] = 37434, ["name"] = "Proving Grounds", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37434 }, ["description"] = "Hail commander. Word of your exploits has made its way back to Trial Master Rotun, and he has requested to see your prowess in person. Fighting in his proving grounds would be an excellent way to spread your reputation to the farthest reaches of the Horde, and beyond. If you're interested in proving yourself, talk to me to enter Trial Master Rotun's Proving Grounds.", ["objectivesText"] = "Speak with Warmaster Zog in your garrison to enter the Proving Grounds, and then complete a Bronze trial. Progress: Have you completed your challenge?", ["rewardGold"] = 341600, ["rewardXP"] = 2040, ["rewardItems"] = { 17690, 17691, 19483, 19484, 119457, 119458, 119459, 119460, 119461, 119462, 119463, 119464 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37439] = { ["id"] = 37439, ["name"] = "Thirst Unending", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6455, ["mapID"] = 94, ["storyline"] = { 37439 }, ["description"] = "If there is only one lesson you deign to remember from your time on Sunstrider Isle , let it be this - control your thirst for magic. It is a thirst unending, <name> - what you absorb must be controlled and released via Arcane Torrent. Failure is to become one of the Wretched... hopelessly addicted and insane. Seek out a mana wyrm and unleash your Arcane Torrent upon it. Learn to master your power. When you have sufficiently released an Arcane Torrent, return to me.", ["objectivesText"] = "Use your Arcane Torrent racial ability on a Mana Wyrm, then return to Arcanist Helion . Progress: It is not an option or a choice... you must quench your magical thirst. To fail in this is to fail as a <race>. Those who thought they could control their needs without tutoring now find themselves as one of the Wretched. You do NOT want to end up as an insane addict. Believe me.", ["rewardXP"] = 200, ["rewardItems"] = { 20999, 21000, 21001, 131236 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15297, ["x"] = 0.372, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15297, ["x"] = 0.372, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.372, ["y"] = 0.19 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 6455 } }, ["questType"] = "standard" },
[37440] = { ["id"] = 37440, ["name"] = "A Fistful of Slivers", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6455, ["mapID"] = 94, ["storyline"] = { 37440 }, ["description"] = "It's a shame that we've lost control of many of the creatures here on the island. This was once a tranquil place of study and research. Now it's all we can do to keep from being attacked by our own creations! I'm going to offer you a chance to receive a magical boon in exchange for some collecting work on your part. Bring me a stack of arcane slivers that are found on the mana-using creatures of Sunstrider Isle , and I will cast a spell on you that should aid your adventures on the isle.", ["objectivesText"] = "Collect 6 Arcane Slivers from any creature on the isle that uses mana, and then return to Arcanist Ithanas on Sunstrider Isle . Progress: Many of the creatures here on the isle were at one point bound into non-aggression and complacency by our magical skills. When the Scourge destroyed the Sunwell, our hold over these creatures shattered. Arcane slivers are the remnants of the control we once had, and as such might be usable in fashioning a new device to aid us in regaining their control. Better still, perhaps the slivers could be used to see what malaise the isle truly suffers under...", ["rewardXP"] = 200, ["rewardItems"] = { 20482, 20991 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15296, ["x"] = 0.382, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15296, ["x"] = 0.382, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.382, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 6455 } }, ["questType"] = "standard" },
[37442] = { ["id"] = 37442, ["name"] = "The Shrine of Dath'Remar", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6455, ["mapID"] = 467, ["storyline"] = { 37442 }, ["description"] = "Day after day I stand here, watching, waiting. I've been accused of dwelling too much on our past, while my eyes look to the horizon. But it is my firm belief that each visitor to this island should honor those who have sacrificed all so that they may continue to do so. Dath'Remar Sunstrider was our first king. He led us here from Kalimdor through the Maelstrom. Seek out his shrine to the west and do not return to me until you have read the plaque upon it in his honor.", ["objectivesText"] = "Read the plaque on the Shrine of Dath'Remar and then return to Well Watcher Solanian at the Sunspire on Sunstrider Isle .", ["rewardGold"] = 400, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 467, ["npcID"] = 15295, ["x"] = 0.64, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 467, ["npcID"] = 15295, ["x"] = 0.64, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 467, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 467 }, ["zone"] = { 6455 } }, ["questType"] = "standard" },
[37443] = { ["id"] = 37443, ["name"] = "Solanian's Belongings", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6455, ["mapID"] = 467, ["storyline"] = { 37443 }, ["description"] = "With all the chaos happening here at the Sunspire, I haven't had a chance to collect my belongings I've left outside at various places on the isle. I must maintain my vigil over the Sunwell here, so I'll ask you to collect them in my stead. I need my scrying orb, my scroll of Scourge magic , and my journal. Use this satchel for some extra space, as my things are rather bulky. Return them to me and I'll give you a little something - you know, for the effort; you can keep the satchel as well!", ["objectivesText"] = "Collect Well Watcher Solanian's Scrying Orb , his Scroll of Scourge Magic , and his Journal. They are found on Sunstrider Isle by the pond, the fountain, and one of the Burning Crystals. Return them to the Well Watcher at the Sunspire on Sunstrider Isle when you've collected them all. Progress: Have you had a chance to find my belongings? Once we reassert our dominance over Sunstrider Isle , I will need them in my work. For now though, I must maintain my watch over the Sunwell... or what remains of it.", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 20470, 20471, 20472, 20474, 20995, 20996, 131235 }, ["starts"] = { { ["mapID"] = 467, ["npcID"] = 15295, ["x"] = 0.64, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 467, ["npcID"] = 15295, ["x"] = 0.64, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 467, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 467 }, ["zone"] = { 6455 } }, ["questType"] = "standard" },
[37444] = { ["id"] = 37444, ["name"] = "Inoculation", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["description"] = "Zhanaa needs our help to salvage parts from the Exodar. Taerix prepared an inoculum that can be given to the Nestlewood owlkin that live in the area of a lot of the salvage. Just get close to the unaffected ones and use the crystal on them. Unfortunately, you'll have to kill the others. You'll find the owlkin at Nestlewood Thicket and Nestlewood Hills to the southeast.", ["objectivesText"] = "Use the Inoculating Crystal on 6 Nestlewood Owlkin. Then return to Vindicator Aldar at the Crash Site in Ammen Vale . Progress: The more we can do to clear up Nestlewood, the faster Zhanaa can get back to work.", ["rewardGold"] = 107000, ["rewardXP"] = 250, ["rewardItems"] = { 118, 2454, 5997, 22962, 152096, 237812 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16535, ["x"] = 0.794, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16535, ["x"] = 0.794, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.794, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 12, ["flags"] = 0 } } },
[37445] = { ["id"] = 37445, ["name"] = "Spare Parts", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["description"] = "We managed to recover a damaged holographic emitter from the crash. If we repair it, we'll have a chance to find other survivors outside of Ammen Vale . There were devices from the ship that could be salvaged for spare parts in the area, but the local owlkin carried them off before we could get to them. <name>, you must go south to Nestlewood Thicket and Hills to find the spare parts.", ["objectivesText"] = "Collect 4 Emitter Spare Parts and then return to Technician Zhanaa at the Crash Site in Ammen Vale . Progress: When we have those spare parts, I know that we'll get this emitter repaired. With any luck there will be someone else out there left to talk to.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 22978, 24423, 24424, 24425, 57489, 57490, 57491, 131250, 131472 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17071, ["x"] = 0.794, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17071, ["x"] = 0.794, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.794, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 18, ["flags"] = 0 } } },
[37446] = { ["id"] = 37446, ["name"] = "Lazy Peons", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6451, ["mapID"] = 1, ["storyline"] = { 25126, 25127, 25131, 25132, 25133, 25135, 25136, 25152, 25172, 37446 }, ["description"] = "Cursed peons! They work hard gathering lumber from the trees of the valley, but they're always taking naps! I need someone to help keep the peons in line. You look like the right <race> for my task. Here, you take this blackjack and use it on any lazy peons you find sleeping on the job. A good smack will get them right back to work! Return the blackjack when you're done. Look for them underneath the trees in the valley. Lousy slacking peons...", ["objectivesText"] = "Use the Foreman's Blackjack on 4 Lazy Peons when they're sleeping. Progress: No good lazy... Eh? Do you have my blackjack? Did you catch any peons sleeping on the job?!", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["rewardItems"] = { 16114 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 11378, ["x"] = 0.434, ["y"] = 0.674 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 11378, ["x"] = 0.434, ["y"] = 0.674 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6451 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 461, ["questLines"] = { { ["id"] = 1227, ["name"] = "Valley of Trials", ["orderIndex"] = 5, ["flags"] = 0 } } },
[37452] = { ["id"] = 37452, ["name"] = "Sealing Fate: Heap of Apexis Crystals", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7332, ["storyline"] = { 37452 }, ["objectivesText"] = "Progress: Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be more efficient for you? I leave the choice up to you. Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I may have others.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7332 } }, ["questType"] = "standard" },
[37453] = { ["id"] = 37453, ["name"] = "Sealing Fate: Mountain of Apexis Crystals", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7332, ["storyline"] = { 37453 }, ["objectivesText"] = "Progress: Four times the cost of the first, but only one seal. Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice. Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I may have others.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7332 } }, ["questType"] = "standard" },
