[37563] = { ["id"] = 37563, ["name"] = "The Frostwolves Stand Ready", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 37563 }, ["description"] = "Though we have lost much this day, the Frostwolves stand ready to uphold our pact with your people. To honor this agreement, some of my clan have asked to join your ranks and fight alongside your forces. Our numbers are strained so I ask that you chose only one. Speak with me when you have made your decision.", ["objectivesText"] = "Choose a follower (either Greatmother Geyah, Kal'gor the Honorable, or Lokra) and then speak with Makar Stonebinder . Progress: Have you decided which orc to take with you?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 76730, ["x"] = 0.757, ["y"] = 0.55 }, { ["mapID"] = 525, ["npcID"] = 88147, ["x"] = 0.782, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 76730, ["x"] = 0.757, ["y"] = 0.55 }, { ["mapID"] = 525, ["npcID"] = 88147, ["x"] = 0.782, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.757, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
