[37749] = { ["id"] = 37749, ["name"] = "Trials of Khadgar: Iron Maidens", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6967, ["storyline"] = { 37749 }, ["objectivesText"] = "Defeat the Iron Maidens encounter, with the following conditions.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6967 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Avoid Detonation Sequence", ["amount"] = 1, ["type"] = 0, ["objectID"] = 77231, ["orderIndex"] = 0 } } },
[37756] = { ["id"] = 37756, ["name"] = "Walled City: Brackenspore", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37756 }, ["description"] = "The Iron Horde is just one of the threats we must deal with on Draenor. We must also clean up the chaos they are leaving in their wake. Brackenspore , ancient walker of the deep, was drawn from the waters near Highmaul by the presence of the Iron Horde. He spreads his fungal growth in his wake and will eradicate all of us if left unchecked. Travel to Highmaul and defeat Brackenspore .", ["objectivesText"] = "Defeat Brackenspore in Highmaul .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 123975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[37757] = { ["id"] = 37757, ["name"] = "Arcane Sanctum: Ko'ragh", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "weekly", "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37757 }, ["description"] = "Forget all you know of the ogres on Azeroth, <name>. On Draenor they commanded a once-mighty civilization. Even now they threaten to reclaim their former glory. Highmaul excavations in Nagrand unearthed a mysterious relic. The only ogre to survive direct exposure to this relic was Ko'ragh ; he was left with a near-complete immunity to all magic. Ko'ragh must be killed before the ogres learn to replicate his unique powers. Travel to Highmaul and defeat Ko'ragh !", ["objectivesText"] = "Defeat Ko'ragh in Highmaul .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 123975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[37758] = { ["id"] = 37758, ["name"] = "Imperator's Rise: Imperator Mar'gok", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37758 }, ["description"] = "The conditions are ripe for a decisive attack against the Highmaul , commander. Will you engage? Descended from a long line of sorcerers, Imperator Mar'gok is the grand Imperator of Highmaul . He is both cunning and brutal, and allied himself with the Iron Horde when he recognized what it would be to oppose them. Travel to Highmaul and defeat Imperator Mar'gok . Without their leader, the Ogre Empire will descend into chaos for many years.", ["objectivesText"] = "Defeat Imperator Mar'gok in Highmaul .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 123975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[37762] = { ["id"] = 37762, ["name"] = "Slagworks: Heart of the Mountain", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37762 }, ["description"] = "Blackrock orcs fight like no other clan. They rely on arms and armor forged in the heart of their unnatural crucibles. Deep within the Foundry of the Blackrock clan is a furnace powered by a primal force known as the Heart of the Mountain . Destroy it, and deprive our foe of the arms they rely on. Travel to Blackrock Foundry and defeat the Heart of the Mountain .", ["objectivesText"] = "Defeat the Heart of the Mountain at the Blast Furnace in Blackrock Foundry .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 123975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[37763] = { ["id"] = 37763, ["name"] = "The Black Forge: Kromog", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37763 }, ["description"] = "Commander. Frostwolf scouts report that blackrock miners dug up a magnaron, and they've coerced the beast into helping them to create their infernal machines. They call it \" Kromog .\" We must destroy it, <name>. Travel to Blackrock Foundry and defeat Kromog .", ["objectivesText"] = "Defeat Kromog in Blackrock Foundry . Progress: Da defeat of Kromog will hinder da Iron Horde's operations within da Foundry.", ["rewardGold"] = 679200, ["rewardXP"] = 1365, ["rewardItems"] = { 123975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[37764] = { ["id"] = 37764, ["name"] = "Iron Assembly: Admiral Gar'an", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37764 }, ["description"] = "Our forces are making progress on land, but victory at sea still eludes us. We must take out the Iron Horde leadership while they are in harbor. Gar'an, Admiral of the Iron Horde fleet and first of the so-called Iron Maidens, is tactically brilliant. She, along with her lieutenants, Marak, and Sorka, have crushed all who have been sent to oppose them. Travel to Blackrock Foundry and defeat Admiral Gar'an .", ["objectivesText"] = "Defeat Admiral Gar'an in Blackrock Foundry .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 123975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[37765] = { ["id"] = 37765, ["name"] = "Blackhand's Crucible: Blackhand", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37765 }, ["description"] = "Grommash Hellscream relied on the strength of his Warlords to keep the Iron Horde under his control. It is time to strike a decisive blow. Blackhand , Warlord of the Blackrock clan, is a dauntless warrior and ruthless tyrant. He is second only to Grommash within the Iron Horde and oversees operations in the Foundry from atop its Crucible. Travel to the Blackrock Foundry and defeat Blackhand .", ["objectivesText"] = "Defeat Blackhand in the Blackrock Foundry .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 123975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[37766] = { ["id"] = 37766, ["name"] = "Walled City: Brackenspore", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37766 }, ["description"] = "If it ain't one threat, it's another - I swear this light-forsaken world would try to eat us alive even without no Horde to fight. Brackenspore , ancient walker of the deep, was drawn from the waters near Highmaul by the presence of the Iron Horde. That thing is already spreading like a disease, <name>. Ye got to put it down! Travel to Highmaul and defeat Brackenspore before he gets too powerful to stop.", ["objectivesText"] = "Defeat Brackenspore in Highmaul .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 123975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "raid" },
[37767] = { ["id"] = 37767, ["name"] = "Arcane Sanctum: Ko'ragh", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37767 }, ["description"] = "Ye know the name \" Ko'ragh ?\" One of them Highmaul ogres. They dug up a relic some time ago that killed everyone it touched but for Ko'ragh ... givin' him a near-complete immunity to all magic. Ogres ain't meant to have that kind of power! Travel to Highmaul and defeat Ko'ragh , before they learn to use him against us.", ["objectivesText"] = "Defeat Ko'ragh in Highmaul . Progress: Why would Ko'ragh remain a lackey to the sorcerer king despite his unique gifts? Ogres.", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 123975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "raid" },
[37768] = { ["id"] = 37768, ["name"] = "Imperator's Rise: Imperator Mar'gok", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37768 }, ["description"] = "I never thought much of them ogres, not until I saw a Highmaul legion on the march. Like a wall o' armored muscle, backed by the magics o' the emperor's best sorcerers. Never underestimate an ogre. Imperator Mar'gok is the grand Imperator of Highmaul . Aye, he's a cunning one - allied himself with the Iron Horde, he did. If we're to break up the party, we'd best start at the top. Travel to Highmaul and defeat Imperator Mar'gok !", ["objectivesText"] = "Defeat Imperator Mar'gok in Highmaul .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 123975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "raid" },
[37769] = { ["id"] = 37769, ["name"] = "Slagworks: Heart of the Mountain", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37769 }, ["description"] = "Blackrock warriors use weapons forged in cursed fire by the breath of a creature o' pure flame: The Heart o' the Mountain. Let's disarm 'em, <boy/lass>! Destroy that infernal creature, and the Blackrock won't have enough heat to fuel their Blast Furnace. Travel to Blackrock Foundry and defeat the Heart o' the Mountain.", ["objectivesText"] = "Defeat the Heart of the Mountain at the Blast Furnace in Blackrock Foundry .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 123975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "raid" },
[37770] = { ["id"] = 37770, ["name"] = "The Black Forge: Kromog", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37770 }, ["description"] = "Yer garrison scouts report that blackrock miners dug up a magnaron, and that the filthy beast has begun helpin' those brutes churn out their infernal machines. They call it \" Kromog .\" Travel to Blackrock Foundry and slay that fiend!", ["objectivesText"] = "Defeat Kromog in Blackrock Foundry .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 123975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "raid" },
[37771] = { ["id"] = 37771, ["name"] = "Iron Assembly: Admiral Gar'an", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37771 }, ["description"] = "\"If ye want to topple a wall, start with the foundation.\" It's an old Dwarf saying. If we take out the Iron Horde's leadership, the whole thing tumbles. Gar'an is the Admiral o' the Iron Horde fleet and first of the so-called \"Iron Maidens.\" She, along with her lieutenants, Marak, and Sorka, have dominated the seas of Draenor. No more, <name>. Travel to Blackrock Foundry and defeat Admiral Gar'an .", ["objectivesText"] = "Defeat Admiral Gar'an in Blackrock Foundry .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 123975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "raid" },
[37772] = { ["id"] = 37772, ["name"] = "Blackhand's Crucible: Blackhand", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37772 }, ["description"] = "Ol' Grommash cannot rule the Iron Horde without his Warlords keeping the clans in line. Let's deal 'em a blow that they can't recover from! Blackhand , Warlord of the Blackrock clan, is a dauntless warrior and ruthless tyrant. He's second only to Grommash within the Iron Horde and oversees operations in the Foundry from atop its Crucible. Travel to the Blackrock Foundry and defeat Blackhand .", ["objectivesText"] = "Defeat Blackhand in the Blackrock Foundry .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 123975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "raid" },
[37773] = { ["id"] = 37773, ["name"] = "Death to Amethon!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37773 }, ["description"] = "Foreman Eksos down in your Talador outpost figures he has the answer for why there's been so much seismic activity recently. See, there's this giant, ah... earth fury, I think they're called, and it's covered in these powerful crystals in a cave up above Kuuro's Claim. The crystals hum real loud and we think it's driving the fury crazy! Problem is, nobody's got the firepower to take the thing down so we can examine a sample. Think you could lend us a hand, commander?", ["objectivesText"] = "Retrieve a Humming Draenite Spike from Amethon above Kuuro's Claim in Talador. Progress: Sir, what is that you have there?", ["rewardGold"] = 1488770, ["rewardXP"] = 1365, ["rewardItems"] = { 32572, 122133, 122190, 122191 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "group" },
[37774] = { ["id"] = 37774, ["name"] = "Death to Gor'thul!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37774 }, ["description"] = "Saberon spirit army. I ain't pullin' your leg, commander, that's what we've got coming for us if we don't act fast. The Shattered Hand shaman Gor'thul was spotted down in Spires of Arak in the Bloodmane Pridelands right about the same time we started hearing reports of saberon spirits raiding our supply caravans. I don't want to take any chances, commander. I think you should personally head down there and put a stop to this before it starts.", ["objectivesText"] = "Slay Gor'thul at Bloodmane Pridelands in Spires of Arak.", ["rewardGold"] = 1488770, ["rewardXP"] = 1365, ["rewardItems"] = { 32572, 109223, 122190, 122191 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "group" },
[37775] = { ["id"] = 37775, ["name"] = "Death to Nullifier Darkoor!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37775 }, ["description"] = "You ever heard of the Ring of Blood, commander? It's pretty simple. Big ogre named Mogor loves watching people fight for their lives against savage beasts. Ambitious goblin called Gurgthock arranges the fights and rakes in the profits. Anwyays, Gurgthock and I are long time buddies and he's arranged a special exhibition match just for you! Pretty sweet, right? Just whisper into his ear \"I seek the seeker.\"", ["objectivesText"] = "Speak to Gurgthock at the Ring of Blood in Nagrand and win the special exhibition match.", ["rewardGold"] = 1641940, ["rewardXP"] = 1365, ["rewardItems"] = { 32572, 122190, 122191, 122274 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "group" },
[37776] = { ["id"] = 37776, ["name"] = "Death to Undertow!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37776 }, ["description"] = "Good day to ya, commander! I have bad news. We've been contracting out some spy work to the local fisherman - we pay 'em some coin, they take their boats out north of Umbrafen and see what the Iron Horde's up to. Win-win, right? Well, it turns out... no. Every boat that goes out never comes back. Apparently this giant water elemental, Undertow I think it was, is murdering the snot out of everyone that passes through. Any chance you could clear it out for us, commander?", ["objectivesText"] = "Kill Undertow in the Tanaan Channel north of Umbrafen in Shadowmoon Valley.", ["rewardGold"] = 1641940, ["rewardXP"] = 1365, ["rewardItems"] = { 32572, 122190, 122191, 122241 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "group" },
[37777] = { ["id"] = 37777, ["name"] = "Death to Tremor!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37777 }, ["description"] = "Your outpost in Gorgrond has a serious saberon problem, commander, and we can't really afford to keep sending more troops to help 'em out. So I have an idea. There's an enormous worm beast on the west coast of Gorgrond called Tremor, better known as the devourer of lobstroks. If you took that thing down and brought the, well, pile of partially digested lobstrok meat back here, we can cook it here, ship it back there, use it to calm the saberon for a good long time!", ["objectivesText"] = "Kill Tremor west of Gorgorek's Fall in Gorgrond and obtain the Pile of Partially Digested Lobstrok Meat . Progress: Orders commander? And what is that awful smell?!", ["rewardGold"] = 899940, ["rewardXP"] = 1365, ["rewardItems"] = { 32572, 122132, 122190, 122191 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "group" },
[37778] = { ["id"] = 37778, ["name"] = "Death to Hivelord Ik'rix!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37778 }, ["description"] = "We've got a radical new idea to try using ice ravager carapaces in our tempering process for armor and weapons. It's the sort of trailblazing work we strive for, commander! Only problem is, ravagers apparently aren't keen on our guys and gals taking their carapaces off of them. There's this particular ravager at the Southwind Cliffs in Frostfire Ridge called Hivelord Ik'rix - if you could take him down we wouldn't need more for weeks!", ["objectivesText"] = "Retrieve the Iceshatter Carapace from Hivelord Ik'rix at Southwind Cliffs in Frostfire Ridge. Progress: Yes, commander?", ["rewardGold"] = 1641940, ["rewardXP"] = 1365, ["rewardItems"] = { 32572, 122134, 122190, 122191 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "group" },
[37780] = { ["id"] = 37780, ["name"] = "Auchindoun", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37780 }, ["description"] = "Commander, Gul'dan's favored agent Teron'gor has infiltrated Auchindoun in Talador and has already taken to devouring the countless souls within. We must not let this nefarious warlock gain any further strength. Enter the holy mausoleum of Auchindoun and rout Teron'gor and the rest of the Shadow Council before more damage is done.", ["objectivesText"] = "Defeat Teron'gor in Auchindoun .", ["rewardGold"] = 1239200, ["rewardXP"] = 690, ["rewardItems"] = { 113029, 113030, 113031, 119078, 119087 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "dungeon" },
[37781] = { ["id"] = 37781, ["name"] = "Bloodmaul Slag Mines", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37781 }, ["description"] = "The Bloodmaul ogres are brutal slavers, commander. Innocents from across Draenor are dragged deep into the volcanic slag mines in Frostfire Ridge to dredge up cart after cart of gems and ore, never to return. We suspect that they have turned their focus to unearthing an ancient relic of immense power for their sorcerer-king. The ogre Gug'rokk rules over the slag mines with an iron fist. Take him down and the mines will fall as well.", ["objectivesText"] = "Defeat Gug'rokk in the Bloodmaul Slag Mines . Progress: We can't allow da slag mines to operate. Gug'rokk has cracked his last whip against da bloody backs of the innocent.", ["rewardGold"] = 1239200, ["rewardXP"] = 355, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "dungeon" },
[37782] = { ["id"] = 37782, ["name"] = "Grimrail Depot", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37782 }, ["description"] = "We must move quickly, commander. As we speak the Grimrail is preparing to depart Grimrail Depot to deliver a massive battalion of troops to Shattrath. Rumor has it that they have outfitted the train with a weapon strong enough to shatter the shield protecting the inner city. Skylord Tovra has taken to guarding the train on its journey to Talador. You must stop Tovra and the Grimrail before it reaches Shattrath!", ["objectivesText"] = "Defeat Skylord Tovra in Grimrail Depot .", ["rewardGold"] = 1239200, ["rewardXP"] = 1200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "dungeon" },
[37783] = { ["id"] = 37783, ["name"] = "Iron Docks", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37783 }, ["description"] = "The Iron Docks is one of the Iron Horde's greatest assets in this war. Our scouts have reported that the docks are alight with activity, indicating imminent attack. Skulloc , son of Gruul, was seen leaving the Blackrock Foundry, armed to the teeth with powerful cannons, and has been loaded onto their mightiest warship. It does not matter where they intend to strike, commander - you must sack the Iron Docks and defeat Skulloc before they ever leave.", ["objectivesText"] = "Defeat Skulloc in the Iron Docks .", ["rewardGold"] = 1239200, ["rewardXP"] = 525, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "dungeon" },
[37785] = { ["id"] = 37785, ["name"] = "Skyreach", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37785 }, ["description"] = "High Sage Viryx has finished a devastating crystal superweapon atop the highest point in Skyreach in Spires of Arak. She intends to eradicate the 'lesser races' in the name of their god Rukhmar. The arakkoa outcasts were nearly wiped out in mere seconds by the weapon. You must stop Viryx before she turns her sights to your garrison, commander.", ["objectivesText"] = "Defeat High Sage Viryx in Skyreach .", ["rewardGold"] = 1123600, ["rewardXP"] = 1030, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "dungeon" },
[37786] = { ["id"] = 37786, ["name"] = "The Everbloom", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37786 }, ["description"] = "The Kirin Tor created an outpost in Gorgrond with a portal to Stormwind to facilitate quick reinforcements in the assault on the Blackrock Foundry. In their infinite wisdom they built it in the heart of the Everbloom , home to the botani and the mightiest of the genesaur - Yalnu . The outpost has already been overrun and it is only a matter of time before the overgrowth spreads to Stormwind... and with it the whole of Azeroth.", ["objectivesText"] = "Defeat Yalnu in the Everbloom .", ["rewardGold"] = 679200, ["rewardXP"] = 1200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "dungeon" },
[37787] = { ["id"] = 37787, ["name"] = "Upper Blackrock Spire", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37787 }, ["description"] = "Hellscream's Ironmarch vanguard managed to reach Blackrock Mountain and has allied with Warlord Zaela of the Dragonmaw clan. Even now the Iron Horde readies to invade Azeroth while Zaela prepares a doomsday weapon in the heart of the mountain to ensure nothing stands in their way. You must put a stop to Zaela once and for all, commander. She has been a thorn in our side for too long.", ["objectivesText"] = "Defeat Warlord Zaela in Upper Blackrock Spire .", ["rewardGold"] = 1239200, ["rewardXP"] = 1200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "dungeon" },
[37788] = { ["id"] = 37788, ["name"] = "Treasure Contract: Gutrek's Cleaver", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37788 }, ["series"] = { 37797, 37798, 37799, 37811, 37992 }, ["description"] = "In Nagrand , the ogres tell of an ancient weapon called Gutrek's cleaver. I would very much like to study it. A goblin treasure hunter by the name of Val Goldspade discovered the whereabouts of the weapon. Unfortunately, this goblin has gone missing somewhere in the Broken Precipice - probably after a run-in with the locals.", ["objectivesText"] = "Search the ogres in the Broken Precipice for clues regarding Goldspade's discovery.", ["rewardGold"] = 70225, ["rewardXP"] = 1365, ["rewardItems"] = { 119093, 120989, 120998, 121814, 121822, 122399, 122404, 122407, 122409, 122415, 122417, 122423, 122424 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37789] = { ["id"] = 37789, ["name"] = "Upper Blackrock Spire", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37789 }, ["description"] = "Hellscream's Ironmarch vanguard managed to reach Blackrock Mountain and has allied with Warlord Zaela o' the Dragonmaw clan. Even now the Iron Horde readies to invade Azeroth while Zaela prepares a doomsday weapon in the heart o' the mountain to ensure nothing stands in their way. You must put a stop to Zaela once and for all, commander. She's been a thorn in our side for too long.", ["objectivesText"] = "Defeat Warlord Zaela in Upper Blackrock Spire .", ["rewardGold"] = 1239200, ["rewardXP"] = 1200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37790] = { ["id"] = 37790, ["name"] = "The Everbloom", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37790 }, ["description"] = "The Kirin Tor created an outpost in Gorgrond with a portal to Stormwind to facilitate quick reinforcements in the assault on the Blackrock Foundry. Unfortunately they built it in the heart o' the Everbloom , home to the botani and the mightiest o' the genesaur - Yalnu . The outpost has already been overrun and it is only a matter o' time before the overgrowth spreads to Stormwind... and with it the whole of Azeroth.", ["objectivesText"] = "Defeat Yalnu in the Everbloom .", ["rewardGold"] = 1239200, ["rewardXP"] = 1200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37791] = { ["id"] = 37791, ["name"] = "Skyreach", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37791 }, ["description"] = "High Sage Viryx has finished a devastatin' crystal superweapon atop the highest point in Skyreach in Spires of Arak. She intends to eradicate the 'lesser races' in the name of their god Rukhmar. The arakkoa outcasts were nearly wiped out in mere seconds by the weapon. You must stop Viryx before she turns her sights to your garrison!", ["objectivesText"] = "Defeat High Sage Viryx in Skyreach .", ["rewardGold"] = 1239200, ["rewardXP"] = 1030, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37793] = { ["id"] = 37793, ["name"] = "Iron Docks", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37793 }, ["description"] = "The Iron Docks is one o' the Iron Horde's greatest assets in this war. Our scouts have reported that the docks are alight with activity, indicatin' imminent attack. Skulloc , son o' Gruul, was seen leavin' the Blackrock Foundry, armed to the teeth with powerful cannons, and has been loaded onto their mightiest warship. It doesn't matter where they intend to strike, commander - you must sack the Iron Docks and defeat Skulloc before they ever leave!", ["objectivesText"] = "Defeat Skulloc in the Iron Docks .", ["rewardGold"] = 679200, ["rewardXP"] = 525, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37794] = { ["id"] = 37794, ["name"] = "Grimrail Depot", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37794 }, ["description"] = "We must move quickly, commander. As we speak the Grimrail is preparing to depart Grimrail Depot to deliver a massive battalion o' troops to Shattrath. Rumor has it that they have outfitted the train with a weapon strong enough to shatter the shield protectin' the inner city. Skylord Tovra has taken to guardin' the train on its journey to Talador. You must stop Tovra and the Grimrail before it reaches Shattrath!", ["objectivesText"] = "Defeat Skylord Tovra in Grimrail Depot .", ["rewardGold"] = 1239200, ["rewardXP"] = 1200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37795] = { ["id"] = 37795, ["name"] = "Bloodmaul Slag Mines", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37795 }, ["description"] = "The Bloodmaul ogres are brutal slavers, commander. Innocents from across Draenor are dragged deep into the volcanic slag mines in Frostfire Ridge to dredge up cart after cart o' gems and ore, never to return. We suspect that they have turned their focus to unearthin' an ancient relic o' immense power for their sorcerer-king. The ogre Gug'rokk rules over the slag mines with an iron fist. Take him down and the mines will fall as well.", ["objectivesText"] = "Defeat Gug'rokk in the Bloodmaul Slag Mines .", ["rewardGold"] = 1239200, ["rewardXP"] = 355, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37796] = { ["id"] = 37796, ["name"] = "Auchindoun", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37796 }, ["description"] = "Commander, Gul'dan's favored agent Teron'gor has infiltrated Auchindoun in Talador and has already taken to devourin' the countless souls within. We mustn't let this nefarious warlock gain any further strength. Enter the holy mausoleum o' Auchindoun and rout Teron'gor and the rest o' the Shadow Council before more damage is done.", ["objectivesText"] = "Defeat Teron'gor in Auchindoun .", ["rewardGold"] = 679200, ["rewardXP"] = 690, ["rewardItems"] = { 113029, 113030, 113031, 119078, 119087 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "dungeon" },
[37797] = { ["id"] = 37797, ["name"] = "Gutrek's Cleaver: The First Piece", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 37797 }, ["series"] = { 37788, 37798, 37799, 37811, 37992 }, ["description"] = "The journal points to the location of the pieces of Gutrek's Cleaver. It reads: \"The pommel was brought to the Broken Precipice, where it was to be housed in the skull of Gutrek's first kill. It looks like it was some manner of large beast that he fought in the big bone pit.\"", ["objectivesText"] = "Follow the clue from the journal to find Gutrek's pommel .", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 119093, 120989, 120997, 120998, 121814, 121822 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[37798] = { ["id"] = 37798, ["name"] = "Gutrek's Cleaver: The Second Piece", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 37798 }, ["series"] = { 37788, 37797, 37799, 37811, 37992 }, ["description"] = "The search for Gutrek's Cleaver continues. The journal reads: \"The hilt was to be buried in the marshlands, among the serpents whose poison claimed Gutrek's life. There's something here about covering it with a spiral stone, which is supposed to keep Gutrek's spirit at bay somehow.\"", ["objectivesText"] = "Follow the clue from the journal to find Gutrek's hilt .", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 119093, 120979, 120989, 120998, 121814, 121822 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[37799] = { ["id"] = 37799, ["name"] = "Gutrek's Cleaver: The Final Piece", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 37799 }, ["series"] = { 37788, 37797, 37798, 37811, 37992 }, ["description"] = "Only one piece remains. The journal reads: \"The final piece, Gutrek's blade , was to be displayed in a place of honor for all time overlooking the Ring of Blood. I don't think I've seen it there myself, but it says it's supposed to be somewhere where it has a clear view of every battle.\"", ["objectivesText"] = "Follow the clue from the journal to find Gutrek's blade .", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 119093, 120989, 120998, 121814, 121822 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[37811] = { ["id"] = 37811, ["name"] = "Gutrek's Cleaver: The Spirit Forge", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6755, ["storyline"] = { 37811 }, ["series"] = { 37788, 37797, 37798, 37799, 37992 }, ["description"] = "With the pieces recovered, all that is left is to reforge Gutrek's Cleaver . Goldspade's journal seems to indicate that the only place to do this is the location where it was initially dismantled. The journal mentions a \"Spirit Forge\" used to dismantle the blade, and that it may be located somewhere in the nearby gorge. Find the forge and use it to combine the pieces you've gathered.", ["objectivesText"] = "Locate the Spirit Forge in Earthshaker Gorge and reforge Gutrek's Cleaver . Progress: Did you find that old blade Dr. Jones was looking for?", ["rewardGold"] = 1653920, ["rewardXP"] = 1365, ["rewardItems"] = { 119093, 120989, 120998, 121814, 121822 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[37813] = { ["id"] = 37813, ["name"] = "Death to Amethon!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37813 }, ["description"] = "Foreman Grobash in da Talador outpost figures he knows why der's been so much seismic activity recently. Der be an earth fury called Amethon that be covered in powerful crystals in a cave up above Kuuro's Claim. Da crystals' hummin' be drivin' da fury crazy! We want a sample to see if we can figure out why da crystals are so powerful. I wouldn't be askin' ya if I thought anybody else could do it, commander.", ["objectivesText"] = "Retrieve a Humming Draenite Spike from Amethon above Kuuro's Claim in Talador. Progress: What be makin' that infernal racket? Is that the crystal from Amethon you be holdin'?", ["rewardGold"] = 1641940, ["rewardXP"] = 1365, ["rewardItems"] = { 32572, 122133, 122190, 122191, 122273, 128320 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group" },
[37814] = { ["id"] = 37814, ["name"] = "Death to Gor'thul!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37814 }, ["description"] = "We been hearin' 'bout some real, real bad voodoo in Spires of Arak, commander. Da Shattered Hand shaman Gor'thul be seen sneakin' about da spires the same time we be hearin' of saberon spirits attackin' our supply caravans and our arakkoa allies. I think it best if we take no chances. You should deal with da shaman personally before dis matter gets out of hand.", ["objectivesText"] = "Slay Gor'thul at Bloodmane Pridelands in Spires of Arak.", ["rewardGold"] = 1488770, ["rewardXP"] = 1365, ["rewardItems"] = { 32572, 122190, 122191 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group" },
[37815] = { ["id"] = 37815, ["name"] = "Death to Nullifier Darkoor!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37815 }, ["description"] = "Da goblin Gurgthock be requestin' your presence at the Ring of Blood in Nagrand, boss-mon. It seems that Mogor, da lord of da ring, be holdin' an exhibition match der and he want you to fight his newest acquisition. I think it be safe, commander. I heard of dis goblin's work before. If you be ready, whisper to him \"I seek da seeker.\"", ["objectivesText"] = "Speak to Gurgthock at the Ring of Blood in Nagrand and win the special exhibition match.", ["rewardGold"] = 1488770, ["rewardXP"] = 1365, ["rewardItems"] = { 32572, 122190, 122191 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group" },
[37816] = { ["id"] = 37816, ["name"] = "Death to Undertow!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37816 }, ["description"] = "We be havin' a problem, commander. We been sendin' some small boats into the Tanaan Channel north of da Umbrafen in Shadowmoon ta spy on da Alliance base der as well as da Iron Horde in Tanaan Jungle. Da problem is dat every boat we send out come back in pieces, if it come back at all. We think a water elemental called Undertow is da culprit. I know you be busy, but destroyin' that creature would be very helpful to our efforts.", ["objectivesText"] = "Kill Undertow in the Tanaan Channel north of Umbrafen in Shadowmoon Valley. Progress: Ey, commander. How you doin' dis fine day?", ["rewardGold"] = 899940, ["rewardXP"] = 1365, ["rewardItems"] = { 32572, 39563, 122190, 122191 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group" },
[37817] = { ["id"] = 37817, ["name"] = "Death to Tremor!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37817 }, ["description"] = "Da Gorgrond outpost be havin' troubles with saberon, and we can't afford ta throw troops at the problem any longer. Don't worry, I be havin' an idea. There be an enormous worm beast on the west coast of Gorgrond called Tremor, da devourer of lobstroks. If you killed da beast and brought da pile of lobstrok meat back here, we can cook it 'ere, send it to da outpost, and use it to calm da saberon for good!", ["objectivesText"] = "Kill Tremor west of Gorgorek's Fall in Gorgrond and obtain the Pile of Partially Digested Lobstrok Meat . Progress: Ey, commander. What be that awful smell?", ["rewardGold"] = 1641940, ["rewardXP"] = 1365, ["rewardItems"] = { 32572, 122132, 122190, 122191 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group" },
[37818] = { ["id"] = 37818, ["name"] = "Death to Hivelord Ik'rix!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 37818 }, ["description"] = "We been tryin' out a new way to temper weapons with ice ravager carapaces. Der icy hides are perfect for da process. Hivelord Ik'rix in da Southwind Cliffs nearby is rumored to be da largest ravager we ever seen - if you could bring its carapace back, we'd be able to make all sorts of things!", ["objectivesText"] = "Retrieve the Iceshatter Carapace from Hiveord Ik'rix at Southwind Cliffs in Frostfire Ridge. Progress: Ey, boss-mon. What can I do for you today?", ["rewardGold"] = 1641940, ["rewardXP"] = 1365, ["rewardItems"] = { 32572, 122134, 122190, 122191 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group" },
[37819] = { ["id"] = 37819, ["name"] = "Welcome to the Darkmoon Races", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 5, ["zoneID"] = 5861, ["storyline"] = { 37819 }, ["description"] = "So this is your first race, eh? Don't worry - it's easier than it looks. Let me break it down for you... Run through that big banner there. That starts everything. Then, follow the smaller banners until you see a big, blue Post. Hit that, then return here. You're scored on your time, so finish as fast as you can! And watch out for those electrified tripwires. They'll slow you down if you run through them. Good luck!", ["objectivesText"] = "Run through the Darkmoon Races Start Banner, hit the Blue Post, then return to the Darkmoon Races Start Banner. Progress: Hurry! Hit the blue post!", ["rewardGold"] = 30900, ["rewardXP"] = 25, ["rewardItems"] = { 74142, 93724, 122119, 122120, 122121, 122124, 122125, 122126, 122128, 122129 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[37834] = { ["id"] = 37834, ["name"] = "Orb of Dominion", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 37834 }, ["series"] = { 36007, 36009, 36010, 36012, 36013, 36014, 36016, 36017, 36018, 37836, 37837, 37841, 37964, 39023, 40501 }, ["description"] = "Gul'dan and his Shadow Council have their hooks embedded deep into Garona's soul. We've tried traditional magical methods and they haven't helped her. It's time to get unorthodox. <Khadgar cracks his knuckles, his eyes flashing with a disturbing eagerness.> I've just learned of a Shadow Council holdout hidden beneath the Draenei city of Elodor. They are using an Orb of Dominion to brainwash spies. Quickly! Assault the cave and recover the orb for me. We will turn this dark magic to our advantage.", ["objectivesText"] = "Retrieve an Orb of Dominion from the Den of Secrets in Shadowmoon Valley. Progress: <Khadgar's fingers glow in anticipation.> The orb! Did you find it?", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 119093, 122155 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[37835] = { ["id"] = 37835, ["name"] = "The Shadow War", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 535, ["storyline"] = { 37835 }, ["description"] = "The Shadow Council are more entrenched than you expected. A large contingent seems focused on infiltrating the draenei Exarch Council in the town above. Khadgar certainly wouldn't complain if you did a little... \"housecleaning.\"", ["objectivesText"] = "Slay 15 Shadow Council members in the Den of Secrets.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 }, { ["mapID"] = 539, ["npcID"] = 92213, ["x"] = 0.513, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535, 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[37836] = { ["id"] = 37836, ["name"] = "Breaking Badness", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 37836 }, ["series"] = { 36007, 36009, 36010, 36012, 36013, 36014, 36016, 36017, 36018, 37834, 37837, 37841, 37964, 39023, 40501 }, ["description"] = "It is time to liberate Garona. I know what to do... I think. I'd like you to stay close in case anything goes wrong. Speak with me when you are ready to begin.", ["objectivesText"] = "Speak with Khadgar and assist him as he frees Garona from Gul'dan's mind control.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 115523 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[37837] = { ["id"] = 37837, ["name"] = "An Inside Job", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 37837 }, ["series"] = { 36007, 36009, 36010, 36012, 36013, 36014, 36016, 36017, 36018, 37834, 37836, 37841, 37964, 39023, 40501 }, ["description"] = "If Garona's intelligence is correct, Gul'dan will be inside this Iron Horde compound. With Garona's help, slip inside, gather any info you find, and learn what Gul'dan intends to do. The guards are on high alert. Garona can \"liquidate\" individual guards for you, but she must not be seen! You will have to choose your targets carefully and pick your way through the bastion undetected. Don't let anyone sound the alarm. If things get too hot, I'll teleport you to safety. At least... I'll try.", ["objectivesText"] = "Infiltrate Bladefury's Command with Garona's help. Use her talents to eliminate guards without being seen. Locate Iron Horde intelligence and then spy on Gul'dan. Progress: Don't give up. I know you can do this. <Despite his words, Khadgar doesn't seem so sure.>", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 40727, 42898, 104299, 109076, 119093, 120945, 208128, 208129 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 90233, ["x"] = 0.674, ["y"] = 0.066 } }, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 90233, ["x"] = 0.674, ["y"] = 0.066 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.066 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[37839] = { ["id"] = 37839, ["name"] = "Light Be With You", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 525, ["storyline"] = { 37839 }, ["description"] = "You've done everything I've asked, <name>. I believe we can apply one final enchantment to your ring. But... we must be cautious. Last time I augmented your ring I killed you. (Sorry.) It will take a divine act to empower you further. Fortunately, you've made some powerful allies during your time here. Travel to the Temple of Karabor, where Yrel is waiting for you. With the blessing of a Naaru your ring will become as powerful and unique as - well, as you yourself. Go to Karabor. You've earned it.", ["objectivesText"] = "Meet Yrel at the Coliseum of Light near the Temple of Karabor.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 71086, 118663, 124634, 124635, 124636, 124637, 124638 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 91913, ["x"] = 0.734, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525, 534 }, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37840] = { ["id"] = 37840, ["name"] = "Draenor's Blessing", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 525, ["storyline"] = { 37840 }, ["description"] = "You've done everything I've asked, <name>. I believe we can apply one final enchantment to your ring. But... we must be cautious. Last time I augmented your ring I killed you. (Sorry.) It will take an act of ancient magic to empower you further. Fortunately, you've made some powerful allies during your time here. Seek out Farseer Drek'Thar at the Throne of Elements in Nagrand. There you can receive the blessing of the elements and safely unlock your ring's final form. Go, hero! Claim your reward!", ["objectivesText"] = "Speak with Drek'Thar at the Throne of the Elements in Nagrand. Progress: More than any other you embody the might of the Horde, champion.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["rewardItems"] = { 124634, 124635, 124636, 124637, 124638, 127785 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37841] = { ["id"] = 37841, ["name"] = "The Final Assault", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 37841 }, ["series"] = { 36007, 36009, 36010, 36012, 36013, 36014, 36016, 36017, 36018, 37834, 37836, 37837, 37964, 39023, 40501 }, ["description"] = "Our campaign in Draenor has taken an unexpected turn. With Gul'dan assuming power over the Iron Horde, history is poised to repeat itself - our world is in more peril than ever. It's time to bring the full might of your garrison to bear against Tanaan Jungle. Build a shipyard for your garrison! I will meet you at your new shipyard and we will discuss our next move from there.", ["objectivesText"] = "Speak with your faction leader in your garrison and complete the quests to build a shipyard. Khadgar will meet you there when it's built.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 127115 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 90233, ["x"] = 0.674, ["y"] = 0.066 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.066 }, ["mapCandidates"] = { ["npc"] = { 525, 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[37848] = { ["id"] = 37848, ["name"] = "Treasure Contract: Amulet of Rukhmar", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37848 }, ["series"] = { 37849, 37850, 37851, 37852, 37993 }, ["description"] = "It seems the Adherents of Rukhmar have stumbled upon some information leading to an ancient amulet, said to possess the power of their god and bestow it upon the wearer. We should make sure they don't find it. Head to Skettis and find what they have learned. Hopefully we can find it before they get to it.", ["objectivesText"] = "Search the ruins of upper Skettis for the Arakkoa research involving the Amulet of Rukhmar.", ["rewardGold"] = 14665, ["rewardXP"] = 1365, ["rewardItems"] = { 8827, 81354, 118711, 121819, 121820, 121823, 122399, 122404, 122407, 122409, 122415, 122417, 122423 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37849] = { ["id"] = 37849, ["name"] = "Amulet of Rukhmar: The First Key", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 8485, ["storyline"] = { 37849 }, ["series"] = { 37848, 37850, 37851, 37852, 37993 }, ["description"] = "The Arakkoa research points to three \"keys\" that need to be activated in order to use the Apexis device. The first is located in Skettis. The text mentioning it reads: \"The first key is kept in the high reaches of upper Skettis. It lay where the dead can protect it from the talons of the unwanted.\"", ["objectivesText"] = "Find and activate the first key to the Apexis device.", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 8827, 81354, 118711, 121819, 121820, 121823 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8485 } }, ["questType"] = "standard" },
[37850] = { ["id"] = 37850, ["name"] = "Amulet of Rukhmar: The Second Key", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6722, ["storyline"] = { 37850 }, ["series"] = { 37848, 37849, 37851, 37852, 37993 }, ["description"] = "The first point has been activated and two more remain. The second location is hinted at in the old outcast writing: \"Beneath the third fall of the great Skettis river lay the second key. May the ever-rushing waters sweep away those that might seek it.\"", ["objectivesText"] = "Find and activate the second key to the Apexis device.", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 8827, 81354, 118711, 121819, 121820, 121823 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37851] = { ["id"] = 37851, ["name"] = "Amulet of Rukhmar: The Final Key", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6722, ["storyline"] = { 37851 }, ["series"] = { 37848, 37849, 37850, 37852, 37993 }, ["description"] = "One last key is required to access the Apexis device. The writings pertaining to its location read: \"The final key has been housed deep within the fungal caves where the river makes its final drop. Though the pale orcs that dwell there may be vile, they should prove a worthy deterrent.\"", ["objectivesText"] = "Find and activate the final key to the Apexis device.", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 8827, 81354, 118711, 121819, 121820, 121823 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37852] = { ["id"] = 37852, ["name"] = "Amulet of Rukhmar: The Apexis Device", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6722, ["storyline"] = { 37852 }, ["series"] = { 37848, 37849, 37850, 37851, 37993 }, ["description"] = "Now that the keys have been activated, the Apexis device that leads to the amulet should be accessible. The Arakkoa research states that it is likely located in Lost Veil Anzu, within the \"shrine to the raven god.\"", ["objectivesText"] = "Activate the Apexis device and claim the Amulet of Rukhmar . Progress: Were you able to take the amulet from the arakkoa?", ["rewardGold"] = 1653920, ["rewardXP"] = 1365, ["rewardItems"] = { 8827, 81354, 118711, 121819, 121820, 121823 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6722 } }, ["questType"] = "standard" },
[37865] = { ["id"] = 37865, ["name"] = "Assault on Ironhold Harbor", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["storyline"] = { 37865 }, ["objectivesText"] = "Iron Horde Forces Thwarted Iron Horde Equipment Destroyed", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Iron Horde Forces Thwarted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Iron Horde Equipment Destroyed", ["amount"] = 34, ["type"] = 0, ["objectID"] = 90048, ["orderIndex"] = 1 } } },
