[37940] = { ["id"] = 37940, ["name"] = "Assault on Ironhold Harbor", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 37940 }, ["description"] = "The Iron Horde continues to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan. A strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.", ["objectivesText"] = "Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle .", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 90481, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[37941] = { ["id"] = 37941, ["name"] = "Treasure Contract: The Infected Orc", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 37941 }, ["series"] = { 37942, 37943, 37944, 37945 }, ["description"] = "In Gorgrond , the Laughing Skull clan has a legend of one called Skulltaker. His mask, known only as the Silent Skull, is legendary among the clan, and could help us learn more about them. Until recently, he was thought to have vanished. Now it appears he has shown his face, so to speak, in Everbloom Wilds. The last orc to have seen him fell to the botani there, but may still have some clues on how you can find Skulltaker and recover the mask. If the botani have him, he may not be cooperative.", ["objectivesText"] = "Find Grinning Tolg's journal among the mutated orcs in Everbloom Wilds.", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 116268, 119093, 122147, 122150, 122399, 122400, 122404, 122407, 122409, 122415, 122417, 122423 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[37942] = { ["id"] = 37942, ["name"] = "The Silent Skull: The First Reagent", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 37942 }, ["series"] = { 37941, 37943, 37944, 37945 }, ["description"] = "Grinning Tolg was in the process of brewing an elixir that would allow him to communicate with the ravagers, whom the Skulltaker relies on to remain hidden. The first ingredient, the leaves of the Shadethistle plant, can be found nearby. The journal reads: \"It rests in the shadows of the harsh Gorgrond sun. I saw some under standing stones near the black iron walls.\"", ["objectivesText"] = "Follow the clue from the journal to find the Shadethisle Leaves.", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 116268, 119093, 122145, 122147, 122150 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[37943] = { ["id"] = 37943, ["name"] = "The Silent Skull: The Second Reagent", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 37943 }, ["series"] = { 37941, 37942, 37944, 37945 }, ["description"] = "The second ingredient to the elixir is a vine from the Bonethorn plant. The journal reads: \"I must find a vine of bonethorn, which grows in the bones of the ancient dead. I remember seeing the bones of a long-dead beast in the dry beds of the northern wilds. Its sun-parched skull would make a pleasant home for such a plant.\"", ["objectivesText"] = "Follow the clue from the journal to find the Bonethorn Vine .", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 116268, 119093, 122144, 122147, 122150 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[37944] = { ["id"] = 37944, ["name"] = "The Silent Skull: The Third Reagent", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 37944 }, ["series"] = { 37941, 37942, 37943, 37945 }, ["description"] = "The final component of the elixir is a handful of Steamcap mushrooms . The journal reads: \"The Crowfeeder said that they grow among the steam vents in the higher parts of the Everbloom. I have seen one such place above the northern hydra pools.\"", ["objectivesText"] = "Follow the clue from the journal to find the Steamcap Mushrooms .", ["rewardGold"] = 77400, ["rewardXP"] = 1365, ["rewardItems"] = { 116268, 119093, 122146, 122147, 122150 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[37945] = { ["id"] = 37945, ["name"] = "The Silent Skull: Taking from the Taker", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6721, ["storyline"] = { 37945 }, ["series"] = { 37941, 37942, 37943, 37944 }, ["description"] = "With the reagents found, you should seek out Grinning Tolg's camp in the nearby cave to brew the elixir. Once the elixir is consumed, you should be able to communicate with the ravagers there. With any luck, they should be able to bring you to Skulltaker. His mask should bring a hefty reward.", ["objectivesText"] = "Use the Laughing Skull elixir to find Skulltaker and claim the Silent Skull . Progress: This must be the cursed skull. Are you sure we should be touching it?", ["rewardGold"] = 1653920, ["rewardXP"] = 1365, ["rewardItems"] = { 116268, 119093, 122147, 122150 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6721 } }, ["questType"] = "standard" },
