[38299] = { ["id"] = 38299, ["name"] = "Critters of Draenor", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 38299 }, ["description"] = "I love collecting pets, and I've picked up a few unusual pets here in Draenor. What would you say to a battle? If you can defeat my humble team, I think we'll both learn a few new tricks.", ["objectivesText"] = "Defeat Erris the Collector in a pet battle. Progress: Are we going to battle or what?", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 104295, 116429, 122532, 122533, 122534, 122535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
