[38449] = { ["id"] = 38449, ["name"] = "Assault on the Temple of Sha'naar", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38449 }, ["description"] = "Up in the hills of Tanaan Jungle , the Sargerei have converted a once-sacred temple into a den of demonic summoning. We must attack them now, before their rituals complete. The longer we delay, the stronger our enemy grows.", ["objectivesText"] = "Assault the Sargerei forces at the Temple of Sha'naar in Tanaan Jungle . Progress: How goes the attack, sir?", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 90481, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
