[38599] = { ["id"] = 38599, ["name"] = "Infrastructure Improvements", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38599 }, ["description"] = "<Sir/Ma'am>, we built a vehicle to take ya up to the Throne of Kil'jaeden but whenever we try a test flight the navigation system goes crazy! In my expert opinion it's 'cause of that crazy demon magic the Iron Horde is playing around with up there. If you could travel up there and place these telemetry beacons we can program the vehicle and give you a stable flight all the way up. Just be sure to have some friends with you, the demons up there look especially vicious!", ["objectivesText"] = "Place 5 G-X3 Telemetry Beacons .", ["rewardGold"] = 561800, ["rewardXP"] = 1365, ["rewardItems"] = { 119093 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90991, ["x"] = 0.598, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90991, ["x"] = 0.598, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "group" },
[38603] = { ["id"] = 38603, ["name"] = "Setting the Signal", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38603 }, ["description"] = "<Sir/Ma'am>, we built a vehicle to bypass the Horde camp and take you to the Throne of Kil'jaeden! There's one problem, the concentrated fel energy up there is causing the navigation system to go haywire! I'll need you to place some sensors along the edge of the summit. With them in place we can stabilize the flight controls. Just be sure to have some friends with you, the demons up there look especially vicious!", ["objectivesText"] = "Place 5 Pentangulate-o-tron 2000s .", ["rewardGold"] = 561800, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 92545, ["x"] = 0.58, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 92545, ["x"] = 0.58, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "group" },
[38633] = { ["id"] = 38633, ["name"] = "Burning Importance", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["storyline"] = { 38633 }, ["description"] = "Champion, you would not believe the horrors I have seen. The timeline is twisting and your fate is dire. Causality bends at its very knees, and in this dire future you kneel to the Betrayer himself, Illidan Stormrage. Venture into the past and save yourself, but beware - your powers are as they were then.", ["objectivesText"] = "Save yourself by completing a Timewalking Dungeon.", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
