[39175] = { ["id"] = 39175, ["name"] = "Gems of the Apexis", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 39175 }, ["series"] = { 39176, 39177, 39195 }, ["description"] = "Listen, boss. I know you're a jewelcrafter. It's OK, I totally understand - I like money, too! I heard some of them bird fellas talking about some new gem-cuttin' device they got up in Tanaan. I'd be interested in checkin' it out myself, but I've got this whole shipyard mess to deal with right now.", ["objectivesText"] = "Find Sun-Sage Chakkis in Tanaan Jungle.", ["rewardGold"] = 5865, ["rewardXP"] = 685, ["rewardItems"] = { 127760, 127761, 127762, 127763, 127764, 127765, 127771, 127772, 127773, 127774, 127775 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 94686, ["x"] = 0.258, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 525, 534 }, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[39176] = { ["id"] = 39176, ["name"] = "Mastery Of Taladite", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39176 }, ["series"] = { 39175, 39177, 39195 }, ["description"] = "You - you are a gemcutter, no? You have the look of it in the twitch of your knuckles, in the focus of your eyes. I've been looking for something specific out here in Tanaan. We did not find it in our excavations in Arak... but the Apexis did not only dwell in Arak. What I am looking for is a storied Apexis construct that specialized in cutting gems. Be on the lookout, jewelcrafter. Such a marvel could benefit the both of us.", ["objectivesText"] = "Find the Apexis Gemcutting Construct.", ["rewardXP"] = 1365, ["rewardItems"] = { 127760, 127761, 127762, 127763, 127764, 127765, 127771, 127772, 127773, 127774, 127775 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 94686, ["x"] = 0.258, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 94605, ["x"] = 0.258, ["y"] = 0.399 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39177] = { ["id"] = 39177, ["name"] = "Ruined Construct", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39177 }, ["series"] = { 39175, 39176, 39195 }, ["description"] = "<It is in disrepair, but it is not broken. More than anything, the construct appears to be in need of re-energizing.> <A slot on the backside of the machine lies open, waiting to accept... whatever the Apexis used as a source of energy.>", ["objectivesText"] = "Repair the Apexis Gemcutter Construct by inserting 1000 Apexis Crystals.", ["rewardItems"] = { 127760, 127761, 127762, 127763, 127764, 127765, 127771, 127772, 127773, 127774, 127775 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 94605, ["x"] = 0.258, ["y"] = 0.399 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 94686, ["x"] = 0.258, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.399 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39195] = { ["id"] = 39195, ["name"] = "Gems of the Apexis", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 534, ["storyline"] = { 39195 }, ["series"] = { 39175, 39176, 39177 }, ["description"] = "Commander! I've noticed you have been keeping up with your jewelcrafting, despite all of this war going on. I find that to be most admirable. I overheard some of the arakkoa discussing a gemcutting device that they believe is located within Tanaan Jungle. They got their information from one named \"Chakkis.\" Just thought you might be interested.", ["objectivesText"] = "Find Sun-Sage Chakkis in Tanaan Jungle.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 94686, ["x"] = 0.258, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[39210] = { ["id"] = 39210, ["name"] = "The Magical Kingdom of Dalaran", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 4395, ["storyline"] = { 39210 }, ["series"] = { 12790, 12791, 12794, 12796 }, ["description"] = "The Kirin Tor have moved their city here to Northrend. No longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest. They believe you to be ready for your journey to the city. Look for the teleportation crystal in Crystal Song Forest. When you arrive, seek out Archmage Celindra .", ["objectivesText"] = "Report to Archmage Celindra at The Violet Gate in Dalaran .", ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[39221] = { ["id"] = 39221, ["name"] = "Pits of Mannoroth", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 39221 }, ["description"] = "In the Hellfire Citadel , they work to corrupt a magnaron with fel energy within the Pits of Mannoroth. If you delve into the fel pools of that place, be on your guard.", ["objectivesText"] = "Defeat Kormrok in Hellfire Citadel .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[39225] = { ["id"] = 39225, ["name"] = "Maw of Souls", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 39225 }, ["description"] = "Falling into the heart of the mausoleum in Auchindoun, Teron'gor gorged upon hundreds of draenei souls, becoming a bloated abomination in the process. No longer recognizable as an orc, Teron'gor gave up his old name and has taken on the mantle of Gorefiend.", ["objectivesText"] = "Defeat Gorefiend in Hellfire Citadel .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 136350, 140618, 140619, 140620, 140621, 237812, 246936, 249400, 251821, 254267, 254579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[39228] = { ["id"] = 39228, ["name"] = "Temple of Tyranny", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 39228 }, ["description"] = "Tyrant Velhari was once a promising vindicator, but has turned to Shadow for reasons known only to her. Purge this Eredar of darkness.", ["objectivesText"] = "Defeat Tyrant Velhari in Hellfire Citadel .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[39231] = { ["id"] = 39231, ["name"] = "Destructor's Rise", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 39231 }, ["description"] = "We believed we were done with Mannoroth, at least for a time. But Gul'dan is more powerful than we had predicted. Mannoroth is nearly back in this world. His bones have been seen within the citadel, and he must be destroyed before he can reach his full power.", ["objectivesText"] = "Defeat Mannoroth in Hellfire Citadel .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[39232] = { ["id"] = 39232, ["name"] = "The Black Gate", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 39232 }, ["description"] = "We have heard rumors that one of the strongest of the eredar could soon enter this world through the Black Gate. If these rumors are to be believed, it could even be Archimonde the Defiler. Should he arrive uncontested, Draenor itself is likely to fall.", ["objectivesText"] = "Defeat Archimonde in Hellfire Citadel .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "raid" },
[39250] = { ["id"] = 39250, ["name"] = "Pits of Mannoroth", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39250 }, ["description"] = "In the Hellfire Citadel , they're corruptin' a magnaron with fel energy in the Pits o' Mannoroth. If ye delve into the fel pools of that place, be on yer guard.", ["objectivesText"] = "Defeat Kormrok in Hellfire Citadel .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "raid" },
[39253] = { ["id"] = 39253, ["name"] = "Maw of Souls", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39253 }, ["description"] = "Falling into the heart o' the mausoleum in Auchindoun, Teron'gor gorged upon hundreds o' draenei souls, becoming a bloated abomination in the process. No longer recognizable as an orc, Teron'gor gave up his old name and has taken on the mantle of Gorefiend.", ["objectivesText"] = "Defeat Gorefiend in Hellfire Citadel . Progress: I hope you make Gorefiend pay for his atrocities.", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["rewardItems"] = { 136350, 140618, 140619, 140620, 140621, 237812, 246936, 249400, 251821, 254267, 254579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "raid" },
