[39260] = { ["id"] = 39260, ["name"] = "The Black Gate", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39260 }, ["description"] = "We've heard rumors that one o' the strongest eredar might enter this world through the Black Gate soon. If these rumors are to be believed, it could even be Archimonde the Defiler. If he arrives unchallenged, Draenor itself is likely to fall.", ["objectivesText"] = "Defeat Archimonde in Hellfire Citadel .", ["rewardGold"] = 1123600, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "raid" },
[39278] = { ["id"] = 39278, ["name"] = "The Missing Manifest", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 39278 }, ["description"] = "The water-proofed manifest contains some form of code for the most part, hiding the contents of the actual manifest. In the corner is a hastily scrawled note for a Mr. Knuckles. \"Shipment attacked, got away but boat is sinking. Get here before they do.\" There are coordinates after that which lead to the sunken boat. Mr. Knuckles is definitely the kind of person you want owing you a favor, not the other way around.", ["objectivesText"] = "Find Mr. Knuckles' missing shipment. Progress: Whatchoo got there?", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 119093, 127669, 127989, 128027 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 83888, ["x"] = 0.538, ["y"] = 0.15 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.15 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["startItems"] = { 127989 } },
