[39292] = { ["id"] = 39292, ["name"] = "Ashran Dominance", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6941, ["storyline"] = { 39292 }, ["description"] = "The Alliance refuse to back down in Ashran . Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.", ["objectivesText"] = "Defeat the Alliance at all event locations in Ashran and kill Grand Marshal Tremblade .", ["rewardXP"] = 200, ["rewardItems"] = { 126924 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6941 } }, ["questType"] = "standard" },
[39299] = { ["id"] = 39299, ["name"] = "Black Marketeering", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 39299 }, ["description"] = "Ya did us a real solid today, <name>. Boss Goya says you're big stuff in dese parts and we should keep an eye on --- uh, I mean we should be good buds. She's sent a repre... repre... del-e-g... um, a Black Market person to your garrison. Go say hi and stuff, and make sure to speak loudly when you plan what you're gonna do next.", ["objectivesText"] = "Speak with Zhang Yeoh in your garrison.", ["rewardItems"] = { 127989 }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 83888, ["x"] = 0.538, ["y"] = 0.15 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.15 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[39313] = { ["id"] = 39313, ["name"] = "Bring the Reinforcements", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39313 }, ["description"] = "Greetings, Commander! With all of the fighting concentrated here in Tanaan, we've got the breathing room to divert some of our resources from nearby outposts to help make headway. Just let me know which reinforcements to call, and I'll get them here on the double!", ["objectivesText"] = "Talk to Angar Steelbellow and choose which reinforcements to bring to Tanaan. Progress: Which allies should I call for?", ["rewardGold"] = 210675, ["rewardXP"] = 4100, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90963, ["x"] = 0.58, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90963, ["x"] = 0.58, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39315] = { ["id"] = 39315, ["name"] = "Bring the Reinforcements", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39315 }, ["description"] = "Hey there, Commander. You know, with all of the fighting concentrated here in Tanaan, we've got plenty of extra supplies just sitting around in our nearby outposts. You just give me the order and I'll make sure some of them get sent our way!", ["objectivesText"] = "Talk to Fraggs and choose which reinforcements to bring to Tanaan.", ["rewardGold"] = 232300, ["rewardXP"] = 4100, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90993, ["x"] = 0.598, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90993, ["x"] = 0.598, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
