[39432] = { ["id"] = 39432, ["name"] = "Unknowable Power", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39432 }, ["description"] = "The one they call Gul'dan has ruined his own people, and now seeks to ruin what remains of mine as well. The fallen outcasts at Kra'nak have already pledged themselves to Gul'dan in a false promise of a return to the skies. He has given the most powerful of his minions the power of the Apexis, but twisted in a way that I cannot explain. Bring one of these fragments to me.", ["objectivesText"] = "Collect a Fel-Corrupted Apexis Fragment from any Treasure or from any Rare or Rare Elite creature in Tanaan Jungle . Progress: This is simply the beginning of what you must do to save what remains of the Arakkoa.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 128346 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 95424, ["x"] = 0.591, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 95424, ["x"] = 0.591, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.591, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "group" },
[39433] = { ["id"] = 39433, ["name"] = "Unseen Influence", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39433 }, ["description"] = "The corruption in the Apexis has begun to affect many of my people. We are so accustomed to the power it grants us that more succumb to the whispers every day. You must bring me more samples so I can free my people from yet another curse.", ["objectivesText"] = "Collect 10 Fel-Corrupted Apexis Fragments from any Treasure or from any Rare or Rare Elite creature in Tanaan Jungle . Progress: I fear even your help may not be enough to avert the doom of the Arakkoa.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 93730, 119093, 124093, 124094, 124095, 124099, 128315, 128346, 128502, 128503 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 95424, ["x"] = 0.591, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 95424, ["x"] = 0.591, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.591, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "group" },
