[39659] = { ["id"] = 39659, ["name"] = "A Winter Veil Gift", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Feast of Winter Veil", ["expansion"] = 5, ["zoneID"] = 1637, ["storyline"] = { 39659 }, ["rewardItems"] = { 34426, 43504, 46740, 67443, 70938, 90892, 104319, 108632, 116761, 128653, 139341, 151350, 162644, 172224, 178528, 187561, 192094, 209871, 218311, 244908 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[39665] = { ["id"] = 39665, ["name"] = "A True Naval Commander", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 39666 }, ["description"] = "Yes! Those are the blueprints I misplaced when I was fishing last week. These instructions match my prototype equipment one for one. Take this Blast Furnace and install it on one of our ships. This should let us break the naval blocade and expand our control of the Draenor seas.", ["objectivesText"] = "Install the Blast Furnace equipment on your ship and complete the Naval Blockade mission. Progress: Get that equipment installed?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 126900, 127882, 127884, 128256, 128260, 128264, 128265, 128373 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93812, ["x"] = 0.286, ["y"] = 0.108 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.286, ["y"] = 0.108 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 15, ["flags"] = 0 } } },
[39668] = { ["id"] = 39668, ["name"] = "What Horrible Presents!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Feast of Winter Veil", ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 39668 }, ["description"] = "That mean old Grumpus has amassed a collection of odd gifts. He's deliberately trying to crush the spirit of children everywhere by giving out the worst presents imaginable. Take this spirit bomb . Toss it on some of Grumpus's unusual gifts and take them out for good! We're in this together, <name>. Now go and save the spirit of the holiday!", ["objectivesText"] = "Destroy 5 Unusual Gifts . Progress: Wow. Those were some nasty presents. You might want to, uh... wash up. Who knows what those were made of.", ["rewardGold"] = 341600, ["rewardXP"] = 1365, ["rewardItems"] = { 21524, 21525, 34085, 34087, 70923, 108635, 128312, 128314, 128315, 128658, 128659, 128665, 128666, 128667, 128668, 128669, 128670, 128671, 128675 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[39697] = { ["id"] = 39697, ["name"] = "Master vs. Commander", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["mapID"] = 525, ["storyline"] = { 39697 }, ["series"] = { 39057 }, ["description"] = "I've been doing a little digging - or whatever you call digging in naval terms. Snorkeling? Gul'dan has sent his most powerful flagship on a scouting mission to the four corners of Draenor. He is mapping out all the oceanic ley-line conjunctions. This is information that I could use to upgrade your ring... But in Gul'dan's hands, it could be catastrophic. Scramble the fleet, <name>! Hunt down his infamous flagship, \"The Master's Call,\" and steal that map before they complete their mission. Hurry!", ["objectivesText"] = "Complete the legendary shipyard missions until you defeat the Master's Call and acquire a Draenic Sea Chart . Progress: I hope the Master's Call hasn't sent too many of your ships to the bottom of the sea...?", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 128693 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[39716] = { ["id"] = 39716, ["name"] = "Smashing Squashlings", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39716 }, ["description"] = "The Bonefleet once raided trading ships traveling the waters of Draenor. One such ship carried farming supplies intended for Elodor. Now, they use these supplies to sow their plague into our earth. From the putrid mounds sprout vegetative horrors. These abominations must be destroyed, before they can spread across the landscape.", ["objectivesText"] = "Kill 6 Growing Squashlings .", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 20397, 20398, 20399, 20411, 33226, 62675, 86125, 104316, 120150, 128658, 128660, 128661, 128662, 128663, 128664, 128794, 128807 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[39719] = { ["id"] = 39719, ["name"] = "Mutiny on the Boneship", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39719 }, ["description"] = "Each year, around this time, there is a strange surge of spiritual energy across Draenor. Beckoned by this phenomenon, a ghastly fleet of undead pirates emerges from the mist. We call it the Bonefleet. The Bonefleet is led by a savage pirate known as Bonerender. He seeks nothing more than the complete destruction of all of the living of Draenor. Seek out Bonerender and defeat him, before he sails back into the mist once again.", ["objectivesText"] = "Kill Bonerender.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 20397, 20398, 20399, 20411, 33226, 62675, 86125, 104316, 120150, 128658, 128660, 128661, 128662, 128663, 128664, 128794, 128807 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "group", ["db2LabelIDs"] = { 2764 } },
[39720] = { ["id"] = 39720, ["name"] = "Foul Fertilizer", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39720 }, ["description"] = "The Bonefleet wants nothing more than to spread their undead curse onto dry land. Like a sickness, it will slowly overtake the landscape if left unchecked. The stench of undeath permeates the barrels of fertilizer they use to sow their dread crops. They are the source of the spreading plague, and must be destroyed.", ["objectivesText"] = "Destroy 8 kegs of Dread Fertilizer .", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 20397, 20398, 20399, 20411, 33226, 62675, 86125, 104316, 120150, 128658, 128660, 128661, 128662, 128663, 128664, 128794, 128807 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[39721] = { ["id"] = 39721, ["name"] = "Culling the Crew", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 39721 }, ["description"] = "If we're going to protect Draenor from the Bonefleet menace, we'll need to thin out the crew. See to a swift reduction in their numbers, and we might just push them back into the sea for another year.", ["objectivesText"] = "Destroy 12 Boneship crew members.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 20397, 20398, 20399, 20411, 33226, 62675, 86125, 104316, 120150, 128658, 128660, 128661, 128662, 128663, 128664, 128794, 128807 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[40168] = { ["id"] = 40168, ["name"] = "The Swirling Vial", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "weekly", "repeatable", "loremaster" }, ["sharable"] = false, ["event"] = "Outland Timewalking Dungeon Event", ["expansion"] = 5, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 40168 }, ["description"] = "As you touch the vial, your mind is flooded with memories, not all of which are your own. The most vivid is a memory of exchanging a similar vial with someone in Shattrath, with A'dal's light shining behind you. Despite your best efforts however, you can't pinpoint when that might have been - maybe it hasn't been, and is yet to be?", ["objectivesText"] = "Bring the Swirling Timewarped Vial to the central dome in Shattrath.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 19971, 33816, 33818, 33820, 33844, 33857, 33869, 33870, 33871, 33873, 33875, 33925, 34109, 34834, 34836, 35348, 35349, 35350, 43007, 44113, 44228, 44983, 45984, 45991, 45992, 46007, 49602, 50362, 67414, 122338, 122339, 122340, 122341, 127669, 129747, 129857, 129922, 129923, 129926, 129928, 129929, 129938, 129940, 129941, 129942, 129943, 129944, 129945, 129946, 129947, 129948, 129949, 129950, 129951, 129952, 129954, 129955, 129965, 133150, 133151, 133152, 133154, 133159, 133160, 133377, 133378, 133511, 133542, 133543, 133545, 143776, 167921, 167922, 187611, 225348 }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 98685, ["x"] = 0.545, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard", ["startItems"] = { 129747 } },
[40173] = { ["id"] = 40173, ["name"] = "The Unstable Prism", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "weekly", "repeatable", "loremaster" }, ["sharable"] = false, ["event"] = "Northrend Timewalking Dungeon Event", ["expansion"] = 5, ["zoneID"] = 4395, ["storyline"] = { 40173 }, ["description"] = "As the prism struggles to stabilize in a single time flow, it bleeds a shadowy chill, the likes of which you haven't felt since Northrend. Surely some mage in Dalaran would be interested in this relic.", ["objectivesText"] = "Deliver the Frigid Timewarped Prism to an interested mage in Dalaran .", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 19971, 33816, 33818, 33820, 33844, 33857, 33869, 33870, 33871, 33873, 33875, 33925, 34109, 34834, 34836, 35348, 35349, 35350, 43007, 44113, 44228, 44935, 44983, 45984, 45991, 45992, 46007, 49602, 50362, 67414, 122338, 122339, 122340, 122341, 127669, 129747, 129857, 129922, 129923, 129926, 129928, 129929, 129938, 129940, 129941, 129942, 129943, 129944, 129945, 129946, 129947, 129948, 129949, 129950, 129951, 129952, 129954, 129955, 129965, 133150, 133151, 133152, 133154, 133159, 133160, 133377, 133378, 133511, 133542, 133543, 133545, 143776, 167921, 167922, 187611, 225348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard", ["startItems"] = { 129928 } },
[40235] = { ["id"] = 40235, ["name"] = "Abrogator Arbitrator", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 40235 }, ["description"] = "Da bums in Highmaul refuse to see dey are on da way out. Me, I'm gettin' while da gettin' is good. Da sooner youse bring me a bunch of Apexis Crystals , da sooner I can get off dis stupid island. Da amount required is very precise!", ["objectivesText"] = "Kluk'kluk wants you to bring him 14958 Apexis Crystals . Progress: I can feel da power of da crystals! Give dem to me!", ["rewardXP"] = 1365, ["rewardItems"] = { 115280, 115981 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 99180, ["x"] = 0.583, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 99180, ["x"] = 0.583, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.583, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[40237] = { ["id"] = 40237, ["name"] = "Work Work Stoppage", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 40237 }, ["description"] = "We've had enough! The working conditions in the Foundry are intolerable with all the fire and the ogron and the flames and the fire elementals and infernos and marauding adventurers! But especially the heat. I've had enough! Me and the boys are going to start a work stoppage but we need to hire some security muscle and the only goon from Highmaul I could get to agree to the job only takes payment in Apexis Crystals .", ["objectivesText"] = "Bring 20000 Apexis Crystals to the Renegade Ironworker . Progress: It's a good thing you took care of Mar'gok or nobody would be available for hire. Ogre security is still effective, right?", ["rewardXP"] = 1365, ["rewardItems"] = { 115510, 123974 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 99183, ["x"] = 0.586, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 99183, ["x"] = 0.586, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[40329] = { ["id"] = 40329, ["name"] = "Battle Pet Tamers: Warlords", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 40329 }, ["description"] = "You have proven yourself before but the wilds of Draenor are on another level. Defeat tamers in the wilds to prove your pet battle supremacy: Cymre Brightblade in Gorgrond, Vesharr in Spires of Arak, Tarr the Terrible in Nagrand, Taralune in Talador, Gargra in Frostfire Ridge, or Ashlei in Shadowmoon Valley. You can also defeat a visiting tamer: Erris the Collector or Kura Thunderhoof in your garrison. By defeating them will show your dominance in Draenor.", ["objectivesText"] = "Defeat 5 pet battle trainers in Draenor. Progress: Have you been able to defeat most of the tamers?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 116429, 120050, 120051, 140590 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[40418] = { ["id"] = 40418, ["name"] = "To Tanaan!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 40418 }, ["series"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259 }, ["description"] = "It is vital that you set your focus on Tanaan Jungle and establish a foothold there, before you are distracted with other matters. The King is ready for you inside your town hall along with his full retinue. It would be wise not to keep him waiting...", ["objectivesText"] = "Speak with King Varian Wrynn inside the Town Hall of your garrison.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 94219 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 92219, ["x"] = 0.276, ["y"] = 0.102 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.102 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[40786] = { ["id"] = 40786, ["name"] = "The Smoldering Ember", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "weekly", "repeatable", "loremaster" }, ["sharable"] = false, ["event"] = "Cataclysm Timewalking Dungeon Event", ["expansion"] = 5, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40786 }, ["description"] = "Cold to the touch when you first reach for it, this ember bursts into flame without warning and snuffs itself just as quickly. As the stone rests in your hand, visions of fire and of dragons dance through your mind, but you can hear conversation taking place in Orgrimmar and the familiar sight of circle portals bubbles to the top.", ["objectivesText"] = "Bring the Smoldering Timewarped Ember to Kiatke in Orgrimmar .", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 19971, 33816, 33818, 33820, 33844, 33857, 33869, 33870, 33871, 33873, 33875, 33925, 34109, 34834, 34836, 35348, 35349, 35350, 43007, 44113, 44228, 44983, 45984, 45991, 45992, 46007, 49602, 50362, 67414, 122338, 122339, 122340, 122341, 127669, 129747, 129857, 129922, 129923, 129926, 129928, 129929, 129938, 129940, 129941, 129942, 129943, 129944, 129945, 129946, 129947, 129948, 129949, 129950, 129951, 129952, 129954, 129955, 129965, 133150, 133151, 133152, 133154, 133159, 133160, 133377, 133378, 133511, 133542, 133543, 133545, 143776, 167921, 167922, 187611, 225348 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 101759, ["x"] = 0.762, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["startItems"] = { 133377 } },
[40787] = { ["id"] = 40787, ["name"] = "The Smoldering Ember", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "weekly", "repeatable", "loremaster" }, ["sharable"] = false, ["event"] = "Cataclysm Timewalking Dungeon Event", ["expansion"] = 5, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40787 }, ["description"] = "Cold to the touch when you first reach for it, this ember bursts into flame without warning and snuffs itself just as quickly. As the stone rests in your hand, visions of fire and of dragons dance through your mind, but you can hear the hustle and bustle of Stormwind and the familiar sight of circle portals bubbles to the top.", ["objectivesText"] = "Bring the Smoldering Timewarped Ember to Kiatke in Stormwind.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 19971, 33816, 33818, 33820, 33844, 33857, 33869, 33870, 33871, 33873, 33875, 33925, 34109, 34834, 34836, 35348, 35349, 35350, 43007, 44113, 44228, 44983, 45984, 45991, 45992, 46007, 49602, 50362, 67414, 122338, 122339, 122340, 122341, 127669, 129747, 129857, 129922, 129923, 129926, 129928, 129929, 129938, 129940, 129941, 129942, 129943, 129944, 129945, 129946, 129947, 129948, 129949, 129950, 129951, 129952, 129954, 129955, 129965, 133150, 133151, 133152, 133154, 133159, 133160, 133377, 133378, 133511, 133542, 133543, 133545, 143776, 167921, 167922, 187611, 225348 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 101759, ["x"] = 0.762, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["startItems"] = { 133378 } },
[40792] = { ["id"] = 40792, ["name"] = "A Shattered Path Through Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 5, ["zoneID"] = 7078, ["storyline"] = { 40792 }, ["description"] = "The Destroyer's star shines upon the land with its piercing light as even the spirits retreat to the shadows. This star is unlike any other in the skies, laying bare the weaknesses of even the boldest heroes. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: Follow the Destroyer's star, and walk the paths it reveals.", ["rewardItems"] = { 127853, 129946, 129965, 133543, 226193, 226194, 247821, 250116 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
