[40904] = { ["id"] = 40904, ["name"] = "Shadow of the Defiler", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 40904 }, ["description"] = "Crimson energy swirls within this disturbing object, which seems to have slightly different contours each time your gaze returns to it. Its power is utterly foreign, unlike anything you have seen in Draenor or during your battles with the Legion. Perhaps the keepers of Moonglade, back on Azeroth, might have some insight into its nature.", ["objectivesText"] = "Consult the keepers of Moonglade to see if they can shed any light on the nature of the Remnant of Chaos . Progress: I have heard of your deeds beyond the red portal, <name>. Two worlds owe you and your companions a great debt. What brings you to the Moonglade?", ["rewardXP"] = 1365, ["rewardItems"] = { 20644, 123890, 128422, 133762 }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 102432, ["x"] = 0.364667, ["y"] = 0.415333 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.415333 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["startItems"] = { 133762 } },
[40941] = { ["id"] = 40941, ["name"] = "Missive: Assault on the Pit", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 40941 }, ["description"] = "The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us. If you choose the battle, bring friends. The Blackrock won't be defeated easily.", ["objectivesText"] = "Assault the Blackrock forces at the Pit in Gorgrond.", ["rewardGold"] = 679200, ["rewardXP"] = 1365, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group", ["startItems"] = { 133876 } },
