[40943] = { ["id"] = 40943, ["name"] = "Missive: Assault on the Heart of Shattrath", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 5, ["zoneID"] = 7004, ["storyline"] = { 40943 }, ["description"] = "Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose. Bring allies if you wish to face the Sargerei so deep within the city.", ["objectivesText"] = "Assault the Sargerei force in Shattrath City in Talador.", ["rewardGold"] = 679200, ["rewardXP"] = 1365, ["rewardItems"] = { 251547 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "group", ["startItems"] = { 133884 } },
